def _build_prompt353_runtime_verification_planning_artifact_bundle(
    *,
    execution_repo_path: str,
    one_cycle_controller_dir: Path,
    local_autonomous_cycle_v2_decision: Mapping[str, Any] | None,
) -> dict[str, dict[str, Any]]:
    command_summary: dict[str, Any] = {}
    cycle_v2_decision_payload = (
        dict(local_autonomous_cycle_v2_decision)
        if isinstance(local_autonomous_cycle_v2_decision, Mapping)
        else {}
    )
    detected_branch = ""
    normalized_repo_path = _normalize_text(execution_repo_path, default="")
    if normalized_repo_path:
        try:
            detected_branch = _resolve_current_branch(
                normalized_repo_path,
                command_summary=command_summary,
            )
        except (OSError, subprocess.SubprocessError):
            detected_branch = ""
    target_branch = detected_branch or "local/prompt299-one-cycle-controller-v1"
    target_repo = (
        Path(normalized_repo_path).name
        if normalized_repo_path
        else "codex-local-runner"
    )
    target_repo = _normalize_text(target_repo, default="codex-local-runner")
    run_id = _normalize_text(
        cycle_v2_decision_payload.get("run_id"),
        default="prompt353-runtime-verification",
    )
    objective_summary = "Prompt353 local autonomous ordering repair runtime verification"
    requested_outcome = (
        "Verify that the local autonomous one-cycle controller can run past "
        "Prompt333/Prompt334/Prompt335 ordering without "
        "local_targeted_contract_fix_prompt_state UnboundLocalError and without selecting "
        "the stale Prompt167 smoke objective fallback."
    )
    acceptance_criteria = [
        "No UnboundLocalError or Traceback for local_targeted_contract_fix_prompt_state.",
        "Prompt333 current-run execution artifacts are produced or explicitly accounted before Prompt334/335 downstream artifacts are built.",
        "Prompt334/335/336-342 downstream surfaces use current-run or reconciled state, or block with an explicit current-run reason.",
        "The planned step contract is explicitly bounded, local-only, and manual-review-safe.",
    ]
    in_scope = [
        "automation/orchestration/planned_execution_runner.py",
        str(one_cycle_controller_dir),
    ]
    out_of_scope = [
        "GitHub write operations",
        "push",
        "PR creation",
        "merge",
        "rollback execution",
        "unbounded retry loops",
        "scheduler or daemon behavior",
    ]
    risk_tier = "local_only_bounded_manual_review_safe"
    validation_command = (
        "python -m py_compile automation/orchestration/planned_execution_runner.py "
        "scripts/run_planned_execution.py "
        "automation/orchestration/objective_contract.py "
        "automation/planning/project_planner.py "
        "automation/planning/planned_step_contract.py "
        "automation/planning/prompt_compiler.py"
    )
    pr_id = "prompt353-local-autonomous-ordering-runtime-verification"

    return {
        "project_brief": {
            "project_id": run_id,
            "project_name": target_repo,
            "objective": objective_summary,
            "summary": requested_outcome,
            "success_definition": requested_outcome,
            "target_repo": target_repo,
            "target_branch": target_branch,
            "task_type": "runtime_verification",
            "allowed_risk_level": risk_tier,
            "constraints": [
                "Local-only verification path.",
                "Bounded single verification run only.",
                "Manual-review-safe posture only.",
            ],
            "non_goals": list(out_of_scope),
        },
        "repo_facts": {
            "repo": target_repo,
            "default_branch": target_branch,
            "relevant_paths": list(in_scope),
            "build_commands": [validation_command],
        },
        "roadmap": {
            "roadmap_id": f"{pr_id}-roadmap",
            "estimated_risk": risk_tier,
            "items": [
                {
                    "id": pr_id,
                    "title": objective_summary,
                    "status": "ready",
                }
            ],
        },
        "pr_plan": {
            "plan_id": f"{pr_id}-plan",
            "estimated_risk": risk_tier,
            "prs": [
                {
                    "pr_id": pr_id,
                    "title": objective_summary,
                    "summary": requested_outcome,
                    "exact_scope": requested_outcome,
                    "touched_files": list(in_scope),
                    "forbidden_files": list(out_of_scope),
                    "acceptance_criteria": list(acceptance_criteria),
                    "validation_commands": [validation_command],
                    "rollback_notes": "Rollback execution remains out of scope for this local-only verification fallback.",
                    "tier_category": "local_only_bounded_manual_review_safe",
                    "depends_on": [],
                    "risk": risk_tier,
                    "status": "ready",
                }
            ],
        },
    }

def _build_prompt355_local_autonomous_continuation_readiness_surface(
    *,
    run_state_payload: Mapping[str, Any],
    planning_artifacts: Mapping[str, Any] | None,
    completion_contract_payload: Mapping[str, Any] | None,
    execution_authorization_gate_payload: Mapping[str, Any] | None,
    bounded_execution_bridge_payload: Mapping[str, Any] | None,
    verification_closure_contract_payload: Mapping[str, Any] | None,
    endgame_closure_contract_payload: Mapping[str, Any] | None,
) -> dict[str, Any]:
    run_state = dict(run_state_payload or {})
    planning_bundle = dict(planning_artifacts or {})
    completion = dict(completion_contract_payload or {})
    execution_authorization = dict(execution_authorization_gate_payload or {})
    bounded_execution = dict(bounded_execution_bridge_payload or {})
    verification = dict(verification_closure_contract_payload or {})
    endgame = dict(endgame_closure_contract_payload or {})

    def _read_text(*values: Any, default: str = "") -> str:
        for value in values:
            text = _normalize_text(value, default="")
            if text:
                return text
        return default

    def _as_boolish(value: Any, *, default: bool = False) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, int):
            return value != 0
        text = _normalize_text(value, default="").strip().lower()
        if text in {"1", "true", "yes", "on", "enabled"}:
            return True
        if text in {"0", "false", "no", "off", "disabled"}:
            return False
        return default

    def _is_clear_reason(value: Any) -> bool:
        return _normalize_text(value, default="").strip().lower() in {"", "none"}

    blocked_reasons: list[str] = []

    def _add_reason(condition: bool, reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if condition and normalized_reason and normalized_reason not in blocked_reasons:
            blocked_reasons.append(normalized_reason)

    verification_status = _read_text(
        verification.get("verification_status"),
        run_state.get("verification_status"),
    )
    verification_outcome = _read_text(
        verification.get("verification_outcome"),
        run_state.get("verification_outcome"),
    )
    verification_primary_reason = _read_text(
        verification.get("verification_primary_reason"),
        run_state.get("verification_primary_reason"),
    )
    closure_status = _read_text(
        verification.get("closure_status"),
        run_state.get("closure_status"),
    )
    safely_closable = _as_boolish(
        verification.get("safely_closable")
        if "safely_closable" in verification
        else run_state.get("safely_closable")
    )
    completion_status = _read_text(
        completion.get("completion_status"),
        run_state.get("completion_status"),
    )
    safe_closure_status = _read_text(
        completion.get("safe_closure_status"),
        run_state.get("safe_closure_status"),
    )
    execution_authorization_blocked_reason = _read_text(
        execution_authorization.get("execution_authorization_blocked_reason"),
        run_state.get("execution_authorization_blocked_reason"),
    )
    execution_authorization_manual_required = _as_boolish(
        execution_authorization.get("execution_authorization_manual_required")
        if "execution_authorization_manual_required" in execution_authorization
        else run_state.get("execution_authorization_manual_required")
    )
    execution_authorization_replan_required = _as_boolish(
        execution_authorization.get("execution_authorization_replan_required")
        if "execution_authorization_replan_required" in execution_authorization
        else run_state.get("execution_authorization_replan_required")
    )
    execution_authorization_primary_reason = _read_text(
        execution_authorization.get("execution_authorization_primary_reason"),
        run_state.get("execution_authorization_primary_reason"),
    )
    execution_authorization_binding_status = _read_text(
        execution_authorization.get("execution_authorization_binding_status"),
        run_state.get("execution_authorization_binding_status"),
    )
    execution_authorization_approval_status = _read_text(
        execution_authorization.get("execution_authorization_approval_status"),
        run_state.get("execution_authorization_approval_status"),
    )
    bounded_execution_blocked_reason = _read_text(
        bounded_execution.get("bounded_execution_blocked_reason"),
        run_state.get("bounded_execution_blocked_reason"),
    )
    bounded_execution_manual_required = _as_boolish(
        bounded_execution.get("bounded_execution_manual_required")
        if "bounded_execution_manual_required" in bounded_execution
        else run_state.get("bounded_execution_manual_required")
    )
    bounded_execution_replan_required = _as_boolish(
        bounded_execution.get("bounded_execution_replan_required")
        if "bounded_execution_replan_required" in bounded_execution
        else run_state.get("bounded_execution_replan_required")
    )
    bounded_execution_primary_reason = _read_text(
        bounded_execution.get("bounded_execution_primary_reason"),
        run_state.get("bounded_execution_primary_reason"),
    )
    bounded_execution_status = _read_text(
        bounded_execution.get("bounded_execution_status"),
        run_state.get("bounded_execution_status"),
    )
    bounded_execution_decision = _read_text(
        bounded_execution.get("bounded_execution_decision"),
        run_state.get("bounded_execution_decision"),
    )
    manual_closure_only = _as_boolish(
        endgame.get("manual_closure_only")
        if "manual_closure_only" in endgame
        else run_state.get("manual_closure_only")
    )
    prompt167_smoke_fallback_active = bool(
        _planning_artifact_bundle_is_prompt167_smoke_placeholder(planning_bundle)
        or _planning_artifact_bundle_is_incomplete_prompt167_smoke_placeholder(planning_bundle)
    )
    local_targeted_contract_fix_prompt_lifecycle_issue_detected = _as_boolish(
        run_state.get("local_targeted_contract_fix_prompt_lifecycle_issue_detected")
    )
    local_targeted_contract_fix_route_intake_blocked_reason = _read_text(
        run_state.get("local_targeted_contract_fix_route_intake_blocked_reason"),
    )
    local_targeted_contract_fix_prompt_plan_blocked_reason = _read_text(
        run_state.get("local_targeted_contract_fix_prompt_plan_blocked_reason"),
    )
    local_targeted_contract_fix_prompt_normalized_reason = _read_text(
        run_state.get("local_targeted_contract_fix_prompt_normalized_reason"),
    )

    _add_reason(
        verification_status != "verified_success",
        "verification_status_not_verified_success",
    )
    _add_reason(
        verification_outcome != "objective_satisfied",
        "verification_outcome_not_objective_satisfied",
    )
    _add_reason(
        closure_status != "safely_closable",
        "closure_status_not_safely_closable",
    )
    _add_reason(
        not safely_closable,
        "safely_closable_false",
    )
    _add_reason(
        completion_status != "done_and_safely_closed",
        "completion_status_not_done_and_safely_closed",
    )
    _add_reason(
        safe_closure_status != "safely_closed",
        "safe_closure_status_not_safely_closed",
    )
    _add_reason(
        not _is_clear_reason(execution_authorization_blocked_reason),
        "execution_authorization_blocked_reason_present",
    )
    _add_reason(
        not _is_clear_reason(bounded_execution_blocked_reason),
        "bounded_execution_blocked_reason_present",
    )
    _add_reason(
        execution_authorization_manual_required,
        "execution_authorization_manual_required",
    )
    _add_reason(
        bounded_execution_manual_required,
        "bounded_execution_manual_required",
    )
    _add_reason(
        execution_authorization_binding_status not in {"", "none", "not_needed"},
        "execution_authorization_binding_status_not_not_needed",
    )
    _add_reason(
        execution_authorization_approval_status not in {"", "none", "not_needed"},
        "execution_authorization_approval_status_not_not_needed",
    )
    _add_reason(
        bounded_execution_status not in {"", "none", "not_applicable"},
        "bounded_execution_status_not_not_applicable",
    )
    _add_reason(
        bounded_execution_decision not in {"", "none", "no_execution"},
        "bounded_execution_decision_not_no_execution",
    )
    _add_reason(
        verification_primary_reason == "completion_gap",
        "completion_gap",
    )
    _add_reason(
        manual_closure_only or closure_status == "manual_closure_only",
        "manual_closure_only",
    )
    _add_reason(
        verification_primary_reason == "approval_blocker",
        "approval_blocker",
    )
    _add_reason(
        execution_authorization_primary_reason == "missing_binding"
        or execution_authorization_binding_status == "missing",
        "missing_binding",
    )
    _add_reason(
        bounded_execution_primary_reason == "authorization_not_eligible",
        "authorization_not_eligible",
    )
    _add_reason(
        verification_primary_reason == "reconcile_mismatch",
        "reconcile_mismatch",
    )
    _add_reason(
        prompt167_smoke_fallback_active,
        "prompt167_smoke_fallback_active",
    )
    _add_reason(
        local_targeted_contract_fix_prompt_lifecycle_issue_detected
        or any(
            marker in reason
            for reason in (
                local_targeted_contract_fix_route_intake_blocked_reason,
                local_targeted_contract_fix_prompt_plan_blocked_reason,
                local_targeted_contract_fix_prompt_normalized_reason,
            )
            for marker in ("UnboundLocalError", "local_targeted_contract_fix_prompt_state")
        ),
        "local_targeted_contract_fix_prompt_state_failure_active",
    )

    readiness_status = "ready" if not blocked_reasons else "blocked"
    next_cycle_allowed = readiness_status == "ready"
    next_action = (
        "proceed_to_next_local_cycle"
        if next_cycle_allowed
        else "hold_for_followup"
    )
    blocked_reason = blocked_reasons[0] if blocked_reasons else ""
    manual_required = bool(
        execution_authorization_manual_required
        or bounded_execution_manual_required
        or _as_boolish(run_state.get("manual_intervention_required"))
        or _as_boolish(run_state.get("manual_closure_required"))
        or manual_closure_only
    )
    replan_required = bool(
        execution_authorization_replan_required
        or bounded_execution_replan_required
        or _as_boolish(completion.get("completion_replan_required"))
        or _as_boolish(run_state.get("replan_required"))
    )
    summary = (
        "Prompt355 ready: Prompt354 clean verified closure can proceed to the next "
        "local-only autonomous cycle."
        if next_cycle_allowed
        else "Prompt355 blocked: " + ", ".join(blocked_reasons)
    )

    return {
        "prompt355_readiness_status": readiness_status,
        "prompt355_next_cycle_allowed": bool(next_cycle_allowed),
        "prompt355_next_action": next_action,
        "prompt355_blocked_reason": blocked_reason,
        "prompt355_blocked_reasons": _normalize_string_list(blocked_reasons),
        "prompt355_truth_source": "prompt354_clean_verified_closure",
        "prompt355_scope": "local_only",
        "prompt355_remote_operations_required": False,
        "prompt355_github_operations_required": False,
        "prompt355_manual_required": bool(manual_required),
        "prompt355_replan_required": bool(replan_required),
        "prompt355_summary": summary,
    }

def _build_prompt356_stale_blocker_alignment_surface(
    *,
    run_state_payload: Mapping[str, Any],
    prompt355_readiness_payload: Mapping[str, Any] | None,
    completion_contract_payload: Mapping[str, Any] | None,
    execution_authorization_gate_payload: Mapping[str, Any] | None,
    bounded_execution_bridge_payload: Mapping[str, Any] | None,
    verification_closure_contract_payload: Mapping[str, Any] | None,
    endgame_closure_contract_payload: Mapping[str, Any] | None,
    failure_bucket_rollup_payload: Mapping[str, Any] | None,
    failure_bucketing_hardening_payload: Mapping[str, Any] | None,
    reconcile_contract_payload: Mapping[str, Any] | None,
    repair_suggestion_contract_payload: Mapping[str, Any] | None,
    repair_plan_transport_payload: Mapping[str, Any] | None,
    repair_approval_binding_payload: Mapping[str, Any] | None,
) -> dict[str, Any]:
    run_state = dict(run_state_payload or {})
    prompt355 = dict(prompt355_readiness_payload or {})
    completion = dict(completion_contract_payload or {})
    execution_authorization = dict(execution_authorization_gate_payload or {})
    bounded_execution = dict(bounded_execution_bridge_payload or {})
    verification = dict(verification_closure_contract_payload or {})
    endgame = dict(endgame_closure_contract_payload or {})
    failure_bucket = dict(failure_bucket_rollup_payload or {})
    failure_bucketing = dict(failure_bucketing_hardening_payload or {})
    reconcile = dict(reconcile_contract_payload or {})
    repair = dict(repair_suggestion_contract_payload or {})
    repair_plan = dict(repair_plan_transport_payload or {})
    repair_binding = dict(repair_approval_binding_payload or {})

    def _read_text(*values: Any, default: str = "") -> str:
        for value in values:
            text = _normalize_text(value, default="")
            if text:
                return text
        return default

    def _as_boolish(value: Any, *, default: bool = False) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, int):
            return value != 0
        text = _normalize_text(value, default="").strip().lower()
        if text in {"1", "true", "yes", "on", "enabled"}:
            return True
        if text in {"0", "false", "no", "off", "disabled"}:
            return False
        return default

    def _is_clear_reason(value: Any) -> bool:
        return _normalize_text(value, default="").strip().lower() in {"", "none"}

    def _contains_marker(value: Any, marker: str) -> bool:
        return marker in _normalize_text(value, default="").strip().lower()

    prompt355_readiness_status = _read_text(
        prompt355.get("prompt355_readiness_status"),
        run_state.get("prompt355_readiness_status"),
    )
    prompt355_next_cycle_allowed = _as_boolish(
        prompt355.get("prompt355_next_cycle_allowed")
        if "prompt355_next_cycle_allowed" in prompt355
        else run_state.get("prompt355_next_cycle_allowed")
    )
    prompt355_next_action = _read_text(
        prompt355.get("prompt355_next_action"),
        run_state.get("prompt355_next_action"),
    )
    prompt355_manual_required = _as_boolish(
        prompt355.get("prompt355_manual_required")
        if "prompt355_manual_required" in prompt355
        else run_state.get("prompt355_manual_required")
    )
    prompt355_replan_required = _as_boolish(
        prompt355.get("prompt355_replan_required")
        if "prompt355_replan_required" in prompt355
        else run_state.get("prompt355_replan_required")
    )

    verification_status = _read_text(
        verification.get("verification_status"),
        run_state.get("verification_status"),
    )
    verification_outcome = _read_text(
        verification.get("verification_outcome"),
        run_state.get("verification_outcome"),
    )
    verification_primary_reason = _read_text(
        verification.get("verification_primary_reason"),
        run_state.get("verification_primary_reason"),
    )
    closure_status = _read_text(
        verification.get("closure_status"),
        run_state.get("closure_status"),
    )
    safely_closable = _as_boolish(
        verification.get("safely_closable")
        if "safely_closable" in verification
        else run_state.get("safely_closable")
    )
    completion_status = _read_text(
        completion.get("completion_status"),
        run_state.get("completion_status"),
    )
    safe_closure_status = _read_text(
        completion.get("safe_closure_status"),
        run_state.get("safe_closure_status"),
    )
    endgame_closure_status = _read_text(
        endgame.get("endgame_closure_status"),
        run_state.get("endgame_closure_status"),
    )
    terminal_success = _as_boolish(
        endgame.get("terminal_success")
        if "terminal_success" in endgame
        else run_state.get("terminal_success")
    )
    execution_authorization_blocked_reason = _read_text(
        execution_authorization.get("execution_authorization_blocked_reason"),
        run_state.get("execution_authorization_blocked_reason"),
    )
    bounded_execution_blocked_reason = _read_text(
        bounded_execution.get("bounded_execution_blocked_reason"),
        run_state.get("bounded_execution_blocked_reason"),
    )

    authoritative_ready = all(
        (
            prompt355_readiness_status == "ready",
            prompt355_next_cycle_allowed,
            prompt355_next_action == "proceed_to_next_local_cycle",
            not prompt355_manual_required,
            not prompt355_replan_required,
            verification_status == "verified_success",
            verification_outcome == "objective_satisfied",
            verification_primary_reason == "verified_success",
            closure_status == "safely_closable",
            safely_closable,
            completion_status == "done_and_safely_closed",
            safe_closure_status == "safely_closed",
            endgame_closure_status == "safely_closed" or terminal_success,
            _is_clear_reason(execution_authorization_blocked_reason),
            _is_clear_reason(bounded_execution_blocked_reason),
        )
    )

    stale_blocker_reasons: list[str] = []

    def _add_stale_reason(condition: bool, reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if condition and normalized_reason and normalized_reason not in stale_blocker_reasons:
            stale_blocker_reasons.append(normalized_reason)

    primary_failure_bucket = _read_text(
        failure_bucket.get("primary_failure_bucket"),
        failure_bucketing.get("primary_failure_bucket"),
        run_state.get("primary_failure_bucket"),
    )
    failure_bucketing_primary_reason = _read_text(
        failure_bucketing.get("failure_bucketing_primary_reason"),
        run_state.get("failure_bucketing_primary_reason"),
    )
    reconcile_status = _read_text(
        reconcile.get("reconcile_status"),
        run_state.get("reconcile_status"),
    )
    reconcile_primary_mismatch = _read_text(
        reconcile.get("reconcile_primary_mismatch"),
        run_state.get("reconcile_primary_mismatch"),
    )
    repair_primary_reason = _read_text(
        repair.get("repair_primary_reason"),
        run_state.get("repair_primary_reason"),
    )
    repair_plan_primary_reason = _read_text(
        repair_plan.get("repair_plan_primary_reason"),
        run_state.get("repair_plan_primary_reason"),
    )
    repair_approval_binding_status = _read_text(
        repair_binding.get("repair_approval_binding_status"),
        run_state.get("repair_approval_binding_status"),
    )
    repair_approval_binding_primary_reason = _read_text(
        repair_binding.get("repair_approval_binding_primary_reason"),
        run_state.get("repair_approval_binding_primary_reason"),
    )

    _add_stale_reason(
        primary_failure_bucket == "approval_blocker",
        "failure_bucket_approval_blocker",
    )
    _add_stale_reason(
        _contains_marker(failure_bucketing_primary_reason, "approval_blocker"),
        "failure_bucketing_primary_reason_approval_blocker",
    )
    _add_stale_reason(
        reconcile_status == "blocked"
        and reconcile_primary_mismatch == "completion_evidence_partial",
        "reconcile_blocked_completion_evidence_partial",
    )
    _add_stale_reason(
        repair_primary_reason == "completion_not_safely_closed",
        "repair_completion_not_safely_closed",
    )
    _add_stale_reason(
        repair_plan_primary_reason == "completion_not_safely_closed",
        "repair_plan_completion_not_safely_closed",
    )
    _add_stale_reason(
        repair_approval_binding_status == "missing"
        and repair_approval_binding_primary_reason == "missing_approval",
        "repair_approval_binding_missing_approval",
    )

    active_blocked_reasons: list[str] = []

    def _add_active_reason(condition: bool, reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if condition and normalized_reason and normalized_reason not in active_blocked_reasons:
            active_blocked_reasons.append(normalized_reason)

    _add_active_reason(
        prompt355_readiness_status != "ready",
        "prompt355_readiness_status_not_ready",
    )
    _add_active_reason(
        not prompt355_next_cycle_allowed,
        "prompt355_next_cycle_not_allowed",
    )
    _add_active_reason(
        prompt355_next_action != "proceed_to_next_local_cycle",
        "prompt355_next_action_not_proceed_to_next_local_cycle",
    )
    _add_active_reason(
        prompt355_manual_required,
        "prompt355_manual_required",
    )
    _add_active_reason(
        prompt355_replan_required,
        "prompt355_replan_required",
    )
    _add_active_reason(
        verification_status != "verified_success",
        "verification_status_not_verified_success",
    )
    _add_active_reason(
        verification_outcome != "objective_satisfied",
        "verification_outcome_not_objective_satisfied",
    )
    _add_active_reason(
        verification_primary_reason != "verified_success",
        "verification_primary_reason_not_verified_success",
    )
    _add_active_reason(
        closure_status != "safely_closable",
        "closure_status_not_safely_closable",
    )
    _add_active_reason(
        not safely_closable,
        "safely_closable_false",
    )
    _add_active_reason(
        completion_status != "done_and_safely_closed",
        "completion_status_not_done_and_safely_closed",
    )
    _add_active_reason(
        safe_closure_status != "safely_closed",
        "safe_closure_status_not_safely_closed",
    )
    _add_active_reason(
        endgame_closure_status != "safely_closed" and not terminal_success,
        "endgame_closure_not_safely_closed_or_terminal_success",
    )
    _add_active_reason(
        not _is_clear_reason(execution_authorization_blocked_reason),
        "execution_authorization_blocked_reason_present",
    )
    _add_active_reason(
        not _is_clear_reason(bounded_execution_blocked_reason),
        "bounded_execution_blocked_reason_present",
    )

    if authoritative_ready:
        alignment_status = "aligned"
        next_cycle_safe = True
        stale_blockers_ignored = bool(stale_blocker_reasons)
        active_blocked_reason = ""
        active_blocked_reasons = []
        manual_required = False
        replan_required = False
        next_action = "proceed_to_next_local_cycle"
        if stale_blocker_reasons:
            summary = (
                "Prompt356 aligned: local-only terminal success is authoritative and "
                "stale blocker surfaces are ignored_for_local_only_next_cycle: "
                + ", ".join(stale_blocker_reasons)
            )
        else:
            summary = (
                "Prompt356 aligned: Prompt355 ready terminal success is authoritative "
                "for next local-only cycle routing."
            )
    else:
        alignment_status = "blocked"
        next_cycle_safe = False
        stale_blockers_ignored = False
        active_blocked_reason = active_blocked_reasons[0] if active_blocked_reasons else "prompt356_authoritative_ready_evidence_missing"
        if not active_blocked_reasons:
            active_blocked_reasons = [active_blocked_reason]
        manual_required = bool(prompt355_manual_required)
        replan_required = bool(prompt355_replan_required)
        next_action = "hold_for_followup"
        summary = "Prompt356 blocked: " + ", ".join(active_blocked_reasons)

    return {
        "prompt356_alignment_status": alignment_status,
        "prompt356_next_cycle_safe": bool(next_cycle_safe),
        "prompt356_stale_blockers_present": bool(stale_blocker_reasons),
        "prompt356_stale_blockers_ignored": bool(stale_blockers_ignored),
        "prompt356_stale_blocker_reasons": _normalize_string_list(stale_blocker_reasons),
        "prompt356_active_blocked_reason": active_blocked_reason,
        "prompt356_active_blocked_reasons": _normalize_string_list(active_blocked_reasons),
        "prompt356_authoritative_source": "prompt355_ready_terminal_success",
        "prompt356_scope": "local_only",
        "prompt356_manual_required": bool(manual_required),
        "prompt356_replan_required": bool(replan_required),
        "prompt356_next_action": next_action,
        "prompt356_summary": summary,
    }

def _build_prompt357_evidence_snapshot(
    *,
    prompt355_payload: Mapping[str, Any] | None = None,
    prompt356_payload: Mapping[str, Any] | None = None,
    verification_payload: Mapping[str, Any] | None = None,
    completion_payload: Mapping[str, Any] | None = None,
    endgame_payload: Mapping[str, Any] | None = None,
    summary_payload: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    return {
        "prompt355_readiness_status": _prompt357_read_text(
            "prompt355_readiness_status",
            prompt355_payload,
            prompt356_payload,
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "prompt355_next_cycle_allowed": _prompt357_read_bool(
            "prompt355_next_cycle_allowed",
            prompt355_payload,
            prompt356_payload,
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "prompt355_next_action": _prompt357_read_text(
            "prompt355_next_action",
            prompt355_payload,
            prompt356_payload,
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "prompt355_manual_required": _prompt357_read_bool(
            "prompt355_manual_required",
            prompt355_payload,
            prompt356_payload,
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "prompt355_replan_required": _prompt357_read_bool(
            "prompt355_replan_required",
            prompt355_payload,
            prompt356_payload,
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "prompt356_alignment_status": _prompt357_read_text(
            "prompt356_alignment_status",
            prompt356_payload,
            prompt355_payload,
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "prompt356_next_cycle_safe": _prompt357_read_bool(
            "prompt356_next_cycle_safe",
            prompt356_payload,
            prompt355_payload,
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "prompt356_stale_blockers_present": _prompt357_read_bool(
            "prompt356_stale_blockers_present",
            prompt356_payload,
            prompt355_payload,
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "prompt356_stale_blockers_ignored": _prompt357_read_bool(
            "prompt356_stale_blockers_ignored",
            prompt356_payload,
            prompt355_payload,
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "prompt356_next_action": _prompt357_read_text(
            "prompt356_next_action",
            prompt356_payload,
            prompt355_payload,
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "prompt356_active_blocked_reason": _prompt357_read_text(
            "prompt356_active_blocked_reason",
            prompt356_payload,
            prompt355_payload,
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "prompt356_active_blocked_reasons": _prompt357_read_list(
            "prompt356_active_blocked_reasons",
            prompt356_payload,
            prompt355_payload,
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "prompt356_manual_required": _prompt357_read_bool(
            "prompt356_manual_required",
            prompt356_payload,
            prompt355_payload,
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "prompt356_replan_required": _prompt357_read_bool(
            "prompt356_replan_required",
            prompt356_payload,
            prompt355_payload,
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "verification_status": _prompt357_read_text(
            "verification_status",
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "verification_outcome": _prompt357_read_text(
            "verification_outcome",
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "verification_primary_reason": _prompt357_read_text(
            "verification_primary_reason",
            verification_payload,
            completion_payload,
            endgame_payload,
            summary_payload,
        ),
        "completion_status": _prompt357_read_text(
            "completion_status",
            completion_payload,
            verification_payload,
            endgame_payload,
            summary_payload,
        ),
        "safe_closure_status": _prompt357_read_text(
            "safe_closure_status",
            completion_payload,
            verification_payload,
            endgame_payload,
            summary_payload,
        ),
        "endgame_closure_status": _prompt357_read_text(
            "endgame_closure_status",
            endgame_payload,
            completion_payload,
            verification_payload,
            summary_payload,
        ),
        "terminal_success": _prompt357_read_bool(
            "terminal_success",
            endgame_payload,
            completion_payload,
            verification_payload,
            summary_payload,
        ),
    }

def _build_prompt357_current_runtime_regression_reasons(
    evidence_snapshot: Mapping[str, Any],
) -> list[str]:
    reasons: list[str] = []

    def _append(reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    if _normalize_text(
        evidence_snapshot.get("prompt355_readiness_status"),
        default="",
    ) != "ready":
        _append("prompt355_readiness_status_not_ready")
    if not bool(evidence_snapshot.get("prompt355_next_cycle_allowed", False)):
        _append("prompt355_next_cycle_not_allowed")
    if _normalize_text(
        evidence_snapshot.get("prompt355_next_action"),
        default="",
    ) != "proceed_to_next_local_cycle":
        _append("prompt355_next_action_not_proceed_to_next_local_cycle")
    if bool(evidence_snapshot.get("prompt355_manual_required", False)):
        _append("prompt355_manual_required")
    if bool(evidence_snapshot.get("prompt355_replan_required", False)):
        _append("prompt355_replan_required")
    if _normalize_text(
        evidence_snapshot.get("prompt356_alignment_status"),
        default="",
    ) != "aligned":
        _append("prompt356_alignment_status_not_aligned")
    if not bool(evidence_snapshot.get("prompt356_next_cycle_safe", False)):
        _append("prompt356_next_cycle_not_safe")
    if bool(evidence_snapshot.get("prompt356_stale_blockers_present", False)) and not bool(
        evidence_snapshot.get("prompt356_stale_blockers_ignored", False)
    ):
        _append("prompt356_stale_blockers_present_not_ignored")
    prompt356_active_blocked_reason = _normalize_text(
        evidence_snapshot.get("prompt356_active_blocked_reason"),
        default="",
    )
    if prompt356_active_blocked_reason:
        _append(prompt356_active_blocked_reason)
    for reason in _normalize_string_list(
        evidence_snapshot.get("prompt356_active_blocked_reasons"),
        sort_items=False,
    ):
        _append(reason)
    if bool(evidence_snapshot.get("prompt356_manual_required", False)):
        _append("prompt356_manual_required")
    if bool(evidence_snapshot.get("prompt356_replan_required", False)):
        _append("prompt356_replan_required")
    if _normalize_text(
        evidence_snapshot.get("verification_status"),
        default="",
    ) != "verified_success":
        _append("verification_status_not_verified_success")
    if _normalize_text(
        evidence_snapshot.get("verification_outcome"),
        default="",
    ) != "objective_satisfied":
        _append("verification_outcome_not_objective_satisfied")
    if _normalize_text(
        evidence_snapshot.get("completion_status"),
        default="",
    ) != "done_and_safely_closed":
        _append("completion_status_not_done_and_safely_closed")
    if _normalize_text(
        evidence_snapshot.get("endgame_closure_status"),
        default="",
    ) != "safely_closed" and not bool(
        evidence_snapshot.get("terminal_success", False)
    ):
        _append("endgame_closure_not_safely_closed_or_terminal_success")
    return reasons

def _build_prompt357_previous_success_evidence_missing(
    evidence_snapshot: Mapping[str, Any],
) -> list[str]:
    missing: list[str] = []

    def _append(reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in missing:
            missing.append(normalized_reason)

    if _normalize_text(
        evidence_snapshot.get("prompt355_readiness_status"),
        default="",
    ) != "ready":
        _append("prompt355_readiness_status_not_ready")
    if not bool(evidence_snapshot.get("prompt355_next_cycle_allowed", False)):
        _append("prompt355_next_cycle_not_allowed")
    if _normalize_text(
        evidence_snapshot.get("prompt355_next_action"),
        default="",
    ) != "proceed_to_next_local_cycle":
        _append("prompt355_next_action_not_proceed_to_next_local_cycle")
    if bool(evidence_snapshot.get("prompt355_manual_required", False)):
        _append("prompt355_manual_required")
    if bool(evidence_snapshot.get("prompt355_replan_required", False)):
        _append("prompt355_replan_required")
    if _normalize_text(
        evidence_snapshot.get("prompt356_alignment_status"),
        default="",
    ) != "aligned":
        _append("prompt356_alignment_status_not_aligned")
    if not bool(evidence_snapshot.get("prompt356_next_cycle_safe", False)):
        _append("prompt356_next_cycle_not_safe")
    if not bool(evidence_snapshot.get("prompt356_stale_blockers_ignored", False)):
        _append("prompt356_stale_blockers_not_ignored")
    if _normalize_text(
        evidence_snapshot.get("prompt356_next_action"),
        default="",
    ) != "proceed_to_next_local_cycle":
        _append("prompt356_next_action_not_proceed_to_next_local_cycle")
    if _normalize_text(
        evidence_snapshot.get("prompt356_active_blocked_reason"),
        default="",
    ):
        _append("prompt356_active_blocked_reason_present")
    if _normalize_string_list(
        evidence_snapshot.get("prompt356_active_blocked_reasons"),
        sort_items=False,
    ):
        _append("prompt356_active_blocked_reasons_present")
    if _normalize_text(
        evidence_snapshot.get("verification_status"),
        default="",
    ) != "verified_success":
        _append("verification_status_not_verified_success")
    if _normalize_text(
        evidence_snapshot.get("verification_outcome"),
        default="",
    ) != "objective_satisfied":
        _append("verification_outcome_not_objective_satisfied")
    if _normalize_text(
        evidence_snapshot.get("verification_primary_reason"),
        default="",
    ) != "verified_success":
        _append("verification_primary_reason_not_verified_success")
    if _normalize_text(
        evidence_snapshot.get("completion_status"),
        default="",
    ) != "done_and_safely_closed":
        _append("completion_status_not_done_and_safely_closed")
    if _normalize_text(
        evidence_snapshot.get("safe_closure_status"),
        default="",
    ) != "safely_closed":
        _append("safe_closure_status_not_safely_closed")
    if _normalize_text(
        evidence_snapshot.get("endgame_closure_status"),
        default="",
    ) != "safely_closed" and not bool(
        evidence_snapshot.get("terminal_success", False)
    ):
        _append("endgame_closure_not_safely_closed_or_terminal_success")
    return missing

def _build_prompt357_previous_success_candidate(
    *,
    source_label: str,
    source_priority: int,
    source_path: Path | None = None,
    prompt355_payload: Mapping[str, Any] | None = None,
    prompt356_payload: Mapping[str, Any] | None = None,
    verification_payload: Mapping[str, Any] | None = None,
    completion_payload: Mapping[str, Any] | None = None,
    endgame_payload: Mapping[str, Any] | None = None,
    summary_payload: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    snapshot = _build_prompt357_evidence_snapshot(
        prompt355_payload=prompt355_payload,
        prompt356_payload=prompt356_payload,
        verification_payload=verification_payload,
        completion_payload=completion_payload,
        endgame_payload=endgame_payload,
        summary_payload=summary_payload,
    )
    source_timestamp = 0
    if source_path is not None:
        try:
            source_timestamp = source_path.stat().st_mtime_ns
        except OSError:
            source_timestamp = 0
    valid = not _build_prompt357_previous_success_evidence_missing(snapshot)
    return {
        "source_label": _normalize_text(source_label, default="previous_success_source"),
        "source_priority": int(source_priority),
        "source_timestamp": int(source_timestamp),
        "source_path": str(source_path) if source_path is not None else "",
        "snapshot": snapshot,
        "valid": bool(valid),
        "missing": _build_prompt357_previous_success_evidence_missing(snapshot),
    }

def _build_prompt357_suppressed_legacy_blockers(
    *,
    manifest_units: Sequence[Mapping[str, Any]],
    prompt356_stale_blocker_alignment_payload: Mapping[str, Any] | None,
) -> list[str]:
    prompt356 = dict(prompt356_stale_blocker_alignment_payload or {})
    suppressed_blockers: list[str] = []

    def _append(reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in suppressed_blockers:
            suppressed_blockers.append(normalized_reason)

    for stale_reason in _normalize_string_list(
        prompt356.get("prompt356_stale_blocker_reasons"),
        sort_items=False,
    ):
        _append(
            f"stale_blocker_ignored_for_local_only_next_cycle:{stale_reason}"
        )

    blocker_sources = (
        ("push", "push_execution_summary"),
        ("pr", "pr_execution_summary"),
        ("merge", "merge_execution_summary"),
        ("rollback", "rollback_execution_summary"),
    )
    blocker_field_names = (
        "blocking_reasons",
        "validation_blocked_reasons",
        "authority_blocked_reasons",
        "remote_github_blocked_reasons",
        "rollback_aftermath_blocked_reasons",
    )
    blocker_reason_names = (
        "failure_reason",
        "validation_blocked_reason",
        "authority_blocked_reason",
        "remote_state_blocked_reason",
        "remote_github_blocked_reason",
        "rollback_aftermath_blocked_reason",
    )
    for entry in manifest_units:
        unit_id = _normalize_text(
            entry.get("pr_id"),
            default=_normalize_text(entry.get("unit_id"), default="unknown_unit"),
        )
        for blocker_kind, summary_key in blocker_sources:
            summary = entry.get(summary_key)
            if not isinstance(summary, Mapping):
                continue
            reasons: list[str] = []
            for field_name in blocker_field_names:
                reasons.extend(
                    _normalize_string_list(summary.get(field_name), sort_items=False)
                )
            for field_name in blocker_reason_names:
                reason = _normalize_text(summary.get(field_name), default="")
                if reason:
                    reasons.append(reason)
            if bool(summary.get("remote_state_blocked", False)):
                reasons.append("remote_state_blocked")
            if bool(summary.get("remote_github_blocked", False)):
                reasons.append("remote_github_blocked")
            if bool(summary.get("rollback_remote_followup_required", False)):
                reasons.append("rollback_remote_followup_required")
            if bool(summary.get("rollback_aftermath_blocked", False)):
                reasons.append("rollback_aftermath_blocked")
            if _normalize_text(summary.get("status"), default="") == "blocked" and not reasons:
                reasons.append("blocked")
            for reason in _normalize_string_list(reasons, sort_items=False):
                _append(
                    f"{blocker_kind}_blocker_not_required_for_local_only_continuation:{unit_id}:{reason}"
                )

    return suppressed_blockers

def _build_prompt357_local_continuation_route_surface(
    *,
    run_state_payload: Mapping[str, Any],
    decision_payload: Mapping[str, Any] | None,
    prompt355_readiness_payload: Mapping[str, Any] | None,
    prompt356_stale_blocker_alignment_payload: Mapping[str, Any] | None,
    manifest_units: Sequence[Mapping[str, Any]],
    execution_repo_path: str,
    artifacts_dir_path: str,
    run_root_path: str,
    prior_manifest_payload: Mapping[str, Any] | None,
    prior_run_state_payload: Mapping[str, Any] | None,
    prior_prompt355_readiness_payload: Mapping[str, Any] | None,
    prior_prompt356_stale_blocker_alignment_payload: Mapping[str, Any] | None,
    prior_verification_closure_contract_payload: Mapping[str, Any] | None,
    prior_completion_contract_payload: Mapping[str, Any] | None,
    prior_endgame_closure_contract_payload: Mapping[str, Any] | None,
    reference_payloads: Sequence[Mapping[str, Any] | None],
) -> dict[str, Any]:
    run_state = dict(run_state_payload or {})
    decision = dict(decision_payload or {})
    prompt355 = dict(prompt355_readiness_payload or {})
    prompt356 = dict(prompt356_stale_blocker_alignment_payload or {})

    def _read_text(*values: Any, default: str = "") -> str:
        for value in values:
            text = _normalize_text(value, default="")
            if text:
                return text
        return default

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    prompt355_readiness_status = _read_text(
        prompt355.get("prompt355_readiness_status"),
        run_state.get("prompt355_readiness_status"),
    )
    prompt355_next_cycle_allowed = _prompt357_as_boolish(
        prompt355.get("prompt355_next_cycle_allowed")
        if "prompt355_next_cycle_allowed" in prompt355
        else run_state.get("prompt355_next_cycle_allowed")
    )
    prompt355_next_action = _read_text(
        prompt355.get("prompt355_next_action"),
        run_state.get("prompt355_next_action"),
    )
    prompt355_manual_required = _prompt357_as_boolish(
        prompt355.get("prompt355_manual_required")
        if "prompt355_manual_required" in prompt355
        else run_state.get("prompt355_manual_required")
    )
    prompt355_replan_required = _prompt357_as_boolish(
        prompt355.get("prompt355_replan_required")
        if "prompt355_replan_required" in prompt355
        else run_state.get("prompt355_replan_required")
    )

    prompt356_alignment_status = _read_text(
        prompt356.get("prompt356_alignment_status"),
        run_state.get("prompt356_alignment_status"),
    )
    prompt356_next_cycle_safe = _prompt357_as_boolish(
        prompt356.get("prompt356_next_cycle_safe")
        if "prompt356_next_cycle_safe" in prompt356
        else run_state.get("prompt356_next_cycle_safe")
    )
    prompt356_stale_blockers_present = _prompt357_as_boolish(
        prompt356.get("prompt356_stale_blockers_present")
        if "prompt356_stale_blockers_present" in prompt356
        else run_state.get("prompt356_stale_blockers_present")
    )
    prompt356_stale_blockers_ignored = _prompt357_as_boolish(
        prompt356.get("prompt356_stale_blockers_ignored")
        if "prompt356_stale_blockers_ignored" in prompt356
        else run_state.get("prompt356_stale_blockers_ignored")
    )
    prompt356_active_blocked_reason = _read_text(
        prompt356.get("prompt356_active_blocked_reason"),
        run_state.get("prompt356_active_blocked_reason"),
    )
    prompt356_active_blocked_reasons = _normalize_string_list(
        prompt356.get("prompt356_active_blocked_reasons")
        if "prompt356_active_blocked_reasons" in prompt356
        else run_state.get("prompt356_active_blocked_reasons"),
        sort_items=False,
    )
    prompt356_manual_required = _prompt357_as_boolish(
        prompt356.get("prompt356_manual_required")
        if "prompt356_manual_required" in prompt356
        else run_state.get("prompt356_manual_required")
    )
    prompt356_replan_required = _prompt357_as_boolish(
        prompt356.get("prompt356_replan_required")
        if "prompt356_replan_required" in prompt356
        else run_state.get("prompt356_replan_required")
    )

    current_runtime_evidence = _build_prompt357_evidence_snapshot(
        prompt355_payload=prompt355,
        prompt356_payload=prompt356,
        verification_payload=run_state,
        completion_payload=run_state,
        endgame_payload=run_state,
        summary_payload=run_state,
    )
    verification_status = _normalize_text(
        current_runtime_evidence.get("verification_status"),
        default="",
    )
    verification_outcome = _normalize_text(
        current_runtime_evidence.get("verification_outcome"),
        default="",
    )
    completion_status = _normalize_text(
        current_runtime_evidence.get("completion_status"),
        default="",
    )
    endgame_closure_status = _normalize_text(
        current_runtime_evidence.get("endgame_closure_status"),
        default="",
    )
    terminal_success = bool(current_runtime_evidence.get("terminal_success", False))
    legacy_next_action = _read_text(
        decision.get("next_action"),
        run_state.get("next_action"),
        run_state.get("next_run_action"),
    )
    ready_evidence = _prompt357_current_runtime_evidence_is_ready(
        current_runtime_evidence
    )
    active_blocked_reasons = _build_prompt357_current_runtime_regression_reasons(
        current_runtime_evidence
    )

    prompt357_commit_execution_false_blocker_detected = False
    prompt357_commit_execution_false_blocker_reason = ""
    git_diff_changed_files = _collect_prompt357_local_git_diff_changed_files(
        execution_repo_path=execution_repo_path,
    )
    if git_diff_changed_files:
        for entry in manifest_units:
            summary = entry.get("commit_execution_summary")
            if not isinstance(summary, Mapping):
                continue
            blocking_reasons = _normalize_string_list(
                summary.get("blocking_reasons"),
                sort_items=False,
            )
            validation_blocked_reasons = _normalize_string_list(
                summary.get("validation_blocked_reasons"),
                sort_items=False,
            )
            if (
                "result_changed_files_missing" in blocking_reasons
                or "result_changed_files_missing" in validation_blocked_reasons
            ):
                prompt357_commit_execution_false_blocker_detected = True
                prompt357_commit_execution_false_blocker_reason = (
                    "result_changed_files_missing_but_git_diff_changed_files_present"
                )
                break

    suppressed_legacy_next_action = (
        "proceed_to_pr" if legacy_next_action == "proceed_to_pr" else ""
    )
    suppressed_legacy_blockers = _build_prompt357_suppressed_legacy_blockers(
        manifest_units=manifest_units,
        prompt356_stale_blocker_alignment_payload=prompt356,
    )
    if suppressed_legacy_next_action:
        _append_reason(
            suppressed_legacy_blockers,
            "legacy_next_action_not_required_for_local_only_continuation:proceed_to_pr",
        )

    if ready_evidence:
        route_status = "reconciled"
        local_continuation_allowed = True
        authoritative_next_action = "proceed_to_next_local_cycle"
        next_action = "prepare_next_local_cycle"
        evidence_source = "current_runtime"
        current_runtime_regression_detected = False
        current_runtime_regression_reasons: list[str] = []
        previous_success_evidence_valid = False
        previous_success_evidence_source = ""
        previous_success_evidence_missing: list[str] = []
        commit_tag_manual_step_allowed = True
        manual_required = False
        replan_required = False
        active_blocked_reason = ""
        active_blocked_reasons = []
        authoritative_source = "prompt355_ready_prompt356_aligned_current_runtime"
        summary = (
            "Prompt357 reconciled: authoritative local-only continuation proceeds to "
            "the next cycle."
        )
        if suppressed_legacy_blockers:
            summary += " Suppressed legacy blockers: " + ", ".join(
                suppressed_legacy_blockers
            )
    else:
        current_runtime_regression_detected = bool(active_blocked_reasons) and (
            prompt355_readiness_status != "ready"
            or prompt356_alignment_status != "aligned"
            or bool(prompt356_active_blocked_reason)
            or bool(prompt356_active_blocked_reasons)
        )
        current_runtime_regression_reasons = list(active_blocked_reasons)
        previous_success_fallback = (
            _resolve_prompt357_previous_success_fallback(
                run_root_path=run_root_path,
                artifacts_dir_path=artifacts_dir_path,
                prior_manifest_payload=prior_manifest_payload,
                prior_run_state_payload=prior_run_state_payload,
                prior_prompt355_readiness_payload=prior_prompt355_readiness_payload,
                prior_prompt356_stale_blocker_alignment_payload=(
                    prior_prompt356_stale_blocker_alignment_payload
                ),
                prior_verification_closure_contract_payload=(
                    prior_verification_closure_contract_payload
                ),
                prior_completion_contract_payload=prior_completion_contract_payload,
                prior_endgame_closure_contract_payload=(
                    prior_endgame_closure_contract_payload
                ),
                reference_payloads=reference_payloads,
            )
            if current_runtime_regression_detected
            else {
                "valid": False,
                "source": "",
                "missing": ["current_runtime_regression_not_detected"],
            }
        )
        previous_success_evidence_valid = bool(previous_success_fallback.get("valid", False))
        previous_success_evidence_source = _normalize_text(
            previous_success_fallback.get("source"),
            default="",
        )
        previous_success_evidence_missing = _normalize_string_list(
            previous_success_fallback.get("missing"),
            sort_items=False,
        )

        if previous_success_evidence_valid:
            route_status = "reconciled"
            local_continuation_allowed = True
            authoritative_next_action = "proceed_to_next_local_cycle"
            next_action = "prepare_next_local_cycle"
            evidence_source = "previous_success_artifact_fallback"
            commit_tag_manual_step_allowed = True
            manual_required = False
            replan_required = False
            active_blocked_reason = ""
            active_blocked_reasons = []
            authoritative_source = (
                "prompt355_ready_prompt356_aligned_previous_success_fallback"
            )
            summary = (
                "Prompt357 reconciled: current runtime Prompt355/356 regressed, so "
                "authoritative fallback uses the most recent previous local-only "
                f"Prompt356/Prompt355 success evidence from {previous_success_evidence_source}."
            )
            if current_runtime_regression_reasons:
                summary += " Current regression reasons: " + ", ".join(
                    current_runtime_regression_reasons
                )
            if suppressed_legacy_blockers:
                summary += " Suppressed legacy blockers: " + ", ".join(
                    suppressed_legacy_blockers
                )
        else:
            route_status = "blocked"
            local_continuation_allowed = False
            authoritative_next_action = "hold_for_followup"
            next_action = "hold_for_followup"
            evidence_source = "current_runtime_only"
            commit_tag_manual_step_allowed = False
            manual_required = bool(
                prompt355_manual_required
                or prompt356_manual_required
                or _prompt357_as_boolish(run_state.get("manual_intervention_required"))
            )
            replan_required = bool(
                prompt355_replan_required
                or prompt356_replan_required
                or _prompt357_as_boolish(run_state.get("replan_required"))
            )
            combined_blocked_reasons = list(active_blocked_reasons)
            for missing_reason in previous_success_evidence_missing:
                _append_reason(combined_blocked_reasons, missing_reason)
            active_blocked_reason = (
                combined_blocked_reasons[0]
                if combined_blocked_reasons
                else "prompt357_authoritative_ready_evidence_missing"
            )
            if not combined_blocked_reasons:
                combined_blocked_reasons = [active_blocked_reason]
            active_blocked_reasons = combined_blocked_reasons
            authoritative_source = (
                "prompt355_ready_prompt356_aligned_current_runtime_unreconciled"
            )
            summary = "Prompt357 blocked: " + ", ".join(active_blocked_reasons)

    return {
        "prompt357_route_status": route_status,
        "prompt357_local_continuation_allowed": bool(local_continuation_allowed),
        "prompt357_authoritative_next_action": authoritative_next_action,
        "prompt357_next_action": next_action,
        "prompt357_evidence_source": evidence_source,
        "prompt357_current_runtime_regression_detected": bool(
            current_runtime_regression_detected
        ),
        "prompt357_current_runtime_regression_reasons": _normalize_string_list(
            current_runtime_regression_reasons,
            sort_items=False,
        ),
        "prompt357_previous_success_evidence_valid": bool(
            previous_success_evidence_valid
        ),
        "prompt357_previous_success_evidence_source": (
            previous_success_evidence_source
        ),
        "prompt357_previous_success_evidence_missing": _normalize_string_list(
            previous_success_evidence_missing,
            sort_items=False,
        ),
        "prompt357_suppressed_legacy_next_action": suppressed_legacy_next_action,
        "prompt357_suppressed_legacy_blockers": _normalize_string_list(
            suppressed_legacy_blockers,
            sort_items=False,
        ),
        "prompt357_remote_operations_required": False,
        "prompt357_github_operations_required": False,
        "prompt357_push_required": False,
        "prompt357_pr_required": False,
        "prompt357_merge_required": False,
        "prompt357_rollback_required": False,
        "prompt357_commit_tag_automation_allowed": False,
        "prompt357_commit_tag_manual_step_allowed": bool(
            commit_tag_manual_step_allowed
        ),
        "prompt357_commit_execution_false_blocker_detected": bool(
            prompt357_commit_execution_false_blocker_detected
        ),
        "prompt357_commit_execution_false_blocker_reason": (
            prompt357_commit_execution_false_blocker_reason
        ),
        "prompt357_manual_required": bool(manual_required),
        "prompt357_replan_required": bool(replan_required),
        "prompt357_active_blocked_reason": active_blocked_reason,
        "prompt357_active_blocked_reasons": _normalize_string_list(
            active_blocked_reasons,
            sort_items=False,
        ),
        "prompt357_authoritative_source": authoritative_source,
        "prompt357_scope": "local_only",
        "prompt357_summary": summary,
    }

def _build_prompt358_next_local_cycle_selection_surface(
    *,
    run_state_payload: Mapping[str, Any],
    prompt355_readiness_payload: Mapping[str, Any] | None,
    prompt356_stale_blocker_alignment_payload: Mapping[str, Any] | None,
    prompt357_local_continuation_route_payload: Mapping[str, Any] | None,
) -> dict[str, Any]:
    run_state = dict(run_state_payload or {})
    prompt355 = dict(prompt355_readiness_payload or {})
    prompt356 = dict(prompt356_stale_blocker_alignment_payload or {})
    prompt357 = dict(prompt357_local_continuation_route_payload or {})

    def _read_text(*values: Any, default: str = "") -> str:
        for value in values:
            text = _normalize_text(value, default="")
            if text:
                return text
        return default

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    prompt355_readiness_status = _read_text(
        prompt355.get("prompt355_readiness_status"),
        run_state.get("prompt355_readiness_status"),
    )
    prompt355_next_cycle_allowed = _prompt357_as_boolish(
        prompt355.get("prompt355_next_cycle_allowed")
        if "prompt355_next_cycle_allowed" in prompt355
        else run_state.get("prompt355_next_cycle_allowed")
    )
    prompt355_manual_required = _prompt357_as_boolish(
        prompt355.get("prompt355_manual_required")
        if "prompt355_manual_required" in prompt355
        else run_state.get("prompt355_manual_required")
    )
    prompt355_replan_required = _prompt357_as_boolish(
        prompt355.get("prompt355_replan_required")
        if "prompt355_replan_required" in prompt355
        else run_state.get("prompt355_replan_required")
    )

    prompt356_alignment_status = _read_text(
        prompt356.get("prompt356_alignment_status"),
        run_state.get("prompt356_alignment_status"),
    )
    prompt356_next_cycle_safe = _prompt357_as_boolish(
        prompt356.get("prompt356_next_cycle_safe")
        if "prompt356_next_cycle_safe" in prompt356
        else run_state.get("prompt356_next_cycle_safe")
    )
    prompt356_manual_required = _prompt357_as_boolish(
        prompt356.get("prompt356_manual_required")
        if "prompt356_manual_required" in prompt356
        else run_state.get("prompt356_manual_required")
    )
    prompt356_replan_required = _prompt357_as_boolish(
        prompt356.get("prompt356_replan_required")
        if "prompt356_replan_required" in prompt356
        else run_state.get("prompt356_replan_required")
    )

    prompt357_route_status = _read_text(
        prompt357.get("prompt357_route_status"),
        run_state.get("prompt357_route_status"),
    )
    prompt357_local_continuation_allowed = _prompt357_as_boolish(
        prompt357.get("prompt357_local_continuation_allowed")
        if "prompt357_local_continuation_allowed" in prompt357
        else run_state.get("prompt357_local_continuation_allowed")
    )
    prompt357_authoritative_next_action = _read_text(
        prompt357.get("prompt357_authoritative_next_action"),
        run_state.get("prompt357_authoritative_next_action"),
    )
    prompt357_next_action = _read_text(
        prompt357.get("prompt357_next_action"),
        run_state.get("prompt357_next_action"),
    )
    prompt357_manual_required = _prompt357_as_boolish(
        prompt357.get("prompt357_manual_required")
        if "prompt357_manual_required" in prompt357
        else run_state.get("prompt357_manual_required")
    )
    prompt357_replan_required = _prompt357_as_boolish(
        prompt357.get("prompt357_replan_required")
        if "prompt357_replan_required" in prompt357
        else run_state.get("prompt357_replan_required")
    )
    prompt357_active_blocked_reason = _read_text(
        prompt357.get("prompt357_active_blocked_reason"),
        run_state.get("prompt357_active_blocked_reason"),
    )
    prompt357_active_blocked_reasons = _normalize_string_list(
        prompt357.get("prompt357_active_blocked_reasons")
        if "prompt357_active_blocked_reasons" in prompt357
        else run_state.get("prompt357_active_blocked_reasons"),
        sort_items=False,
    )

    ready_evidence = all(
        (
            prompt357_route_status == "reconciled",
            prompt357_local_continuation_allowed,
            prompt357_authoritative_next_action == "proceed_to_next_local_cycle",
            prompt357_next_action == "prepare_next_local_cycle",
            not prompt357_manual_required,
            not prompt357_replan_required,
            not prompt357_active_blocked_reason,
            not prompt357_active_blocked_reasons,
            prompt355_readiness_status == "ready",
            prompt355_next_cycle_allowed,
            prompt356_alignment_status == "aligned",
            prompt356_next_cycle_safe,
        )
    )
    recovered_evidence = {
        "prompt358_recovered_evidence_used": False,
        "prompt358_recovered_prompt355_source": "",
        "prompt358_recovered_prompt356_source": "",
        "prompt358_recovered_prompt357_source": "",
    }

    active_blocked_reasons: list[str] = []
    if not ready_evidence:
        if prompt357_route_status != "reconciled":
            _append_reason(
                active_blocked_reasons,
                "prompt357_route_status_not_reconciled",
            )
        if not prompt357_local_continuation_allowed:
            _append_reason(
                active_blocked_reasons,
                "prompt357_local_continuation_not_allowed",
            )
        if (
            prompt357_authoritative_next_action
            != "proceed_to_next_local_cycle"
        ):
            _append_reason(
                active_blocked_reasons,
                "prompt357_authoritative_next_action_not_proceed_to_next_local_cycle",
            )
        if prompt357_next_action != "prepare_next_local_cycle":
            _append_reason(
                active_blocked_reasons,
                "prompt357_next_action_not_prepare_next_local_cycle",
            )
        if prompt357_manual_required:
            _append_reason(active_blocked_reasons, "prompt357_manual_required")
        if prompt357_replan_required:
            _append_reason(active_blocked_reasons, "prompt357_replan_required")
        if prompt357_active_blocked_reason:
            _append_reason(
                active_blocked_reasons,
                "prompt357_active_blocked_reason_present",
            )
        if prompt357_active_blocked_reasons:
            _append_reason(
                active_blocked_reasons,
                "prompt357_active_blocked_reasons_present",
            )
        if prompt355_readiness_status != "ready":
            _append_reason(
                active_blocked_reasons,
                "prompt355_readiness_status_not_ready",
            )
        if not prompt355_next_cycle_allowed:
            _append_reason(
                active_blocked_reasons,
                "prompt355_next_cycle_not_allowed",
            )
        if prompt356_alignment_status != "aligned":
            _append_reason(
                active_blocked_reasons,
                "prompt356_alignment_status_not_aligned",
            )
        if not prompt356_next_cycle_safe:
            _append_reason(
                active_blocked_reasons,
                "prompt356_next_cycle_not_safe",
            )
        recovered_evidence = _resolve_prompt358_recovered_local_continuation_evidence()

    if ready_evidence or bool(recovered_evidence.get("prompt358_recovered_evidence_used", False)):
        selection_status = "ready"
        next_local_cycle_prepared = True
        selected_step_operation = "emit_selected_prompt_contract"
        authoritative_next_action = "emit_selected_prompt_contract"
        next_action = "prepare_prompt359_contract"
        commit_tag_manual_step_allowed = True
        manual_required = False
        replan_required = False
        active_blocked_reason = ""
        active_blocked_reasons = []
        if bool(recovered_evidence.get("prompt358_recovered_evidence_used", False)):
            summary = (
                "Prompt358 ready: authoritative local-only continuation was recovered "
                "from prior Prompt355/356/357 artifacts, and the Prompt359 "
                "selected-step contract is emitted as metadata only."
            )
            authoritative_source = (
                "prompt358_recovered_prompt355_prompt356_prompt357_artifacts"
            )
        else:
            summary = (
                "Prompt358 ready: next local-only autonomous cycle is prepared and the "
                "Prompt359 selected-step contract is emitted as metadata only."
            )
            authoritative_source = "prompt357_local_continuation_reconciled"
    else:
        selection_status = "blocked"
        next_local_cycle_prepared = False
        selected_step_operation = "blocked"
        authoritative_next_action = "hold_for_followup"
        next_action = "hold_for_followup"
        commit_tag_manual_step_allowed = False
        manual_required = bool(
            prompt357_manual_required
            or prompt356_manual_required
            or prompt355_manual_required
        )
        replan_required = bool(
            prompt357_replan_required
            or prompt356_replan_required
            or prompt355_replan_required
        )
        active_blocked_reason = (
            active_blocked_reasons[0]
            if active_blocked_reasons
            else "prompt358_ready_evidence_missing"
        )
        if not active_blocked_reasons:
            active_blocked_reasons = [active_blocked_reason]
        summary = "Prompt358 blocked: " + ", ".join(active_blocked_reasons)
        authoritative_source = "prompt357_local_continuation_reconciled"

    return {
        "prompt358_selection_status": selection_status,
        "prompt358_next_local_cycle_prepared": bool(next_local_cycle_prepared),
        "prompt358_selected_prompt_id": "prompt359",
        "prompt358_selected_prompt_title": (
            "bounded_selected_step_execution_contract"
        ),
        "prompt358_selected_step_operation": selected_step_operation,
        "prompt358_authoritative_next_action": authoritative_next_action,
        "prompt358_next_action": next_action,
        "prompt358_local_only": True,
        "prompt358_remote_operations_required": False,
        "prompt358_github_operations_required": False,
        "prompt358_push_required": False,
        "prompt358_pr_required": False,
        "prompt358_merge_required": False,
        "prompt358_rollback_required": False,
        "prompt358_codex_execution_allowed": False,
        "prompt358_selected_prompt_execution_allowed": False,
        "prompt358_prompt_generation_execution_allowed": False,
        "prompt358_commit_tag_automation_allowed": False,
        "prompt358_commit_tag_manual_step_allowed": bool(
            commit_tag_manual_step_allowed
        ),
        "prompt358_manual_required": bool(manual_required),
        "prompt358_replan_required": bool(replan_required),
        "prompt358_active_blocked_reason": active_blocked_reason,
        "prompt358_active_blocked_reasons": _normalize_string_list(
            active_blocked_reasons,
            sort_items=False,
        ),
        "prompt358_authoritative_source": authoritative_source,
        "prompt358_scope": "local_only",
        "prompt358_summary": summary,
        "prompt358_recovered_evidence_used": bool(
            recovered_evidence.get("prompt358_recovered_evidence_used", False)
        ),
        "prompt358_recovered_prompt355_source": _normalize_text(
            recovered_evidence.get("prompt358_recovered_prompt355_source"),
            default="",
        ),
        "prompt358_recovered_prompt356_source": _normalize_text(
            recovered_evidence.get("prompt358_recovered_prompt356_source"),
            default="",
        ),
        "prompt358_recovered_prompt357_source": _normalize_text(
            recovered_evidence.get("prompt358_recovered_prompt357_source"),
            default="",
        ),
    }

def _build_prompt358_selected_prompt_contract(
    *,
    prompt358_next_local_cycle_selection_payload: Mapping[str, Any] | None,
) -> dict[str, Any]:
    prompt358 = dict(prompt358_next_local_cycle_selection_payload or {})

    contract_status = (
        "ready"
        if _normalize_text(
            prompt358.get("prompt358_selection_status"),
            default="blocked",
        )
        == "ready"
        else "blocked"
    )

    return {
        "prompt358_contract_status": contract_status,
        "prompt358_selected_prompt_id": "prompt359",
        "prompt358_selected_prompt_title": (
            "bounded_selected_step_execution_contract"
        ),
        "prompt358_selected_step_operation": "emit_selected_prompt_contract",
        "prompt358_source_prompt": "prompt357",
        "prompt358_source_action": "prepare_next_local_cycle",
        "prompt358_local_only": True,
        "prompt358_execution_allowed": False,
        "prompt358_codex_execution_allowed": False,
        "prompt358_selected_prompt_execution_allowed": False,
        "prompt358_prompt_generation_execution_allowed": False,
        "prompt358_selected_prompt_objective": (
            "Emit a bounded selected-step execution contract that can later connect "
            "the prepared local-only next cycle to live Codex execution, without "
            "executing Codex, requiring remote GitHub operations, or mutating git."
        ),
        "prompt358_selected_prompt_constraints": [
            "no Codex invocation from runner",
            "no selected prompt execution",
            "no prompt generation execution",
            "no git mutation",
            "no network",
            "no daemon",
            "no unbounded loop",
            "no PR, push, merge, or rollback requirement",
        ],
        "prompt358_selected_prompt_success_criteria": [
            "selected prompt contract emitted",
            "local-only continuation evidence preserved",
            "Prompt357 reconciled evidence preserved",
            "execution remains disabled",
        ],
        "prompt358_active_blocked_reason": _normalize_text(
            prompt358.get("prompt358_active_blocked_reason"),
            default="",
        ),
        "prompt358_active_blocked_reasons": _normalize_string_list(
            prompt358.get("prompt358_active_blocked_reasons"),
            sort_items=False,
        ),
        "prompt358_recovered_evidence_used": bool(
            prompt358.get("prompt358_recovered_evidence_used", False)
        ),
        "prompt358_recovered_prompt355_source": _normalize_text(
            prompt358.get("prompt358_recovered_prompt355_source"),
            default="",
        ),
        "prompt358_recovered_prompt356_source": _normalize_text(
            prompt358.get("prompt358_recovered_prompt356_source"),
            default="",
        ),
        "prompt358_recovered_prompt357_source": _normalize_text(
            prompt358.get("prompt358_recovered_prompt357_source"),
            default="",
        ),
        "prompt358_preserved_local_only_evidence": {
            "prompt355_readiness_status": _normalize_text(
                prompt358.get("prompt355_readiness_status"),
                default="",
            ),
            "prompt355_next_cycle_allowed": bool(
                prompt358.get("prompt355_next_cycle_allowed", False)
            ),
            "prompt356_alignment_status": _normalize_text(
                prompt358.get("prompt356_alignment_status"),
                default="",
            ),
            "prompt356_next_cycle_safe": bool(
                prompt358.get("prompt356_next_cycle_safe", False)
            ),
            "prompt357_route_status": _normalize_text(
                prompt358.get("prompt357_route_status"),
                default="",
            ),
            "prompt357_local_continuation_allowed": bool(
                prompt358.get("prompt357_local_continuation_allowed", False)
            ),
            "prompt357_authoritative_next_action": _normalize_text(
                prompt358.get("prompt357_authoritative_next_action"),
                default="",
            ),
            "prompt357_next_action": _normalize_text(
                prompt358.get("prompt357_next_action"),
                default="",
            ),
        },
    }

def _build_prompt359_bounded_selected_step_execution_contract(
    *,
    run_state_payload: Mapping[str, Any] | None,
    prompt358_selected_prompt_contract_path: Path | None = None,
) -> dict[str, Any]:
    run_state = dict(run_state_payload or {})

    def _read_text(*values: Any, default: str = "") -> str:
        for value in values:
            text = _normalize_text(value, default="")
            if text:
                return text
        return default

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    prompt358_contract_status = _read_text(
        run_state.get("prompt358_contract_status"),
    )
    prompt358_selected_contract_ready = prompt358_contract_status == "ready"
    prompt358_selection_status = _read_text(
        run_state.get("prompt358_selection_status"),
        "ready" if prompt358_selected_contract_ready else "",
    )
    prompt358_next_local_cycle_prepared = _prompt357_as_boolish(
        run_state.get("prompt358_next_local_cycle_prepared")
        if "prompt358_next_local_cycle_prepared" in run_state
        else prompt358_selected_contract_ready
    )
    prompt358_selected_step_operation = _read_text(
        run_state.get("prompt358_selected_step_operation"),
    )
    prompt358_selected_prompt_id = _read_text(
        run_state.get("prompt358_selected_prompt_id"),
    )
    prompt358_selected_prompt_title = _read_text(
        run_state.get("prompt358_selected_prompt_title"),
    )
    prompt358_authoritative_next_action = _read_text(
        run_state.get("prompt358_authoritative_next_action"),
        (
            "emit_selected_prompt_contract"
            if prompt358_selected_contract_ready
            and prompt358_selected_step_operation == "emit_selected_prompt_contract"
            else ""
        ),
    )
    prompt358_next_action = _read_text(
        run_state.get("prompt358_next_action"),
        (
            "prepare_prompt359_contract"
            if prompt358_selected_contract_ready
            and prompt358_selected_step_operation == "emit_selected_prompt_contract"
            else ""
        ),
    )
    prompt358_codex_execution_allowed = _prompt357_as_boolish(
        run_state.get("prompt358_codex_execution_allowed")
    )
    prompt358_selected_prompt_execution_allowed = _prompt357_as_boolish(
        run_state.get("prompt358_selected_prompt_execution_allowed")
    )
    prompt358_prompt_generation_execution_allowed = _prompt357_as_boolish(
        run_state.get("prompt358_prompt_generation_execution_allowed")
    )
    prompt358_manual_required = _prompt357_as_boolish(
        run_state.get("prompt358_manual_required")
    )
    prompt358_replan_required = _prompt357_as_boolish(
        run_state.get("prompt358_replan_required")
    )
    prompt358_active_blocked_reason = _read_text(
        run_state.get("prompt358_active_blocked_reason"),
    )
    prompt358_active_blocked_reasons = _normalize_string_list(
        run_state.get("prompt358_active_blocked_reasons"),
        sort_items=False,
    )
    prompt358_recovered_evidence_used = _prompt357_as_boolish(
        run_state.get("prompt358_recovered_evidence_used")
    )
    prompt358_recovered_prompt355_source = _read_text(
        run_state.get("prompt358_recovered_prompt355_source"),
    )
    prompt358_recovered_prompt356_source = _read_text(
        run_state.get("prompt358_recovered_prompt356_source"),
    )
    prompt358_recovered_prompt357_source = _read_text(
        run_state.get("prompt358_recovered_prompt357_source"),
    )

    active_blocked_reasons: list[str] = []
    if prompt358_selection_status != "ready":
        _append_reason(active_blocked_reasons, "prompt358_selection_status_not_ready")
    if not prompt358_next_local_cycle_prepared:
        _append_reason(
            active_blocked_reasons,
            "prompt358_next_local_cycle_prepared_not_true",
        )
    if prompt358_selected_step_operation != "emit_selected_prompt_contract":
        _append_reason(
            active_blocked_reasons,
            "prompt358_selected_step_operation_not_emit_selected_prompt_contract",
        )
    if prompt358_selected_prompt_id != "prompt359":
        _append_reason(
            active_blocked_reasons,
            "prompt358_selected_prompt_id_not_prompt359",
        )
    if prompt358_selected_prompt_title != "bounded_selected_step_execution_contract":
        _append_reason(
            active_blocked_reasons,
            "prompt358_selected_prompt_title_not_bounded_selected_step_execution_contract",
        )
    if prompt358_authoritative_next_action != "emit_selected_prompt_contract":
        _append_reason(
            active_blocked_reasons,
            "prompt358_authoritative_next_action_not_emit_selected_prompt_contract",
        )
    if prompt358_next_action != "prepare_prompt359_contract":
        _append_reason(
            active_blocked_reasons,
            "prompt358_next_action_not_prepare_prompt359_contract",
        )
    if prompt358_codex_execution_allowed:
        _append_reason(
            active_blocked_reasons,
            "prompt358_codex_execution_allowed_true",
        )
    if prompt358_selected_prompt_execution_allowed:
        _append_reason(
            active_blocked_reasons,
            "prompt358_selected_prompt_execution_allowed_true",
        )
    if prompt358_prompt_generation_execution_allowed:
        _append_reason(
            active_blocked_reasons,
            "prompt358_prompt_generation_execution_allowed_true",
        )
    if prompt358_manual_required:
        _append_reason(active_blocked_reasons, "prompt358_manual_required")
    if prompt358_replan_required:
        _append_reason(active_blocked_reasons, "prompt358_replan_required")
    if prompt358_active_blocked_reason:
        _append_reason(
            active_blocked_reasons,
            "prompt358_active_blocked_reason_present",
        )
    if prompt358_active_blocked_reasons:
        _append_reason(
            active_blocked_reasons,
            "prompt358_active_blocked_reasons_present",
        )
    if not prompt358_recovered_evidence_used:
        _append_reason(
            active_blocked_reasons,
            "prompt358_recovered_evidence_used_not_true",
        )
    if not prompt358_recovered_prompt355_source:
        _append_reason(
            active_blocked_reasons,
            "prompt358_recovered_prompt355_source_missing",
        )
    if not prompt358_recovered_prompt356_source:
        _append_reason(
            active_blocked_reasons,
            "prompt358_recovered_prompt356_source_missing",
        )
    if not prompt358_recovered_prompt357_source:
        _append_reason(
            active_blocked_reasons,
            "prompt358_recovered_prompt357_source_missing",
        )

    contract_ready = not active_blocked_reasons
    prompt358_selected_prompt_contract_path_text = _normalize_text(
        str(prompt358_selected_prompt_contract_path)
        if prompt358_selected_prompt_contract_path is not None
        else "",
        default="",
    )

    if contract_ready:
        contract_status = "ready"
        selected_step_execution_contract_ready = True
        selected_step_operation = "prepare_bounded_codex_live_execution"
        authoritative_next_action = "prepare_bounded_codex_live_execution"
        next_action = "prepare_prompt360_codex_live_execution_gate"
        manual_required = False
        replan_required = False
        active_blocked_reason = ""
        normalized_active_blocked_reasons: list[str] = []
    else:
        contract_status = "blocked"
        selected_step_execution_contract_ready = False
        selected_step_operation = "blocked"
        authoritative_next_action = "hold_for_followup"
        next_action = "hold_for_followup"
        manual_required = True
        replan_required = False
        active_blocked_reason = active_blocked_reasons[0]
        normalized_active_blocked_reasons = _normalize_string_list(
            active_blocked_reasons,
            sort_items=False,
        )

    return {
        "prompt359_contract_status": contract_status,
        "prompt359_selected_step_execution_contract_ready": bool(
            selected_step_execution_contract_ready
        ),
        "prompt359_selected_step_operation": selected_step_operation,
        "prompt359_source_prompt": "prompt358",
        "prompt359_source_action": "prepare_prompt359_contract",
        "prompt359_authoritative_next_action": authoritative_next_action,
        "prompt359_next_action": next_action,
        "prompt359_local_only": True,
        "prompt359_codex_execution_allowed": False,
        "prompt359_live_execution_allowed": False,
        "prompt359_selected_step_execution_allowed": False,
        "prompt359_prompt_generation_execution_allowed": False,
        "prompt359_commit_tag_automation_allowed": False,
        "prompt359_commit_tag_manual_step_allowed": False,
        "prompt359_github_operations_required": False,
        "prompt359_remote_operations_required": False,
        "prompt359_push_required": False,
        "prompt359_pr_required": False,
        "prompt359_merge_required": False,
        "prompt359_rollback_required": False,
        "prompt359_manual_required": bool(manual_required),
        "prompt359_replan_required": bool(replan_required),
        "prompt359_active_blocked_reason": active_blocked_reason,
        "prompt359_active_blocked_reasons": normalized_active_blocked_reasons,
        "prompt359_prompt358_recovered_evidence_used": bool(
            prompt358_recovered_evidence_used
        ),
        "prompt359_prompt358_recovered_prompt355_source": (
            prompt358_recovered_prompt355_source
        ),
        "prompt359_prompt358_recovered_prompt356_source": (
            prompt358_recovered_prompt356_source
        ),
        "prompt359_prompt358_recovered_prompt357_source": (
            prompt358_recovered_prompt357_source
        ),
        "prompt359_prompt358_selected_prompt_contract_path": (
            prompt358_selected_prompt_contract_path_text
        ),
    }

def _build_prompt360_bounded_codex_live_execution_gate(
    *,
    run_state_payload: Mapping[str, Any] | None,
    dry_run: bool,
    adapter: CodexExecutorAdapter | None = None,
    run_root: Path | None = None,
    job_id: str = "",
    execution_repo_path: str = "",
    suppress_for_prompt379_explicit_execution: bool = False,
    now: Callable[[], datetime] = datetime.now,
) -> dict[str, Any]:
    run_state = dict(run_state_payload or {})

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    def _normalize_prompt359_surface(payload: Mapping[str, Any] | None) -> dict[str, Any]:
        source = dict(payload) if isinstance(payload, Mapping) else {}
        return {
            "prompt359_contract_status": _normalize_text(
                source.get("prompt359_contract_status"),
                default="",
            ),
            "prompt359_selected_step_execution_contract_ready": _prompt357_as_boolish(
                source.get("prompt359_selected_step_execution_contract_ready")
            ),
            "prompt359_selected_step_operation": _normalize_text(
                source.get("prompt359_selected_step_operation"),
                default="",
            ),
            "prompt359_authoritative_next_action": _normalize_text(
                source.get("prompt359_authoritative_next_action"),
                default="",
            ),
            "prompt359_next_action": _normalize_text(
                source.get("prompt359_next_action"),
                default="",
            ),
            "prompt359_manual_required": _prompt357_as_boolish(
                source.get("prompt359_manual_required")
            ),
            "prompt359_replan_required": _prompt357_as_boolish(
                source.get("prompt359_replan_required")
            ),
            "prompt359_active_blocked_reason": _normalize_text(
                source.get("prompt359_active_blocked_reason"),
                default="",
            ),
            "prompt359_active_blocked_reasons": _normalize_string_list(
                source.get("prompt359_active_blocked_reasons"),
                sort_items=False,
            ),
            "prompt359_prompt358_recovered_evidence_used": _prompt357_as_boolish(
                source.get("prompt359_prompt358_recovered_evidence_used")
            ),
            "prompt359_prompt358_recovered_prompt355_source": _normalize_text(
                source.get("prompt359_prompt358_recovered_prompt355_source"),
                default="",
            ),
            "prompt359_prompt358_recovered_prompt356_source": _normalize_text(
                source.get("prompt359_prompt358_recovered_prompt356_source"),
                default="",
            ),
            "prompt359_prompt358_recovered_prompt357_source": _normalize_text(
                source.get("prompt359_prompt358_recovered_prompt357_source"),
                default="",
            ),
            "prompt359_prompt358_selected_prompt_contract_path": _normalize_text(
                source.get("prompt359_prompt358_selected_prompt_contract_path"),
                default="",
            ),
        }

    def _prompt359_validation_reasons(
        prompt359_surface: Mapping[str, Any] | None,
    ) -> list[str]:
        surface = dict(prompt359_surface) if isinstance(prompt359_surface, Mapping) else {}
        reasons: list[str] = []
        if surface.get("prompt359_contract_status") != "ready":
            _append_reason(reasons, "prompt359_contract_status_not_ready")
        if not surface.get("prompt359_selected_step_execution_contract_ready", False):
            _append_reason(
                reasons,
                "prompt359_selected_step_execution_contract_ready_not_true",
            )
        if (
            surface.get("prompt359_selected_step_operation")
            != "prepare_bounded_codex_live_execution"
        ):
            _append_reason(
                reasons,
                "prompt359_selected_step_operation_not_prepare_bounded_codex_live_execution",
            )
        if (
            surface.get("prompt359_authoritative_next_action")
            != "prepare_bounded_codex_live_execution"
        ):
            _append_reason(
                reasons,
                "prompt359_authoritative_next_action_not_prepare_bounded_codex_live_execution",
            )
        if (
            surface.get("prompt359_next_action")
            != "prepare_prompt360_codex_live_execution_gate"
        ):
            _append_reason(
                reasons,
                "prompt359_next_action_not_prepare_prompt360_codex_live_execution_gate",
            )
        if surface.get("prompt359_manual_required", False):
            _append_reason(reasons, "prompt359_manual_required_true")
        if surface.get("prompt359_replan_required", False):
            _append_reason(reasons, "prompt359_replan_required_true")
        if surface.get("prompt359_active_blocked_reason"):
            _append_reason(
                reasons,
                "prompt359_active_blocked_reason_present",
            )
        if surface.get("prompt359_active_blocked_reasons"):
            _append_reason(
                reasons,
                "prompt359_active_blocked_reasons_present",
            )
        if not surface.get("prompt359_prompt358_recovered_evidence_used", False):
            _append_reason(
                reasons,
                "prompt359_prompt358_recovered_evidence_used_not_true",
            )
        if not surface.get("prompt359_prompt358_recovered_prompt355_source"):
            _append_reason(
                reasons,
                "prompt359_prompt358_recovered_prompt355_source_missing",
            )
        if not surface.get("prompt359_prompt358_recovered_prompt356_source"):
            _append_reason(
                reasons,
                "prompt359_prompt358_recovered_prompt356_source_missing",
            )
        if not surface.get("prompt359_prompt358_recovered_prompt357_source"):
            _append_reason(
                reasons,
                "prompt359_prompt358_recovered_prompt357_source_missing",
            )
        if not surface.get("prompt359_prompt358_selected_prompt_contract_path"):
            _append_reason(
                reasons,
                "prompt359_prompt358_selected_prompt_contract_path_missing",
            )
        return _normalize_string_list(reasons, sort_items=False)

    def _valid_recovered_prompt359_payload(payload: Mapping[str, Any] | None) -> bool:
        if not isinstance(payload, Mapping):
            return False
        active_blocked_reasons = payload.get("prompt359_active_blocked_reasons")
        return all(
            (
                _prompt358_required_text_match(
                    payload,
                    "prompt359_contract_status",
                    "ready",
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt359_selected_step_execution_contract_ready",
                    True,
                ),
                _prompt358_required_text_match(
                    payload,
                    "prompt359_selected_step_operation",
                    "prepare_bounded_codex_live_execution",
                ),
                _prompt358_required_text_match(
                    payload,
                    "prompt359_authoritative_next_action",
                    "prepare_bounded_codex_live_execution",
                ),
                _prompt358_required_text_match(
                    payload,
                    "prompt359_next_action",
                    "prepare_prompt360_codex_live_execution_gate",
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt359_manual_required",
                    False,
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt359_replan_required",
                    False,
                ),
                "prompt359_active_blocked_reason" in payload,
                _normalize_text(
                    payload.get("prompt359_active_blocked_reason"),
                    default="",
                )
                == "",
                isinstance(active_blocked_reasons, list),
                _normalize_string_list(active_blocked_reasons, sort_items=False) == [],
                _prompt358_required_bool_match(
                    payload,
                    "prompt359_prompt358_recovered_evidence_used",
                    True,
                ),
                bool(
                    _normalize_text(
                        payload.get("prompt359_prompt358_recovered_prompt355_source"),
                        default="",
                    )
                ),
                bool(
                    _normalize_text(
                        payload.get("prompt359_prompt358_recovered_prompt356_source"),
                        default="",
                    )
                ),
                bool(
                    _normalize_text(
                        payload.get("prompt359_prompt358_recovered_prompt357_source"),
                        default="",
                    )
                ),
                bool(
                    _normalize_text(
                        payload.get("prompt359_prompt358_selected_prompt_contract_path"),
                        default="",
                    )
                ),
            )
        )

    def _resolve_recovered_prompt359_evidence() -> dict[str, Any]:
        payload, source = _prompt358_find_latest_valid_prior_artifact(
            filename="prompt359_bounded_selected_step_execution_contract.json",
            validator=_valid_recovered_prompt359_payload,
        )
        normalized = _normalize_prompt359_surface(payload)
        return {
            "prompt360_recovered_prompt359_source": _normalize_text(
                source,
                default="",
            ),
            "prompt360_recovered_prompt359_contract_status": _normalize_text(
                normalized.get("prompt359_contract_status"),
                default="",
            ),
            "prompt360_recovered_prompt359_selected_step_execution_contract_ready": bool(
                normalized.get(
                    "prompt359_selected_step_execution_contract_ready",
                    False,
                )
            ),
            "prompt360_recovered_prompt359_selected_step_operation": _normalize_text(
                normalized.get("prompt359_selected_step_operation"),
                default="",
            ),
            "prompt360_recovered_prompt359_authoritative_next_action": _normalize_text(
                normalized.get("prompt359_authoritative_next_action"),
                default="",
            ),
            "prompt360_recovered_prompt359_next_action": _normalize_text(
                normalized.get("prompt359_next_action"),
                default="",
            ),
            "prompt360_recovered_prompt359_prompt358_recovered_evidence_used": bool(
                normalized.get("prompt359_prompt358_recovered_evidence_used", False)
            ),
            "prompt360_recovered_prompt359_prompt358_recovered_prompt355_source": (
                _normalize_text(
                    normalized.get("prompt359_prompt358_recovered_prompt355_source"),
                    default="",
                )
            ),
            "prompt360_recovered_prompt359_prompt358_recovered_prompt356_source": (
                _normalize_text(
                    normalized.get("prompt359_prompt358_recovered_prompt356_source"),
                    default="",
                )
            ),
            "prompt360_recovered_prompt359_prompt358_recovered_prompt357_source": (
                _normalize_text(
                    normalized.get("prompt359_prompt358_recovered_prompt357_source"),
                    default="",
                )
            ),
            "prompt360_recovered_prompt359_prompt358_selected_prompt_contract_path": (
                _normalize_text(
                    normalized.get("prompt359_prompt358_selected_prompt_contract_path"),
                    default="",
                )
            ),
        }

    def _resolve_safe_live_helper() -> tuple[bool, str]:
        if dry_run or not isinstance(adapter, CodexExecutorAdapter):
            return False, ""
        transport = getattr(adapter, "transport", None)
        if transport is None or isinstance(transport, DryRunCodexExecutionTransport):
            return False, ""
        transport_name = _normalize_text(type(transport).__name__, default="live_transport")
        return True, f"CodexExecutorAdapter:{transport_name}"

    def _resolve_live_timeout_seconds() -> int:
        transport = getattr(adapter, "transport", None) if adapter is not None else None
        timeout_seconds = _as_non_negative_int(
            getattr(transport, "timeout_seconds", 0),
            default=600,
        )
        if timeout_seconds <= 0:
            timeout_seconds = 600
        return timeout_seconds

    def _resolve_repo_path() -> str:
        transport = getattr(adapter, "transport", None) if adapter is not None else None
        return _normalize_text(
            execution_repo_path,
            default=_normalize_text(getattr(transport, "repo_path", ""), default=""),
        )

    def _resolve_bounded_prompt_source(
        *,
        selected_prompt_contract_path: str,
        recovered_prompt359_used: bool,
    ) -> dict[str, Any]:
        path_text = _normalize_text(selected_prompt_contract_path, default="")
        source_label = (
            "prompt360_recovered_prompt359_prompt358_selected_prompt_contract_path"
            if recovered_prompt359_used
            else "prompt359_prompt358_selected_prompt_contract_path"
        )
        if not path_text:
            return {
                "path": "",
                "status": "missing",
                "source": source_label,
            }
        prompt_path = Path(path_text)
        if not prompt_path.exists() or not prompt_path.is_file():
            return {
                "path": path_text,
                "status": "missing",
                "source": source_label,
            }
        try:
            prompt_text = prompt_path.read_text(encoding="utf-8")
        except OSError:
            return {
                "path": path_text,
                "status": "read_error",
                "source": source_label,
            }
        if not prompt_text.strip():
            return {
                "path": path_text,
                "status": "empty",
                "source": source_label,
            }
        return {
            "path": path_text,
            "status": "ready",
            "source": source_label,
        }

    def _run_prompt360_live_execution_once(
        *,
        helper_name: str,
        prompt_source_path: str,
        prompt_source_status: str,
        recovered_prompt359_source: str,
        recovered_prompt359_evidence_used: bool,
    ) -> dict[str, Any]:
        receipt_path = (
            run_root / "prompt360_bounded_codex_live_execution_receipt.json"
            if run_root is not None
            else Path("prompt360_bounded_codex_live_execution_receipt.json")
        )
        execution_work_dir = (
            run_root / "prompt360_bounded_codex_live_execution"
            if run_root is not None
            else Path("prompt360_bounded_codex_live_execution")
        )
        execution_work_dir.mkdir(parents=True, exist_ok=True)

        normalized_job_id = _normalize_text(job_id, default="")
        normalized_repo_path = _resolve_repo_path()
        live_timeout_seconds = _resolve_live_timeout_seconds()
        prompt360_pr_id = "prompt360__bounded_codex_live_execution_once"
        attempted = True
        execution_enabled = True
        execution_confirmed = False
        execution_status = "failed"
        returncode = 1
        stdout_path = ""
        stderr_path = ""
        started_at = _iso_now(now)
        completed_at = started_at
        command_args: list[str] = []
        safe_args_metadata: dict[str, Any] = {
            "helper_name": helper_name,
            "transport_mode": "live",
            "transport_class": _normalize_text(
                type(getattr(adapter, "transport", None)).__name__,
                default="",
            ),
            "invocation_mode": "adapter_launch_job_poll_collect",
            "shell": False,
            "argv_list_managed_by_transport": True,
            "work_dir": str(execution_work_dir),
            "prompt_source_status": prompt_source_status,
        }
        raw_transport_execution: dict[str, Any] = {}
        launch_response: dict[str, Any] = {}
        status_response: dict[str, Any] = {}
        artifact_response: dict[str, Any] = {}
        execution_error = ""

        if not isinstance(adapter, CodexExecutorAdapter):
            execution_status = "failed"
            returncode = 126
            execution_error = "prompt360_safe_live_helper_unavailable"
        else:
            try:
                launch_response = dict(
                    adapter.launch_job(
                        job_id=normalized_job_id,
                        pr_id=prompt360_pr_id,
                        prompt_path=prompt_source_path,
                        work_dir=str(execution_work_dir),
                        metadata={
                            "prompt360_bounded_live_execution": True,
                            "prompt360_bounded_live_execution_max_attempts": 1,
                            "prompt360_source_prompt": "prompt359",
                            "prompt360_source_action": (
                                "prepare_prompt360_codex_live_execution_gate"
                            ),
                            "prompt360_recovered_prompt359_source": (
                                recovered_prompt359_source
                            ),
                            "prompt360_recovered_prompt359_evidence_used": bool(
                                recovered_prompt359_evidence_used
                            ),
                            "validation_commands": [],
                            "requires_explicit_validation": False,
                            "strict_scope_files": [
                                "automation/orchestration/planned_execution_runner.py"
                            ],
                            "forbidden_files": [],
                        },
                    )
                )
                run_id = _normalize_text(launch_response.get("run_id"), default="")
                execution_confirmed = bool(run_id)
                if run_id:
                    status_response = dict(adapter.poll_status(run_id=run_id))
                    artifact_response = dict(adapter.collect_artifacts(run_id=run_id))
                else:
                    status_response = {
                        "status": "failed",
                        "error": "missing_run_id",
                    }
                    artifact_response = {
                        "stdout_path": "",
                        "stderr_path": "",
                        "artifacts": [],
                    }
            except Exception as exc:
                execution_confirmed = False
                status_response = {
                    "status": "failed",
                    "error": (
                        "prompt360_live_execution_launch_exception"
                        f" ({type(exc).__name__}): {exc}"
                    ),
                }
                artifact_response = {
                    "stdout_path": "",
                    "stderr_path": "",
                    "artifacts": [],
                }

            execution_status = _normalize_text(
                status_response.get("status") or launch_response.get("status"),
                default="failed",
            ).lower()
            if execution_status not in {
                "completed",
                "failed",
                "timed_out",
                "not_started",
                "running",
            }:
                execution_status = "failed"
            raw_transport = (
                dict(status_response.get("raw_transport"))
                if isinstance(status_response.get("raw_transport"), Mapping)
                else (
                    dict(artifact_response.get("raw_transport"))
                    if isinstance(artifact_response.get("raw_transport"), Mapping)
                    else {}
                )
            )
            raw_transport_execution = (
                dict(raw_transport.get("execution"))
                if isinstance(raw_transport.get("execution"), Mapping)
                else {}
            )
            command_args = (
                _normalize_string_list(
                    raw_transport_execution.get("command"),
                    sort_items=False,
                )
                if isinstance(raw_transport_execution.get("command"), (list, tuple))
                else []
            )
            maybe_returncode = _as_optional_int(
                raw_transport_execution.get("return_code")
            )
            if maybe_returncode is None:
                maybe_returncode = _as_optional_int(
                    raw_transport_execution.get("returncode")
                )
            if maybe_returncode is None:
                if execution_status == "completed":
                    maybe_returncode = 0
                elif execution_status == "timed_out":
                    maybe_returncode = 124
                else:
                    maybe_returncode = 1
            returncode = maybe_returncode
            stdout_path = _normalize_text(
                status_response.get("stdout_path")
                or artifact_response.get("stdout_path")
                or raw_transport_execution.get("stdout_path"),
                default="",
            )
            stderr_path = _normalize_text(
                status_response.get("stderr_path")
                or artifact_response.get("stderr_path")
                or raw_transport_execution.get("stderr_path"),
                default="",
            )
            started_at = _normalize_text(
                status_response.get("started_at")
                or raw_transport_execution.get("started_at"),
                default=started_at,
            )
            completed_at = _normalize_text(
                status_response.get("finished_at")
                or raw_transport_execution.get("finished_at"),
                default=_iso_now(now),
            )
            execution_error = _normalize_text(
                status_response.get("error")
                or raw_transport_execution.get("error"),
                default="",
            )

        receipt_payload: dict[str, Any] = {
            "attempted": attempted,
            "execution_enabled": execution_enabled,
            "execution_confirmed": execution_confirmed,
            "execution_status": execution_status,
            "command_args": command_args,
            "safe_args_metadata": safe_args_metadata,
            "returncode": returncode,
            "stdout_path": stdout_path,
            "stderr_path": stderr_path,
            "started_at": started_at,
            "completed_at": completed_at,
            "repo_path": normalized_repo_path,
            "job_id": normalized_job_id,
            "transport_mode": "live",
            "live_timeout_seconds": live_timeout_seconds,
            "prompt360_recovered_prompt359_source": recovered_prompt359_source,
            "prompt360_recovered_prompt359_evidence_used": bool(
                recovered_prompt359_evidence_used
            ),
            "prompt360_bounded_prompt_source_path": prompt_source_path,
            "prompt360_bounded_prompt_source_status": prompt_source_status,
            "prompt360_execution_error": execution_error,
        }
        receipt_written = False
        try:
            _write_json(receipt_path, receipt_payload)
            receipt_written = True
        except OSError:
            receipt_written = False

        execution_succeeded = bool(
            execution_confirmed
            and receipt_written
            and execution_status == "completed"
            and returncode == 0
        )
        if execution_succeeded:
            return {
                "prompt360_gate_status": "executed",
                "prompt360_execution_status": execution_status,
                "prompt360_live_execution_attempted": True,
                "prompt360_live_execution_allowed": True,
                "prompt360_codex_execution_allowed": True,
                "prompt360_execution_receipt_path": str(receipt_path),
                "prompt360_execution_receipt_written": bool(receipt_written),
                "prompt360_execution_returncode": returncode,
                "prompt360_authoritative_next_action": "capture_prompt360_execution_diff",
                "prompt360_next_action": "capture_prompt360_execution_diff",
                "prompt360_manual_required": False,
                "prompt360_replan_required": False,
                "prompt360_active_blocked_reason": "",
                "prompt360_active_blocked_reasons": [],
            }
        return {
            "prompt360_gate_status": "execution_failed",
            "prompt360_execution_status": execution_status,
            "prompt360_live_execution_attempted": True,
            "prompt360_live_execution_allowed": True,
            "prompt360_codex_execution_allowed": True,
            "prompt360_execution_receipt_path": str(receipt_path),
            "prompt360_execution_receipt_written": bool(receipt_written),
            "prompt360_execution_returncode": returncode,
            "prompt360_authoritative_next_action": "review_prompt360_execution_failure",
            "prompt360_next_action": "review_prompt360_execution_failure",
            "prompt360_manual_required": True,
            "prompt360_replan_required": False,
            "prompt360_active_blocked_reason": "prompt360_live_execution_failed",
            "prompt360_active_blocked_reasons": [
                "prompt360_live_execution_failed"
            ],
        }

    current_prompt359 = _normalize_prompt359_surface(run_state)
    current_prompt359_ready = not _prompt359_validation_reasons(current_prompt359)
    recovered_prompt359 = _resolve_recovered_prompt359_evidence()
    recovered_prompt359_available = bool(
        recovered_prompt359.get("prompt360_recovered_prompt359_source")
    )
    recovered_prompt359_used = bool(
        recovered_prompt359_available and not current_prompt359_ready
    )
    effective_prompt359 = (
        {
            "prompt359_contract_status": recovered_prompt359.get(
                "prompt360_recovered_prompt359_contract_status",
                "",
            ),
            "prompt359_selected_step_execution_contract_ready": bool(
                recovered_prompt359.get(
                    "prompt360_recovered_prompt359_selected_step_execution_contract_ready",
                    False,
                )
            ),
            "prompt359_selected_step_operation": recovered_prompt359.get(
                "prompt360_recovered_prompt359_selected_step_operation",
                "",
            ),
            "prompt359_authoritative_next_action": recovered_prompt359.get(
                "prompt360_recovered_prompt359_authoritative_next_action",
                "",
            ),
            "prompt359_next_action": recovered_prompt359.get(
                "prompt360_recovered_prompt359_next_action",
                "",
            ),
            "prompt359_manual_required": False,
            "prompt359_replan_required": False,
            "prompt359_active_blocked_reason": "",
            "prompt359_active_blocked_reasons": [],
            "prompt359_prompt358_recovered_evidence_used": bool(
                recovered_prompt359.get(
                    "prompt360_recovered_prompt359_prompt358_recovered_evidence_used",
                    False,
                )
            ),
            "prompt359_prompt358_recovered_prompt355_source": recovered_prompt359.get(
                "prompt360_recovered_prompt359_prompt358_recovered_prompt355_source",
                "",
            ),
            "prompt359_prompt358_recovered_prompt356_source": recovered_prompt359.get(
                "prompt360_recovered_prompt359_prompt358_recovered_prompt356_source",
                "",
            ),
            "prompt359_prompt358_recovered_prompt357_source": recovered_prompt359.get(
                "prompt360_recovered_prompt359_prompt358_recovered_prompt357_source",
                "",
            ),
            "prompt359_prompt358_selected_prompt_contract_path": _normalize_text(
                recovered_prompt359.get(
                    "prompt360_recovered_prompt359_prompt358_selected_prompt_contract_path"
                ),
                default="",
            ),
        }
        if recovered_prompt359_used
        else current_prompt359
    )
    active_blocked_reasons = _prompt359_validation_reasons(effective_prompt359)

    explicit_live_execution_enabled = not bool(dry_run)
    transport_mode = "live" if explicit_live_execution_enabled else "dry-run"
    safe_live_helper_found, safe_live_helper_name = _resolve_safe_live_helper()
    bounded_prompt_source = _resolve_bounded_prompt_source(
        selected_prompt_contract_path=_normalize_text(
            effective_prompt359.get("prompt359_prompt358_selected_prompt_contract_path"),
            default="",
        ),
        recovered_prompt359_used=recovered_prompt359_used,
    )
    prompt360_bounded_prompt_source_path = _normalize_text(
        bounded_prompt_source.get("path"),
        default="",
    )
    prompt360_bounded_prompt_source_status = _normalize_text(
        bounded_prompt_source.get("status"),
        default="missing",
    )
    prompt360_execution_receipt_written = False
    prompt360_execution_returncode = 0
    prompt360_suppressed_for_prompt379_explicit_execution = bool(
        suppress_for_prompt379_explicit_execution
    )

    if prompt360_suppressed_for_prompt379_explicit_execution:
        gate_status = "suppressed_for_prompt379_explicit_execution"
        execution_status = "not_run"
        live_execution_attempted = False
        live_execution_allowed = False
        codex_execution_allowed = False
        execution_receipt_path = ""
        prompt360_execution_receipt_written = False
        prompt360_execution_returncode = 0
        authoritative_next_action = "continue_to_prompt379_explicit_execution"
        next_action = "continue_to_prompt379_explicit_execution"
        manual_required = False
        replan_required = False
        active_blocked_reason = ""
        normalized_active_blocked_reasons = []
        summary = (
            "Prompt360 live execution was suppressed because Prompt379 explicit "
            "execution is active; Prompt360 remained metadata-only to avoid "
            "pre-Prompt379 tracked source mutation."
        )
    elif active_blocked_reasons:
        gate_status = "blocked"
        execution_status = "not_run"
        live_execution_attempted = False
        live_execution_allowed = False
        codex_execution_allowed = False
        execution_receipt_path = ""
        prompt360_execution_receipt_written = False
        prompt360_execution_returncode = 0
        authoritative_next_action = "hold_for_followup"
        next_action = "hold_for_followup"
        manual_required = True
        replan_required = False
        active_blocked_reason = active_blocked_reasons[0]
        normalized_active_blocked_reasons = active_blocked_reasons
        summary = "Prompt360 blocked: " + ", ".join(normalized_active_blocked_reasons)
    elif not explicit_live_execution_enabled:
        gate_status = "ready_for_live_execution"
        execution_status = "not_run"
        live_execution_attempted = False
        live_execution_allowed = False
        codex_execution_allowed = False
        execution_receipt_path = ""
        prompt360_execution_receipt_written = False
        prompt360_execution_returncode = 0
        authoritative_next_action = "run_with_explicit_live_execution_flags"
        next_action = "run_prompt360_with_explicit_live_execution_flags"
        manual_required = False
        replan_required = False
        active_blocked_reason = ""
        normalized_active_blocked_reasons = []
        if recovered_prompt359_used:
            summary = (
                "Prompt360 accepted recovered Prompt359 evidence for explicit live execution readiness, but dry-run/default mode keeps Codex execution disabled."
            )
        else:
            summary = (
                "Prompt360 is ready for explicit live execution, but dry-run/default mode keeps Codex execution disabled."
            )
    elif not safe_live_helper_found:
        gate_status = "blocked_unsupported_live_execution_helper_missing"
        execution_status = "not_run"
        live_execution_attempted = False
        live_execution_allowed = False
        codex_execution_allowed = False
        execution_receipt_path = ""
        prompt360_execution_receipt_written = False
        prompt360_execution_returncode = 0
        authoritative_next_action = "hold_for_followup"
        next_action = "hold_for_followup"
        manual_required = True
        replan_required = False
        active_blocked_reason = "safe_live_execution_helper_missing"
        normalized_active_blocked_reasons = [
            "safe_live_execution_helper_missing"
        ]
        if recovered_prompt359_used:
            summary = (
                "Prompt360 accepted recovered Prompt359 evidence, but live execution remains blocked because no clearly reusable safe live helper is bound to the Prompt359 contract artifacts."
            )
        else:
            summary = (
                "Prompt360 live execution remains blocked because no clearly reusable safe live helper is bound to the Prompt359 contract artifacts."
            )
    elif prompt360_bounded_prompt_source_status != "ready":
        gate_status = "blocked_missing_bounded_execution_prompt"
        execution_status = "not_run"
        live_execution_attempted = False
        live_execution_allowed = False
        codex_execution_allowed = False
        execution_receipt_path = ""
        prompt360_execution_receipt_written = False
        prompt360_execution_returncode = 0
        authoritative_next_action = "prepare_bounded_execution_prompt"
        next_action = "prepare_bounded_execution_prompt"
        manual_required = True
        replan_required = False
        active_blocked_reason = "bounded_execution_prompt_missing"
        normalized_active_blocked_reasons = [
            "bounded_execution_prompt_missing"
        ]
        if recovered_prompt359_used:
            summary = (
                "Prompt360 accepted recovered Prompt359 evidence, but explicit live execution remains blocked because the bounded Prompt359/Prompt360 prompt artifact is unavailable."
            )
        else:
            summary = (
                "Prompt360 explicit live execution remains blocked because the bounded Prompt359/Prompt360 prompt artifact is unavailable."
            )
    else:
        execution_attempt_state = _run_prompt360_live_execution_once(
            helper_name=safe_live_helper_name,
            prompt_source_path=prompt360_bounded_prompt_source_path,
            prompt_source_status=prompt360_bounded_prompt_source_status,
            recovered_prompt359_source=_normalize_text(
                recovered_prompt359.get("prompt360_recovered_prompt359_source"),
                default="",
            ),
            recovered_prompt359_evidence_used=bool(recovered_prompt359_used),
        )
        gate_status = _normalize_text(
            execution_attempt_state.get("prompt360_gate_status"),
            default="execution_failed",
        )
        execution_status = _normalize_text(
            execution_attempt_state.get("prompt360_execution_status"),
            default="failed",
        )
        live_execution_attempted = bool(
            execution_attempt_state.get("prompt360_live_execution_attempted", False)
        )
        live_execution_allowed = bool(
            execution_attempt_state.get("prompt360_live_execution_allowed", False)
        )
        codex_execution_allowed = bool(
            execution_attempt_state.get("prompt360_codex_execution_allowed", False)
        )
        execution_receipt_path = _normalize_text(
            execution_attempt_state.get("prompt360_execution_receipt_path"),
            default="",
        )
        prompt360_execution_receipt_written = bool(
            execution_attempt_state.get("prompt360_execution_receipt_written", False)
        )
        prompt360_execution_returncode = _as_non_negative_int(
            execution_attempt_state.get("prompt360_execution_returncode"),
            default=0,
        )
        authoritative_next_action = _normalize_text(
            execution_attempt_state.get("prompt360_authoritative_next_action"),
            default="review_prompt360_execution_failure",
        )
        next_action = _normalize_text(
            execution_attempt_state.get("prompt360_next_action"),
            default="review_prompt360_execution_failure",
        )
        manual_required = bool(
            execution_attempt_state.get("prompt360_manual_required", True)
        )
        replan_required = bool(
            execution_attempt_state.get("prompt360_replan_required", False)
        )
        active_blocked_reason = _normalize_text(
            execution_attempt_state.get("prompt360_active_blocked_reason"),
            default="",
        )
        normalized_active_blocked_reasons = _normalize_string_list(
            execution_attempt_state.get("prompt360_active_blocked_reasons"),
            sort_items=False,
        )
        if gate_status == "executed":
            summary = (
                "Prompt360 performed one bounded live Codex execution through the existing safe execution adapter and captured a receipt."
            )
        else:
            summary = (
                "Prompt360 attempted one bounded live Codex execution through the existing safe execution adapter, but the execution did not complete successfully."
            )

    return {
        "prompt360_gate_status": gate_status,
        "prompt360_source_prompt": "prompt359",
        "prompt360_source_action": "prepare_prompt360_codex_live_execution_gate",
        "prompt360_transport_mode": transport_mode,
        "prompt360_live_execution_attempted": bool(live_execution_attempted),
        "prompt360_live_execution_allowed": bool(live_execution_allowed),
        "prompt360_codex_execution_allowed": bool(codex_execution_allowed),
        "prompt360_suppressed_for_prompt379_explicit_execution": (
            prompt360_suppressed_for_prompt379_explicit_execution
        ),
        "prompt360_execution_status": execution_status,
        "prompt360_execution_receipt_path": execution_receipt_path,
        "prompt360_safe_live_helper_found": bool(safe_live_helper_found),
        "prompt360_safe_live_helper_name": safe_live_helper_name,
        "prompt360_bounded_prompt_source_path": prompt360_bounded_prompt_source_path,
        "prompt360_bounded_prompt_source_status": (
            prompt360_bounded_prompt_source_status
        ),
        "prompt360_execution_receipt_written": bool(
            prompt360_execution_receipt_written
        ),
        "prompt360_execution_returncode": int(prompt360_execution_returncode),
        "prompt360_authoritative_next_action": authoritative_next_action,
        "prompt360_next_action": next_action,
        "prompt360_manual_required": bool(manual_required),
        "prompt360_replan_required": bool(replan_required),
        "prompt360_active_blocked_reason": active_blocked_reason,
        "prompt360_active_blocked_reasons": normalized_active_blocked_reasons,
        "prompt360_recovered_prompt359_evidence_used": bool(
            recovered_prompt359_used
        ),
        "prompt360_recovered_prompt359_source": _normalize_text(
            recovered_prompt359.get("prompt360_recovered_prompt359_source"),
            default="",
        ),
        "prompt360_recovered_prompt359_contract_status": _normalize_text(
            recovered_prompt359.get("prompt360_recovered_prompt359_contract_status"),
            default="",
        ),
        "prompt360_recovered_prompt359_selected_step_execution_contract_ready": bool(
            recovered_prompt359.get(
                "prompt360_recovered_prompt359_selected_step_execution_contract_ready",
                False,
            )
        ),
        "prompt360_recovered_prompt359_selected_step_operation": _normalize_text(
            recovered_prompt359.get("prompt360_recovered_prompt359_selected_step_operation"),
            default="",
        ),
        "prompt360_recovered_prompt359_authoritative_next_action": _normalize_text(
            recovered_prompt359.get(
                "prompt360_recovered_prompt359_authoritative_next_action"
            ),
            default="",
        ),
        "prompt360_recovered_prompt359_next_action": _normalize_text(
            recovered_prompt359.get("prompt360_recovered_prompt359_next_action"),
            default="",
        ),
        "prompt360_recovered_prompt359_prompt358_recovered_evidence_used": bool(
            recovered_prompt359.get(
                "prompt360_recovered_prompt359_prompt358_recovered_evidence_used",
                False,
            )
        ),
        "prompt360_recovered_prompt359_prompt358_recovered_prompt355_source": (
            _normalize_text(
                recovered_prompt359.get(
                    "prompt360_recovered_prompt359_prompt358_recovered_prompt355_source"
                ),
                default="",
            )
        ),
        "prompt360_recovered_prompt359_prompt358_recovered_prompt356_source": (
            _normalize_text(
                recovered_prompt359.get(
                    "prompt360_recovered_prompt359_prompt358_recovered_prompt356_source"
                ),
                default="",
            )
        ),
        "prompt360_recovered_prompt359_prompt358_recovered_prompt357_source": (
            _normalize_text(
                recovered_prompt359.get(
                    "prompt360_recovered_prompt359_prompt358_recovered_prompt357_source"
                ),
                default="",
            )
        ),
        "prompt360_summary": summary,
    }

def _build_prompt361_post_execution_diff_capture(
    *,
    run_state_payload: Mapping[str, Any] | None,
    run_root: Path | None = None,
    execution_repo_path: str = "",
    current_prompt360_source_path: str = "",
    suppress_for_prompt379_explicit_execution: bool = False,
) -> dict[str, Any]:
    run_state = dict(run_state_payload or {})
    artifact_root = run_root if run_root is not None else Path(".")
    prompt361_json_path = artifact_root / "prompt361_post_execution_diff_capture.json"
    prompt361_patch_path = artifact_root / "prompt361_post_execution_tracked.patch"
    prompt361_report_path = artifact_root / "prompt361_post_execution_diff_report.txt"
    normalized_patch_path = _normalize_text(str(prompt361_patch_path), default="")
    normalized_report_path = _normalize_text(str(prompt361_report_path), default="")

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    def _normalize_prompt360_surface(payload: Mapping[str, Any] | None) -> dict[str, Any]:
        source = dict(payload) if isinstance(payload, Mapping) else {}
        return {
            "prompt360_gate_status": _normalize_text(
                source.get("prompt360_gate_status"),
                default="",
            ),
            "prompt360_source_prompt": _normalize_text(
                source.get("prompt360_source_prompt"),
                default="",
            ),
            "prompt360_source_action": _normalize_text(
                source.get("prompt360_source_action"),
                default="",
            ),
            "prompt360_execution_status": _normalize_text(
                source.get("prompt360_execution_status"),
                default="",
            ),
            "prompt360_execution_receipt_path": _normalize_text(
                source.get("prompt360_execution_receipt_path"),
                default="",
            ),
            "prompt360_live_execution_attempted": _prompt357_as_boolish(
                source.get("prompt360_live_execution_attempted")
            ),
            "prompt360_live_execution_allowed": _prompt357_as_boolish(
                source.get("prompt360_live_execution_allowed")
            ),
            "prompt360_codex_execution_allowed": _prompt357_as_boolish(
                source.get("prompt360_codex_execution_allowed")
            ),
            "prompt360_execution_receipt_written": _prompt357_as_boolish(
                source.get("prompt360_execution_receipt_written")
            ),
            "prompt360_execution_returncode": _as_non_negative_int(
                source.get("prompt360_execution_returncode"),
                default=0,
            ),
            "prompt360_authoritative_next_action": _normalize_text(
                source.get("prompt360_authoritative_next_action"),
                default="",
            ),
            "prompt360_next_action": _normalize_text(
                source.get("prompt360_next_action"),
                default="",
            ),
            "prompt360_manual_required": _prompt357_as_boolish(
                source.get("prompt360_manual_required")
            ),
            "prompt360_replan_required": _prompt357_as_boolish(
                source.get("prompt360_replan_required")
            ),
            "prompt360_active_blocked_reason": _normalize_text(
                source.get("prompt360_active_blocked_reason"),
                default="",
            ),
            "prompt360_active_blocked_reasons": _normalize_string_list(
                source.get("prompt360_active_blocked_reasons"),
                sort_items=False,
            ),
        }

    def _valid_prompt360_executed_payload(payload: Mapping[str, Any] | None) -> bool:
        if not isinstance(payload, Mapping):
            return False
        active_blocked_reasons = payload.get("prompt360_active_blocked_reasons")
        return all(
            (
                _prompt358_required_text_match(
                    payload,
                    "prompt360_gate_status",
                    "executed",
                ),
                _prompt358_required_text_match(
                    payload,
                    "prompt360_execution_status",
                    "completed",
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt360_live_execution_attempted",
                    True,
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt360_live_execution_allowed",
                    True,
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt360_codex_execution_allowed",
                    True,
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt360_execution_receipt_written",
                    True,
                ),
                _as_non_negative_int(
                    payload.get("prompt360_execution_returncode"),
                    default=-1,
                )
                == 0,
                bool(
                    _normalize_text(
                        payload.get("prompt360_execution_receipt_path"),
                        default="",
                    )
                ),
                _prompt358_required_text_match(
                    payload,
                    "prompt360_authoritative_next_action",
                    "capture_prompt360_execution_diff",
                ),
                _prompt358_required_text_match(
                    payload,
                    "prompt360_next_action",
                    "capture_prompt360_execution_diff",
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt360_manual_required",
                    False,
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt360_replan_required",
                    False,
                ),
                "prompt360_active_blocked_reason" in payload,
                _normalize_text(
                    payload.get("prompt360_active_blocked_reason"),
                    default="",
                )
                == "",
                isinstance(active_blocked_reasons, list),
                _normalize_string_list(active_blocked_reasons, sort_items=False) == [],
            )
        )

    def _prompt360_ready_for_live_execution(payload: Mapping[str, Any] | None) -> bool:
        if not isinstance(payload, Mapping):
            return False
        active_blocked_reasons = payload.get("prompt360_active_blocked_reasons")
        return all(
            (
                _prompt358_required_text_match(
                    payload,
                    "prompt360_gate_status",
                    "ready_for_live_execution",
                ),
                _prompt358_required_text_match(
                    payload,
                    "prompt360_execution_status",
                    "not_run",
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt360_live_execution_attempted",
                    False,
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt360_live_execution_allowed",
                    False,
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt360_codex_execution_allowed",
                    False,
                ),
                _prompt358_required_text_match(
                    payload,
                    "prompt360_next_action",
                    "run_prompt360_with_explicit_live_execution_flags",
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt360_manual_required",
                    False,
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt360_replan_required",
                    False,
                ),
                "prompt360_active_blocked_reason" in payload,
                _normalize_text(
                    payload.get("prompt360_active_blocked_reason"),
                    default="",
                )
                == "",
                isinstance(active_blocked_reasons, list),
                _normalize_string_list(active_blocked_reasons, sort_items=False) == [],
            )
        )

    def _resolve_prompt361_recovered_prompt360_executed_evidence() -> tuple[dict[str, Any], str]:
        # Prompt361 may see a regenerated Prompt360 dry-run gate in the current runtime.
        # Recover only the newest prior executed Prompt360 gate artifact that passes the
        # strict executed-evidence validator.
        payload, source = _prompt358_find_latest_valid_prior_artifact(
            filename="prompt360_bounded_codex_live_execution_gate.json",
            validator=_valid_prompt360_executed_payload,
        )
        return _normalize_prompt360_surface(payload), _normalize_text(source, default="")

    def _derive_prompt360_invalid_reasons(
        surface: Mapping[str, Any] | None,
        *,
        fallback_missing_reason: str,
    ) -> list[str]:
        normalized = dict(surface) if isinstance(surface, Mapping) else {}
        reasons: list[str] = []
        gate_status = _normalize_text(normalized.get("prompt360_gate_status"), default="")
        execution_status = _normalize_text(
            normalized.get("prompt360_execution_status"),
            default="",
        )
        if not gate_status:
            _append_reason(reasons, fallback_missing_reason)
            return reasons
        if gate_status != "executed":
            active_reasons = _normalize_string_list(
                normalized.get("prompt360_active_blocked_reasons"),
                sort_items=False,
            )
            if active_reasons:
                for active_reason in active_reasons:
                    _append_reason(reasons, active_reason)
            else:
                _append_reason(reasons, f"prompt360_gate_status_{gate_status}")
            if gate_status == "ready_for_live_execution":
                _append_reason(
                    reasons,
                    "prompt360_live_execution_not_attempted",
                )
            return reasons
        if execution_status != "completed":
            _append_reason(
                reasons,
                f"prompt360_execution_status_{execution_status or 'missing'}",
            )
        if not bool(normalized.get("prompt360_live_execution_attempted", False)):
            _append_reason(reasons, "prompt360_live_execution_attempted_not_true")
        if not bool(normalized.get("prompt360_live_execution_allowed", False)):
            _append_reason(reasons, "prompt360_live_execution_allowed_not_true")
        if not bool(normalized.get("prompt360_codex_execution_allowed", False)):
            _append_reason(reasons, "prompt360_codex_execution_allowed_not_true")
        if not bool(normalized.get("prompt360_execution_receipt_written", False)):
            _append_reason(reasons, "prompt360_execution_receipt_written_not_true")
        if (
            _as_non_negative_int(
                normalized.get("prompt360_execution_returncode"),
                default=-1,
            )
            != 0
        ):
            _append_reason(reasons, "prompt360_execution_returncode_not_zero")
        if not _normalize_text(
            normalized.get("prompt360_execution_receipt_path"),
            default="",
        ):
            _append_reason(reasons, "prompt360_execution_receipt_path_missing")
        if (
            _normalize_text(
                normalized.get("prompt360_authoritative_next_action"),
                default="",
            )
            != "capture_prompt360_execution_diff"
        ):
            _append_reason(
                reasons,
                "prompt360_authoritative_next_action_not_capture_prompt360_execution_diff",
            )
        if (
            _normalize_text(normalized.get("prompt360_next_action"), default="")
            != "capture_prompt360_execution_diff"
        ):
            _append_reason(
                reasons,
                "prompt360_next_action_not_capture_prompt360_execution_diff",
            )
        if bool(normalized.get("prompt360_manual_required", False)):
            _append_reason(reasons, "prompt360_manual_required_true")
        if bool(normalized.get("prompt360_replan_required", False)):
            _append_reason(reasons, "prompt360_replan_required_true")
        active_blocked_reason = _normalize_text(
            normalized.get("prompt360_active_blocked_reason"),
            default="",
        )
        if active_blocked_reason:
            _append_reason(reasons, active_blocked_reason)
        active_blocked_reasons = _normalize_string_list(
            normalized.get("prompt360_active_blocked_reasons"),
            sort_items=False,
        )
        for active_reason in active_blocked_reasons:
            _append_reason(reasons, active_reason)
        if not reasons:
            _append_reason(reasons, fallback_missing_reason)
        return reasons

    def _write_prompt361_artifacts(
        *,
        payload: Mapping[str, Any],
        patch_text: str,
        report_lines: list[str],
    ) -> None:
        prompt361_json_path.parent.mkdir(parents=True, exist_ok=True)
        prompt361_patch_path.write_text(patch_text, encoding="utf-8")
        prompt361_report_path.write_text("\n".join(report_lines) + "\n", encoding="utf-8")
        _write_json(prompt361_json_path, payload)

    def _build_prompt361_state(
        *,
        diff_capture_status: str,
        prompt360_surface: Mapping[str, Any],
        prompt360_source_path: str,
        recovered_prompt360_evidence_used: bool,
        tracked_diff_present: bool,
        changed_tracked_files: list[str],
        review_handoff_ready: bool,
        next_action: str,
        manual_required: bool,
        replan_required: bool,
        blocked_reasons: list[str],
        summary: str,
    ) -> dict[str, Any]:
        normalized_blocked_reasons = _normalize_string_list(
            blocked_reasons,
            sort_items=False,
        )
        prompt379_suppressed = bool(suppress_for_prompt379_explicit_execution)
        return {
            "prompt361_diff_capture_status": diff_capture_status,
            "prompt361_suppressed_for_prompt379_explicit_execution": (
                prompt379_suppressed
            ),
            "prompt361_recovered_prompt360_evidence_ignored_for_prompt379_explicit_execution": bool(
                prompt379_suppressed and not recovered_prompt360_evidence_used
            ),
            "pre_prompt379_prompt360_continuation_suppressed": prompt379_suppressed,
            "prompt361_source_prompt": "prompt360",
            "prompt361_source_action": "capture_prompt360_execution_diff",
            "prompt361_prompt360_gate_status": _normalize_text(
                prompt360_surface.get("prompt360_gate_status"),
                default="",
            ),
            "prompt361_prompt360_execution_status": _normalize_text(
                prompt360_surface.get("prompt360_execution_status"),
                default="",
            ),
            "prompt361_prompt360_execution_receipt_path": _normalize_text(
                prompt360_surface.get("prompt360_execution_receipt_path"),
                default="",
            ),
            "prompt361_prompt360_source_path": _normalize_text(
                prompt360_source_path,
                default="",
            ),
            "prompt361_recovered_prompt360_evidence_used": bool(
                recovered_prompt360_evidence_used
            ),
            "prompt361_tracked_diff_present": bool(tracked_diff_present),
            "prompt361_changed_tracked_files": list(changed_tracked_files),
            "prompt361_untracked_files_ignored": True,
            "prompt361_patch_path": normalized_patch_path,
            "prompt361_diff_report_path": normalized_report_path,
            "prompt361_review_handoff_ready": bool(review_handoff_ready),
            "prompt361_authoritative_next_action": _normalize_text(
                next_action,
                default="hold_for_followup",
            ),
            "prompt361_next_action": _normalize_text(
                next_action,
                default="hold_for_followup",
            ),
            "prompt361_manual_required": bool(manual_required),
            "prompt361_replan_required": bool(replan_required),
            "prompt361_active_blocked_reason": (
                normalized_blocked_reasons[0] if normalized_blocked_reasons else ""
            ),
            "prompt361_active_blocked_reasons": normalized_blocked_reasons,
            "prompt361_summary": _normalize_text(summary, default=""),
        }

    def _write_and_return(
        *,
        state: Mapping[str, Any],
        report_lines: list[str],
        patch_text: str = "",
    ) -> dict[str, Any]:
        _write_prompt361_artifacts(
            payload=state,
            patch_text=patch_text,
            report_lines=report_lines,
        )
        return dict(state)

    current_prompt360 = _normalize_prompt360_surface(run_state)
    current_prompt360_source = _normalize_text(current_prompt360_source_path, default="")
    current_prompt360_valid_executed = _valid_prompt360_executed_payload(run_state)
    current_prompt360_ready = _prompt360_ready_for_live_execution(run_state)
    prompt379_explicit_suppression_active = bool(
        suppress_for_prompt379_explicit_execution
        or run_state.get("prompt379_explicit_execution_active", False)
        or run_state.get("prompt360_suppressed_for_prompt379_explicit_execution", False)
    )
    recovered_prompt360, recovered_prompt360_source = ({}, "")
    recovered_prompt360_used = False
    if prompt379_explicit_suppression_active:
        suppress_for_prompt379_explicit_execution = True
    if not current_prompt360_valid_executed and not prompt379_explicit_suppression_active:
        (
            recovered_prompt360,
            recovered_prompt360_source,
        ) = _resolve_prompt361_recovered_prompt360_executed_evidence()
        recovered_prompt360_used = bool(recovered_prompt360_source)

    effective_prompt360 = (
        recovered_prompt360 if recovered_prompt360_used else current_prompt360
    )
    effective_prompt360_source = (
        recovered_prompt360_source if recovered_prompt360_used else current_prompt360_source
    )
    effective_prompt360_valid_executed = bool(
        recovered_prompt360_used or current_prompt360_valid_executed
    )
    normalized_repo_path = _normalize_text(
        execution_repo_path,
        default=str(Path.cwd()),
    )

    patch_text = ""
    report_lines = [
        "Prompt361 Post-Execution Diff Report",
        "",
        "- Source prompt: prompt360",
        "- Source action: capture_prompt360_execution_diff",
        f"- Prompt360 source path: {effective_prompt360_source or '(missing)'}",
    ]

    if prompt379_explicit_suppression_active:
        state = _build_prompt361_state(
            diff_capture_status="suppressed_for_prompt379_explicit_execution",
            prompt360_surface=current_prompt360,
            prompt360_source_path=current_prompt360_source,
            recovered_prompt360_evidence_used=False,
            tracked_diff_present=False,
            changed_tracked_files=[],
            review_handoff_ready=False,
            next_action="continue_to_prompt379_explicit_execution",
            manual_required=False,
            replan_required=False,
            blocked_reasons=[],
            summary=(
                "Prompt361 ignored recovered Prompt360 execution evidence because "
                "Prompt379 explicit execution is active; post-execution diff "
                "capture stayed metadata-only to avoid pre-Prompt379 tracked "
                "source mutation."
            ),
        )
        suppressed_report_lines = [
            *report_lines,
            f"- Prompt361 status: {state['prompt361_diff_capture_status']}",
            "- Recovered Prompt360 evidence used: false",
            "- Prompt360 continuation suppressed for Prompt379 explicit execution: true",
            f"- Next action: {state['prompt361_next_action']}",
        ]
        return _write_and_return(
            state=state,
            report_lines=suppressed_report_lines,
            patch_text=patch_text,
        )

    def _emit_blocked(
        *,
        prompt360_surface: Mapping[str, Any],
        prompt360_source_path: str,
        recovered_used: bool,
        blocked_reasons: list[str],
        summary: str,
    ) -> dict[str, Any]:
        state = _build_prompt361_state(
            diff_capture_status="blocked",
            prompt360_surface=prompt360_surface,
            prompt360_source_path=prompt360_source_path,
            recovered_prompt360_evidence_used=recovered_used,
            tracked_diff_present=False,
            changed_tracked_files=[],
            review_handoff_ready=False,
            next_action="hold_for_followup",
            manual_required=True,
            replan_required=False,
            blocked_reasons=blocked_reasons,
            summary=summary,
        )
        blocked_report_lines = [
            *report_lines,
            f"- Prompt361 status: {state['prompt361_diff_capture_status']}",
            f"- Review handoff ready: {str(state['prompt361_review_handoff_ready']).lower()}",
            f"- Blocked reason: {state['prompt361_active_blocked_reason']}",
        ]
        return _write_and_return(
            state=state,
            report_lines=blocked_report_lines,
            patch_text=patch_text,
        )

    if effective_prompt360_valid_executed:
        if not normalized_repo_path:
            return _emit_blocked(
                prompt360_surface=effective_prompt360,
                prompt360_source_path=effective_prompt360_source,
                recovered_used=recovered_prompt360_used,
                blocked_reasons=["prompt361_execution_repo_path_missing"],
                summary=(
                    "Prompt361 blocked because the execution repository path is unavailable for tracked diff capture."
                ),
            )
        if not shutil.which("git"):
            return _emit_blocked(
                prompt360_surface=effective_prompt360,
                prompt360_source_path=effective_prompt360_source,
                recovered_used=recovered_prompt360_used,
                blocked_reasons=["prompt361_git_unavailable"],
                summary=(
                    "Prompt361 blocked because git is unavailable for tracked diff capture."
                ),
            )

        git_commands = {
            "status_short": ["git", "status", "--short", "--untracked-files=no"],
            "diff_name_only": ["git", "diff", "--name-only"],
            "diff_stat": ["git", "diff", "--stat"],
            "diff_patch": ["git", "diff", "--no-ext-diff", "--binary"],
        }
        git_outputs: dict[str, str] = {}
        git_failed_reasons: list[str] = []
        for command_key, command in git_commands.items():
            completed = subprocess.run(
                command,
                text=True,
                capture_output=True,
                check=False,
                cwd=normalized_repo_path,
                shell=False,
            )
            git_outputs[command_key] = completed.stdout or ""
            if completed.returncode != 0:
                _append_reason(
                    git_failed_reasons,
                    f"prompt361_{command_key}_command_failed",
                )
        if git_failed_reasons:
            return _emit_blocked(
                prompt360_surface=effective_prompt360,
                prompt360_source_path=effective_prompt360_source,
                recovered_used=recovered_prompt360_used,
                blocked_reasons=git_failed_reasons,
                summary="Prompt361 blocked because tracked git diff capture failed.",
            )

        changed_from_status = [
            path_text
            for path_text in (
                _parse_git_status_path(raw_line.rstrip("\n"))
                for raw_line in (git_outputs.get("status_short") or "").splitlines()
            )
            if path_text
        ]
        changed_from_diff = [
            line.strip()
            for line in (git_outputs.get("diff_name_only") or "").splitlines()
            if line.strip()
        ]
        changed_tracked_files = sorted(set(changed_from_status + changed_from_diff))
        patch_text = git_outputs.get("diff_patch", "")
        tracked_diff_present = bool(changed_tracked_files)
        next_action = (
            "prepare_post_execution_review"
            if tracked_diff_present
            else "prepare_no_change_review"
        )
        state = _build_prompt361_state(
            diff_capture_status=(
                "captured" if tracked_diff_present else "captured_no_diff"
            ),
            prompt360_surface=effective_prompt360,
            prompt360_source_path=effective_prompt360_source,
            recovered_prompt360_evidence_used=recovered_prompt360_used,
            tracked_diff_present=tracked_diff_present,
            changed_tracked_files=changed_tracked_files,
            review_handoff_ready=True,
            next_action=next_action,
            manual_required=False,
            replan_required=False,
            blocked_reasons=[],
            summary=(
                "Prompt361 captured tracked post-execution git diff artifacts and marked the run ready for review handoff."
                if tracked_diff_present
                else "Prompt361 captured tracked post-execution git diff artifacts, found no tracked changes, and marked the run ready for no-change review."
            ),
        )
        capture_report_lines = [
            *report_lines,
            f"- Prompt361 status: {state['prompt361_diff_capture_status']}",
            f"- Review handoff ready: {str(state['prompt361_review_handoff_ready']).lower()}",
            f"- Recovered Prompt360 evidence used: {str(recovered_prompt360_used).lower()}",
            f"- Tracked diff present: {str(tracked_diff_present).lower()}",
            "",
            "## Commands",
            "- git status --short --untracked-files=no",
            "- git diff --name-only",
            "- git diff --stat",
            "- git diff --no-ext-diff --binary",
            "",
            "## Changed Tracked Files",
        ]
        if changed_tracked_files:
            capture_report_lines.extend(f"- {path}" for path in changed_tracked_files)
        else:
            capture_report_lines.append("- None")
        capture_report_lines.extend(
            [
                "",
                "## git status --short --untracked-files=no",
                (git_outputs.get("status_short") or "").rstrip("\n")
                or "(no tracked changes)",
                "",
                "## git diff --stat",
                (git_outputs.get("diff_stat") or "").rstrip("\n")
                or "(no tracked diff)",
            ]
        )
        return _write_and_return(
            state=state,
            report_lines=capture_report_lines,
            patch_text=patch_text,
        )

    if current_prompt360_ready:
        state = _build_prompt361_state(
            diff_capture_status="waiting_for_prompt360_live_execution",
            prompt360_surface=current_prompt360,
            prompt360_source_path=current_prompt360_source,
            recovered_prompt360_evidence_used=False,
            tracked_diff_present=False,
            changed_tracked_files=[],
            review_handoff_ready=False,
            next_action="run_prompt360_with_explicit_live_execution_flags",
            manual_required=False,
            replan_required=False,
            blocked_reasons=[],
            summary=(
                "Prompt361 is waiting for Prompt360 explicit live execution before tracked diff capture can begin."
            ),
        )
        waiting_report_lines = [
            *report_lines,
            f"- Prompt361 status: {state['prompt361_diff_capture_status']}",
            f"- Review handoff ready: {str(state['prompt361_review_handoff_ready']).lower()}",
            f"- Next action: {state['prompt361_next_action']}",
        ]
        return _write_and_return(
            state=state,
            report_lines=waiting_report_lines,
            patch_text=patch_text,
        )

    blocked_reasons = _derive_prompt360_invalid_reasons(
        current_prompt360,
        fallback_missing_reason="prompt360_executed_state_unavailable",
    )
    if (
        not blocked_reasons
        and not recovered_prompt360_used
        and not current_prompt360_source
    ):
        blocked_reasons = ["prompt360_executed_state_unavailable"]
    return _emit_blocked(
        prompt360_surface=current_prompt360,
        prompt360_source_path=current_prompt360_source,
        recovered_used=False,
        blocked_reasons=blocked_reasons,
        summary=(
            "Prompt361 is blocked because Prompt360 execution evidence is invalid or unavailable for post-execution diff capture."
        ),
    )

def _build_prompt362_review_route_decision(
    *,
    run_state_payload: Mapping[str, Any] | None,
    run_root: Path | None = None,
    current_prompt361_source_path: str = "",
) -> dict[str, Any]:
    run_state = dict(run_state_payload or {})
    artifact_root = run_root if run_root is not None else Path(".")
    prompt362_json_path = artifact_root / "prompt362_review_route_decision.json"

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    def _normalize_prompt361_surface(payload: Mapping[str, Any] | None) -> dict[str, Any]:
        source = dict(payload) if isinstance(payload, Mapping) else {}
        return {
            "prompt361_diff_capture_status": _normalize_text(
                source.get("prompt361_diff_capture_status"),
                default="",
            ),
            "prompt361_source_prompt": _normalize_text(
                source.get("prompt361_source_prompt"),
                default="prompt360",
            ),
            "prompt361_source_action": _normalize_text(
                source.get("prompt361_source_action"),
                default="capture_prompt360_execution_diff",
            ),
            "prompt361_prompt360_gate_status": _normalize_text(
                source.get("prompt361_prompt360_gate_status"),
                default="",
            ),
            "prompt361_prompt360_execution_status": _normalize_text(
                source.get("prompt361_prompt360_execution_status"),
                default="",
            ),
            "prompt361_prompt360_execution_receipt_path": _normalize_text(
                source.get("prompt361_prompt360_execution_receipt_path"),
                default="",
            ),
            "prompt361_prompt360_source_path": _normalize_text(
                source.get("prompt361_prompt360_source_path"),
                default="",
            ),
            "prompt361_recovered_prompt360_evidence_used": _prompt357_as_boolish(
                source.get("prompt361_recovered_prompt360_evidence_used")
            ),
            "prompt361_tracked_diff_present": _prompt357_as_boolish(
                source.get("prompt361_tracked_diff_present")
            ),
            "prompt361_changed_tracked_files": _normalize_string_list(
                source.get("prompt361_changed_tracked_files"),
                sort_items=False,
            ),
            "prompt361_untracked_files_ignored": _prompt357_as_boolish(
                source.get("prompt361_untracked_files_ignored")
            ),
            "prompt361_patch_path": _normalize_text(
                source.get("prompt361_patch_path"),
                default="",
            ),
            "prompt361_diff_report_path": _normalize_text(
                source.get("prompt361_diff_report_path"),
                default="",
            ),
            "prompt361_review_handoff_ready": _prompt357_as_boolish(
                source.get("prompt361_review_handoff_ready")
            ),
            "prompt361_authoritative_next_action": _normalize_text(
                source.get("prompt361_authoritative_next_action"),
                default="",
            ),
            "prompt361_next_action": _normalize_text(
                source.get("prompt361_next_action"),
                default="",
            ),
            "prompt361_manual_required": _prompt357_as_boolish(
                source.get("prompt361_manual_required")
            ),
            "prompt361_replan_required": _prompt357_as_boolish(
                source.get("prompt361_replan_required")
            ),
            "prompt361_active_blocked_reason": _normalize_text(
                source.get("prompt361_active_blocked_reason"),
                default="",
            ),
            "prompt361_active_blocked_reasons": _normalize_string_list(
                source.get("prompt361_active_blocked_reasons"),
                sort_items=False,
            ),
            "prompt361_summary": _normalize_text(
                source.get("prompt361_summary"),
                default="",
            ),
        }

    def _valid_prompt361_review_payload(payload: Mapping[str, Any] | None) -> bool:
        if not isinstance(payload, Mapping):
            return False
        active_blocked_reasons = payload.get("prompt361_active_blocked_reasons")
        next_action = _normalize_text(payload.get("prompt361_next_action"), default="")
        active_blocked_reason = _normalize_text(
            payload.get("prompt361_active_blocked_reason"),
            default="",
        )
        return all(
            (
                _normalize_text(
                    payload.get("prompt361_diff_capture_status"),
                    default="",
                )
                in {"captured", "captured_no_diff"},
                _prompt358_required_bool_match(
                    payload,
                    "prompt361_review_handoff_ready",
                    True,
                ),
                _prompt358_required_text_match(
                    payload,
                    "prompt361_prompt360_gate_status",
                    "executed",
                ),
                _prompt358_required_text_match(
                    payload,
                    "prompt361_prompt360_execution_status",
                    "completed",
                ),
                bool(
                    _normalize_text(
                        payload.get("prompt361_prompt360_execution_receipt_path"),
                        default="",
                    )
                ),
                bool(_normalize_text(payload.get("prompt361_patch_path"), default="")),
                bool(
                    _normalize_text(
                        payload.get("prompt361_diff_report_path"),
                        default="",
                    )
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt361_untracked_files_ignored",
                    True,
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt361_manual_required",
                    False,
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt361_replan_required",
                    False,
                ),
                active_blocked_reason == "",
                isinstance(active_blocked_reasons, list),
                _normalize_string_list(active_blocked_reasons, sort_items=False) == [],
                next_action in {
                    "prepare_post_execution_review",
                    "prepare_no_change_review",
                },
            )
        )

    def _resolve_prompt362_recovered_prompt361_evidence() -> tuple[dict[str, Any], str]:
        payload, source = _prompt358_find_latest_valid_prior_artifact(
            filename="prompt361_post_execution_diff_capture.json",
            validator=_valid_prompt361_review_payload,
        )
        return _normalize_prompt361_surface(payload), _normalize_text(source, default="")

    def _derive_prompt361_invalid_reasons(
        surface: Mapping[str, Any] | None,
        *,
        fallback_missing_reason: str,
    ) -> list[str]:
        normalized = dict(surface) if isinstance(surface, Mapping) else {}
        reasons: list[str] = []
        diff_capture_status = _normalize_text(
            normalized.get("prompt361_diff_capture_status"),
            default="",
        )
        if not diff_capture_status:
            _append_reason(reasons, fallback_missing_reason)
            return reasons
        if diff_capture_status not in {"captured", "captured_no_diff"}:
            _append_reason(
                reasons,
                f"prompt361_diff_capture_status_{diff_capture_status}",
            )
        if (
            _normalize_text(
                normalized.get("prompt361_prompt360_gate_status"),
                default="",
            )
            != "executed"
        ):
            _append_reason(reasons, "prompt361_prompt360_gate_status_not_executed")
        if (
            _normalize_text(
                normalized.get("prompt361_prompt360_execution_status"),
                default="",
            )
            != "completed"
        ):
            _append_reason(
                reasons,
                "prompt361_prompt360_execution_status_not_completed",
            )
        if not _normalize_text(
            normalized.get("prompt361_prompt360_execution_receipt_path"),
            default="",
        ):
            _append_reason(
                reasons,
                "prompt361_prompt360_execution_receipt_path_missing",
            )
        if not _normalize_text(normalized.get("prompt361_patch_path"), default=""):
            _append_reason(reasons, "prompt361_patch_path_missing")
        if not _normalize_text(
            normalized.get("prompt361_diff_report_path"),
            default="",
        ):
            _append_reason(reasons, "prompt361_diff_report_path_missing")
        if not bool(normalized.get("prompt361_untracked_files_ignored", False)):
            _append_reason(reasons, "prompt361_untracked_files_ignored_not_true")
        if not bool(normalized.get("prompt361_review_handoff_ready", False)):
            _append_reason(reasons, "prompt361_review_handoff_ready_not_true")
        next_action = _normalize_text(normalized.get("prompt361_next_action"), default="")
        if next_action not in {
            "prepare_post_execution_review",
            "prepare_no_change_review",
        }:
            _append_reason(
                reasons,
                f"prompt361_next_action_{next_action or 'missing'}",
            )
        if bool(normalized.get("prompt361_manual_required", False)):
            _append_reason(reasons, "prompt361_manual_required_true")
        if bool(normalized.get("prompt361_replan_required", False)):
            _append_reason(reasons, "prompt361_replan_required_true")
        active_blocked_reason = _normalize_text(
            normalized.get("prompt361_active_blocked_reason"),
            default="",
        )
        if active_blocked_reason:
            _append_reason(reasons, active_blocked_reason)
        active_blocked_reasons = _normalize_string_list(
            normalized.get("prompt361_active_blocked_reasons"),
            sort_items=False,
        )
        for active_reason in active_blocked_reasons:
            _append_reason(reasons, active_reason)
        if not reasons:
            _append_reason(reasons, fallback_missing_reason)
        return reasons

    def _path_has_readable_metadata(path_text: str) -> bool:
        normalized_path = _normalize_text(path_text, default="")
        if not normalized_path:
            return False
        try:
            candidate = Path(normalized_path)
            if not candidate.exists() or not candidate.is_file():
                return False
            candidate.stat()
        except OSError:
            return False
        return True

    def _read_diff_report(path_text: str) -> tuple[str, bool]:
        normalized_path = _normalize_text(path_text, default="")
        if not normalized_path:
            return "", False
        try:
            report_text = Path(normalized_path).read_text(encoding="utf-8")
        except OSError:
            return "", False
        return report_text, True

    def _build_prompt362_state(
        *,
        review_status: str,
        route_decision: str,
        prompt361_surface: Mapping[str, Any],
        prompt361_source_path: str,
        recovered_prompt361_evidence_used: bool,
        review_handoff_ready: bool,
        review_summary: str,
        review_findings: list[str],
        requires_targeted_fix: bool,
        approve_commit_tag_ready: bool,
        no_change_review_ready: bool,
        next_action: str,
        manual_required: bool,
        replan_required: bool,
        blocked_reasons: list[str],
        summary: str,
    ) -> dict[str, Any]:
        normalized_review_findings = _normalize_string_list(
            review_findings,
            sort_items=False,
        )
        normalized_blocked_reasons = _normalize_string_list(
            blocked_reasons,
            sort_items=False,
        )
        return {
            "prompt362_review_status": _normalize_text(review_status, default="blocked"),
            "prompt362_route_decision": _normalize_text(route_decision, default="blocked"),
            "prompt362_source_prompt": "prompt361",
            "prompt362_source_action": _normalize_text(
                prompt361_surface.get("prompt361_next_action"),
                default="",
            ),
            "prompt362_prompt361_diff_capture_status": _normalize_text(
                prompt361_surface.get("prompt361_diff_capture_status"),
                default="",
            ),
            "prompt362_prompt361_tracked_diff_present": bool(
                prompt361_surface.get("prompt361_tracked_diff_present", False)
            ),
            "prompt362_prompt361_changed_tracked_files": _normalize_string_list(
                prompt361_surface.get("prompt361_changed_tracked_files"),
                sort_items=False,
            ),
            "prompt362_prompt361_patch_path": _normalize_text(
                prompt361_surface.get("prompt361_patch_path"),
                default="",
            ),
            "prompt362_prompt361_diff_report_path": _normalize_text(
                prompt361_surface.get("prompt361_diff_report_path"),
                default="",
            ),
            "prompt362_prompt361_source_path": _normalize_text(
                prompt361_source_path,
                default="",
            ),
            "prompt362_recovered_prompt361_evidence_used": bool(
                recovered_prompt361_evidence_used
            ),
            "prompt362_review_handoff_ready": bool(review_handoff_ready),
            "prompt362_review_summary": _normalize_text(review_summary, default=""),
            "prompt362_review_findings": normalized_review_findings,
            "prompt362_requires_targeted_fix": bool(requires_targeted_fix),
            "prompt362_approve_commit_tag_ready": bool(approve_commit_tag_ready),
            "prompt362_no_change_review_ready": bool(no_change_review_ready),
            "prompt362_authoritative_next_action": _normalize_text(
                next_action,
                default="hold_for_followup",
            ),
            "prompt362_next_action": _normalize_text(
                next_action,
                default="hold_for_followup",
            ),
            "prompt362_manual_required": bool(manual_required),
            "prompt362_replan_required": bool(replan_required),
            "prompt362_active_blocked_reason": (
                normalized_blocked_reasons[0] if normalized_blocked_reasons else ""
            ),
            "prompt362_active_blocked_reasons": normalized_blocked_reasons,
            "prompt362_summary": _normalize_text(summary, default=""),
        }

    current_prompt361 = _normalize_prompt361_surface(run_state)
    current_prompt361_source = _normalize_text(current_prompt361_source_path, default="")
    current_prompt361_valid = _valid_prompt361_review_payload(run_state)
    prompt379_explicit_suppression_active = bool(
        run_state.get("prompt379_explicit_execution_active", False)
        or run_state.get("prompt361_suppressed_for_prompt379_explicit_execution", False)
        or run_state.get("pre_prompt379_prompt360_continuation_suppressed", False)
    )
    recovered_prompt361, recovered_prompt361_source = ({}, "")
    recovered_prompt361_used = False
    if not current_prompt361_valid and not prompt379_explicit_suppression_active:
        (
            recovered_prompt361,
            recovered_prompt361_source,
        ) = _resolve_prompt362_recovered_prompt361_evidence()
        recovered_prompt361_used = bool(recovered_prompt361_source)

    effective_prompt361 = (
        recovered_prompt361 if recovered_prompt361_used else current_prompt361
    )
    effective_prompt361_source = (
        recovered_prompt361_source if recovered_prompt361_used else current_prompt361_source
    )
    effective_prompt361_valid = bool(
        recovered_prompt361_used or current_prompt361_valid
    )

    if prompt379_explicit_suppression_active:
        state = _build_prompt362_state(
            review_status="suppressed_for_prompt379_explicit_execution",
            route_decision="not_applicable",
            prompt361_surface=current_prompt361,
            prompt361_source_path=current_prompt361_source,
            recovered_prompt361_evidence_used=False,
            review_handoff_ready=False,
            review_summary=(
                "Prompt362 did not recover stale Prompt361 evidence because "
                "Prompt379 explicit execution is active."
            ),
            review_findings=[],
            requires_targeted_fix=False,
            approve_commit_tag_ready=False,
            no_change_review_ready=False,
            next_action="continue_to_prompt379_explicit_execution",
            manual_required=False,
            replan_required=False,
            blocked_reasons=[],
            summary=(
                "Prompt362 stayed metadata-only so Prompt360 post-execution "
                "continuation cannot run ahead of Prompt379 explicit execution."
            ),
        )
        _write_json(prompt362_json_path, state)
        return state

    if not effective_prompt361_valid:
        blocked_reasons = _derive_prompt361_invalid_reasons(
            current_prompt361,
            fallback_missing_reason="prompt361_review_input_unavailable",
        )
        if not recovered_prompt361_used:
            _append_reason(
                blocked_reasons,
                "prompt362_valid_prompt361_recovery_artifact_not_found",
            )
        state = _build_prompt362_state(
            review_status="blocked",
            route_decision="blocked",
            prompt361_surface=current_prompt361,
            prompt361_source_path=current_prompt361_source,
            recovered_prompt361_evidence_used=False,
            review_handoff_ready=False,
            review_summary=(
                "Prompt362 could not locate valid Prompt361 post-execution review evidence."
            ),
            review_findings=blocked_reasons,
            requires_targeted_fix=False,
            approve_commit_tag_ready=False,
            no_change_review_ready=False,
            next_action="hold_for_followup",
            manual_required=True,
            replan_required=False,
            blocked_reasons=blocked_reasons,
            summary=(
                "Prompt362 is blocked because no valid Prompt361 diff capture evidence is available from the current run_state or recovery artifacts."
            ),
        )
        _write_json(prompt362_json_path, state)
        return state

    prompt361_diff_capture_status = _normalize_text(
        effective_prompt361.get("prompt361_diff_capture_status"),
        default="",
    )
    prompt361_tracked_diff_present = bool(
        effective_prompt361.get("prompt361_tracked_diff_present", False)
    )
    prompt361_changed_tracked_files = _normalize_string_list(
        effective_prompt361.get("prompt361_changed_tracked_files"),
        sort_items=False,
    )
    prompt361_patch_path = _normalize_text(
        effective_prompt361.get("prompt361_patch_path"),
        default="",
    )
    prompt361_diff_report_path = _normalize_text(
        effective_prompt361.get("prompt361_diff_report_path"),
        default="",
    )
    diff_report_text, diff_report_readable = _read_diff_report(prompt361_diff_report_path)

    review_findings: list[str] = []
    if not diff_report_readable:
        _append_reason(review_findings, "prompt362_prompt361_diff_report_unreadable")
    if prompt361_diff_capture_status == "captured" and not prompt361_tracked_diff_present:
        _append_reason(
            review_findings,
            "prompt362_prompt361_tracked_diff_expected_but_missing",
        )
    if prompt361_tracked_diff_present and not prompt361_changed_tracked_files:
        _append_reason(
            review_findings,
            "prompt362_prompt361_changed_tracked_files_missing",
        )
    if prompt361_tracked_diff_present and not _path_has_readable_metadata(prompt361_patch_path):
        _append_reason(review_findings, "prompt362_prompt361_patch_path_unreadable")
    if _normalize_text(
        effective_prompt361.get("prompt361_active_blocked_reason"),
        default="",
    ):
        _append_reason(review_findings, "prompt362_prompt361_active_blocker_present")
    if _normalize_string_list(
        effective_prompt361.get("prompt361_active_blocked_reasons"),
        sort_items=False,
    ):
        _append_reason(review_findings, "prompt362_prompt361_active_blockers_present")
    if bool(effective_prompt361.get("prompt361_manual_required", False)):
        _append_reason(review_findings, "prompt362_prompt361_manual_required_true")
    if bool(effective_prompt361.get("prompt361_replan_required", False)):
        _append_reason(review_findings, "prompt362_prompt361_replan_required_true")
    if not bool(effective_prompt361.get("prompt361_review_handoff_ready", False)):
        _append_reason(review_findings, "prompt362_prompt361_review_handoff_not_ready")

    report_line_count = len(
        [line for line in diff_report_text.splitlines() if line.strip()]
    ) if diff_report_readable else 0

    if review_findings:
        review_summary = (
            "Prompt362 completed bounded local review assimilation and found metadata-local blocker indicators in Prompt361 evidence."
        )
        summary = (
            "Prompt362 selected the targeted-fix route because Prompt361 review evidence contains metadata-local blocker indicators."
        )
        state = _build_prompt362_state(
            review_status="completed",
            route_decision="targeted_fix_required",
            prompt361_surface=effective_prompt361,
            prompt361_source_path=effective_prompt361_source,
            recovered_prompt361_evidence_used=recovered_prompt361_used,
            review_handoff_ready=True,
            review_summary=review_summary,
            review_findings=review_findings,
            requires_targeted_fix=True,
            approve_commit_tag_ready=False,
            no_change_review_ready=False,
            next_action="prepare_targeted_fix_prompt",
            manual_required=False,
            replan_required=False,
            blocked_reasons=[],
            summary=summary,
        )
        _write_json(prompt362_json_path, state)
        return state

    if prompt361_diff_capture_status == "captured_no_diff":
        review_summary = (
            "Prompt362 reviewed Prompt361 no-diff evidence and confirmed the no-change review route."
        )
        summary = (
            "Prompt362 selected the no-change review route from Prompt361 post-execution diff capture evidence."
        )
        state = _build_prompt362_state(
            review_status="completed",
            route_decision="no_change_review",
            prompt361_surface=effective_prompt361,
            prompt361_source_path=effective_prompt361_source,
            recovered_prompt361_evidence_used=recovered_prompt361_used,
            review_handoff_ready=True,
            review_summary=review_summary,
            review_findings=[],
            requires_targeted_fix=False,
            approve_commit_tag_ready=False,
            no_change_review_ready=True,
            next_action="prepare_no_change_review_route",
            manual_required=False,
            replan_required=False,
            blocked_reasons=[],
            summary=summary,
        )
        _write_json(prompt362_json_path, state)
        return state

    review_summary = (
        "Prompt362 reviewed Prompt361 tracked diff metadata and diff report and found no metadata-local blocker indicators."
    )
    if report_line_count > 0:
        review_summary = (
            "Prompt362 reviewed Prompt361 tracked diff metadata and "
            f"{report_line_count} non-empty diff report lines without detecting metadata-local blockers."
        )
    summary = (
        "Prompt362 selected the approve-commit-tag preparation route from Prompt361 post-execution diff capture evidence."
    )
    state = _build_prompt362_state(
        review_status="completed",
        route_decision="approve_commit_tag",
        prompt361_surface=effective_prompt361,
        prompt361_source_path=effective_prompt361_source,
        recovered_prompt361_evidence_used=recovered_prompt361_used,
        review_handoff_ready=True,
        review_summary=review_summary,
        review_findings=[],
        requires_targeted_fix=False,
        approve_commit_tag_ready=True,
        no_change_review_ready=False,
        next_action="prepare_approve_commit_tag",
        manual_required=False,
        replan_required=False,
        blocked_reasons=[],
        summary=summary,
    )
    _write_json(prompt362_json_path, state)
    return state

def _build_prompt363_approve_commit_tag_boundary(
    *,
    run_state_payload: Mapping[str, Any] | None,
    run_root: Path | None = None,
    execution_repo_path: str = "",
    current_prompt362_source_path: str = "",
) -> dict[str, Any]:
    run_state = dict(run_state_payload or {})
    artifact_root = run_root if run_root is not None else Path(".")
    prompt363_boundary_path = artifact_root / "prompt363_approve_commit_tag_boundary.json"
    prompt363_plan_path = artifact_root / "prompt363_approve_commit_tag_plan.json"
    prompt363_commands_path = artifact_root / "prompt363_approve_commit_tag_commands.sh"
    normalized_plan_path = _normalize_text(str(prompt363_plan_path), default="")
    normalized_commands_path = _normalize_text(str(prompt363_commands_path), default="")
    expected_tracked_files = [
        "automation/orchestration/planned_execution_runner.py",
        "automation/orchestration/run_state_summary_contract.py",
    ]
    commit_message = "Add Prompt361 and Prompt362 post execution review route"
    tag_name = "prompt362-post-execution-review-route"
    commands_lines = [
        "cd ~/codex-local-runner",
        "git status --short --untracked-files=no",
        "git diff --name-only",
        "git add automation/orchestration/planned_execution_runner.py automation/orchestration/run_state_summary_contract.py",
        'git commit -m "Add Prompt361 and Prompt362 post execution review route"',
        "git tag prompt362-post-execution-review-route",
        "git log --oneline --decorate -n 5",
        "git status --short --untracked-files=no",
    ]

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    def _normalize_prompt362_surface(payload: Mapping[str, Any] | None) -> dict[str, Any]:
        source = dict(payload) if isinstance(payload, Mapping) else {}
        return {
            "prompt362_review_status": _normalize_text(
                source.get("prompt362_review_status"),
                default="",
            ),
            "prompt362_route_decision": _normalize_text(
                source.get("prompt362_route_decision"),
                default="",
            ),
            "prompt362_review_handoff_ready": _prompt357_as_boolish(
                source.get("prompt362_review_handoff_ready")
            ),
            "prompt362_requires_targeted_fix": _prompt357_as_boolish(
                source.get("prompt362_requires_targeted_fix")
            ),
            "prompt362_approve_commit_tag_ready": _prompt357_as_boolish(
                source.get("prompt362_approve_commit_tag_ready")
            ),
            "prompt362_no_change_review_ready": _prompt357_as_boolish(
                source.get("prompt362_no_change_review_ready")
            ),
            "prompt362_authoritative_next_action": _normalize_text(
                source.get("prompt362_authoritative_next_action"),
                default="",
            ),
            "prompt362_next_action": _normalize_text(
                source.get("prompt362_next_action"),
                default="",
            ),
            "prompt362_manual_required": _prompt357_as_boolish(
                source.get("prompt362_manual_required")
            ),
            "prompt362_replan_required": _prompt357_as_boolish(
                source.get("prompt362_replan_required")
            ),
            "prompt362_active_blocked_reason": _normalize_text(
                source.get("prompt362_active_blocked_reason"),
                default="",
            ),
            "prompt362_active_blocked_reasons": _normalize_string_list(
                source.get("prompt362_active_blocked_reasons"),
                sort_items=False,
            ),
            "prompt362_prompt361_changed_tracked_files": _normalize_string_list(
                source.get("prompt362_prompt361_changed_tracked_files"),
                sort_items=False,
            ),
            "prompt362_prompt361_patch_path": _normalize_text(
                source.get("prompt362_prompt361_patch_path"),
                default="",
            ),
            "prompt362_prompt361_diff_report_path": _normalize_text(
                source.get("prompt362_prompt361_diff_report_path"),
                default="",
            ),
        }

    def _valid_prompt362_approve_commit_tag_payload(
        payload: Mapping[str, Any] | None,
    ) -> bool:
        if not isinstance(payload, Mapping):
            return False
        active_blocked_reasons = payload.get("prompt362_active_blocked_reasons")
        changed_tracked_files = _normalize_string_list(
            payload.get("prompt362_prompt361_changed_tracked_files"),
            sort_items=False,
        )
        return all(
            (
                _prompt358_required_text_match(
                    payload,
                    "prompt362_review_status",
                    "completed",
                ),
                _prompt358_required_text_match(
                    payload,
                    "prompt362_route_decision",
                    "approve_commit_tag",
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt362_review_handoff_ready",
                    True,
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt362_requires_targeted_fix",
                    False,
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt362_approve_commit_tag_ready",
                    True,
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt362_no_change_review_ready",
                    False,
                ),
                _prompt358_required_text_match(
                    payload,
                    "prompt362_authoritative_next_action",
                    "prepare_approve_commit_tag",
                ),
                _prompt358_required_text_match(
                    payload,
                    "prompt362_next_action",
                    "prepare_approve_commit_tag",
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt362_manual_required",
                    False,
                ),
                _prompt358_required_bool_match(
                    payload,
                    "prompt362_replan_required",
                    False,
                ),
                "prompt362_active_blocked_reason" in payload,
                _normalize_text(
                    payload.get("prompt362_active_blocked_reason"),
                    default="",
                )
                == "",
                isinstance(active_blocked_reasons, list),
                _normalize_string_list(active_blocked_reasons, sort_items=False) == [],
                bool(changed_tracked_files),
                bool(
                    _normalize_text(
                        payload.get("prompt362_prompt361_patch_path"),
                        default="",
                    )
                ),
                bool(
                    _normalize_text(
                        payload.get("prompt362_prompt361_diff_report_path"),
                        default="",
                    )
                ),
            )
        )

    def _resolve_prompt363_recovered_prompt362_evidence() -> tuple[dict[str, Any], str]:
        payload, source = _prompt358_find_latest_valid_prior_artifact(
            filename="prompt362_review_route_decision.json",
            validator=_valid_prompt362_approve_commit_tag_payload,
        )
        return _normalize_prompt362_surface(payload), _normalize_text(source, default="")

    def _derive_prompt362_invalid_reasons(
        surface: Mapping[str, Any] | None,
    ) -> list[str]:
        normalized = dict(surface) if isinstance(surface, Mapping) else {}
        reasons: list[str] = []
        review_status = _normalize_text(normalized.get("prompt362_review_status"), default="")
        if not review_status:
            _append_reason(reasons, "prompt362_review_status_missing")
        elif review_status != "completed":
            _append_reason(reasons, f"prompt362_review_status_{review_status}")

        route_decision = _normalize_text(normalized.get("prompt362_route_decision"), default="")
        if not route_decision:
            _append_reason(reasons, "prompt362_route_decision_missing")
        elif route_decision != "approve_commit_tag":
            _append_reason(reasons, f"prompt362_route_decision_{route_decision}")

        if "prompt362_review_handoff_ready" not in normalized:
            _append_reason(reasons, "prompt362_review_handoff_ready_missing")
        elif not bool(normalized.get("prompt362_review_handoff_ready", False)):
            _append_reason(reasons, "prompt362_review_handoff_ready_not_true")

        if bool(normalized.get("prompt362_requires_targeted_fix", False)):
            _append_reason(reasons, "prompt362_requires_targeted_fix_true")
        if not bool(normalized.get("prompt362_approve_commit_tag_ready", False)):
            _append_reason(reasons, "prompt362_approve_commit_tag_ready_not_true")
        if bool(normalized.get("prompt362_no_change_review_ready", False)):
            _append_reason(reasons, "prompt362_no_change_review_ready_true")

        authoritative_next_action = _normalize_text(
            normalized.get("prompt362_authoritative_next_action"),
            default="",
        )
        if not authoritative_next_action:
            _append_reason(reasons, "prompt362_authoritative_next_action_missing")
        elif authoritative_next_action != "prepare_approve_commit_tag":
            _append_reason(
                reasons,
                f"prompt362_authoritative_next_action_{authoritative_next_action}",
            )

        next_action = _normalize_text(normalized.get("prompt362_next_action"), default="")
        if not next_action:
            _append_reason(reasons, "prompt362_next_action_missing")
        elif next_action != "prepare_approve_commit_tag":
            _append_reason(reasons, f"prompt362_next_action_{next_action}")

        if bool(normalized.get("prompt362_manual_required", False)):
            _append_reason(reasons, "prompt362_manual_required_true")
        if bool(normalized.get("prompt362_replan_required", False)):
            _append_reason(reasons, "prompt362_replan_required_true")

        if "prompt362_active_blocked_reason" not in normalized:
            _append_reason(reasons, "prompt362_active_blocked_reason_missing")
        else:
            active_blocked_reason = _normalize_text(
                normalized.get("prompt362_active_blocked_reason"),
                default="",
            )
            if active_blocked_reason:
                _append_reason(reasons, active_blocked_reason)

        active_blocked_reasons_raw = normalized.get("prompt362_active_blocked_reasons")
        if not isinstance(active_blocked_reasons_raw, list):
            _append_reason(reasons, "prompt362_active_blocked_reasons_missing_or_invalid")
        else:
            active_blocked_reasons = _normalize_string_list(
                active_blocked_reasons_raw,
                sort_items=False,
            )
            for active_reason in active_blocked_reasons:
                _append_reason(reasons, active_reason)

        if not _normalize_string_list(
            normalized.get("prompt362_prompt361_changed_tracked_files"),
            sort_items=False,
        ):
            _append_reason(reasons, "prompt362_prompt361_changed_tracked_files_missing")
        if not _normalize_text(
            normalized.get("prompt362_prompt361_patch_path"),
            default="",
        ):
            _append_reason(reasons, "prompt362_prompt361_patch_path_missing")
        if not _normalize_text(
            normalized.get("prompt362_prompt361_diff_report_path"),
            default="",
        ):
            _append_reason(reasons, "prompt362_prompt361_diff_report_path_missing")
        if not reasons:
            _append_reason(reasons, "prompt362_approve_commit_tag_evidence_missing")
        return reasons

    def _build_prompt363_state(
        *,
        boundary_status: str,
        prompt362_surface: Mapping[str, Any],
        prompt362_source_path: str,
        recovered_prompt362_evidence_used: bool,
        approve_commit_tag_plan_ready: bool,
        actual_tracked_files: list[str],
        next_action: str,
        blocked_reasons: list[str],
        summary: str,
    ) -> dict[str, Any]:
        normalized_blocked_reasons = _normalize_string_list(
            blocked_reasons,
            sort_items=False,
        )
        return {
            "prompt363_boundary_status": _normalize_text(
                boundary_status,
                default="blocked",
            ),
            "prompt363_source_prompt": "prompt362",
            "prompt363_source_action": "prepare_approve_commit_tag",
            "prompt363_prompt362_review_status": _normalize_text(
                prompt362_surface.get("prompt362_review_status"),
                default="",
            ),
            "prompt363_prompt362_route_decision": _normalize_text(
                prompt362_surface.get("prompt362_route_decision"),
                default="",
            ),
            "prompt363_prompt362_source_path": _normalize_text(
                prompt362_source_path,
                default="",
            ),
            "prompt363_recovered_prompt362_evidence_used": bool(
                recovered_prompt362_evidence_used
            ),
            "prompt363_approve_commit_tag_plan_ready": bool(
                approve_commit_tag_plan_ready
            ),
            "prompt363_commit_tag_execution_allowed": False,
            "prompt363_commit_tag_execution_attempted": False,
            "prompt363_commit_tag_execution_status": "not_run",
            "prompt363_commit_message": commit_message,
            "prompt363_tag_name": tag_name,
            "prompt363_expected_tracked_files": list(expected_tracked_files),
            "prompt363_actual_tracked_files": list(actual_tracked_files),
            "prompt363_untracked_files_ignored": True,
            "prompt363_plan_path": normalized_plan_path,
            "prompt363_commands_path": normalized_commands_path,
            "prompt363_authoritative_next_action": _normalize_text(
                next_action,
                default="hold_for_followup",
            ),
            "prompt363_next_action": _normalize_text(
                next_action,
                default="hold_for_followup",
            ),
            "prompt363_manual_required": False,
            "prompt363_replan_required": False,
            "prompt363_active_blocked_reason": (
                normalized_blocked_reasons[0] if normalized_blocked_reasons else ""
            ),
            "prompt363_active_blocked_reasons": normalized_blocked_reasons,
            "prompt363_summary": _normalize_text(summary, default=""),
        }

    def _write_prompt363_artifacts(state: Mapping[str, Any]) -> None:
        commands_text = "\n".join(commands_lines) + "\n"
        prompt363_boundary_path.parent.mkdir(parents=True, exist_ok=True)
        prompt363_commands_path.write_text(commands_text, encoding="utf-8")
        _write_json(prompt363_boundary_path, state)
        _write_json(prompt363_plan_path, state)

    current_prompt362 = _normalize_prompt362_surface(run_state)
    current_prompt362_source = _normalize_text(current_prompt362_source_path, default="")
    current_prompt362_valid = _valid_prompt362_approve_commit_tag_payload(run_state)
    prompt379_explicit_suppression_active = bool(
        run_state.get("prompt379_explicit_execution_active", False)
        or run_state.get("prompt361_suppressed_for_prompt379_explicit_execution", False)
        or run_state.get("pre_prompt379_prompt360_continuation_suppressed", False)
    )
    recovered_prompt362, recovered_prompt362_source = ({}, "")
    recovered_prompt362_used = False
    if not current_prompt362_valid and not prompt379_explicit_suppression_active:
        (
            recovered_prompt362,
            recovered_prompt362_source,
        ) = _resolve_prompt363_recovered_prompt362_evidence()
        recovered_prompt362_used = bool(recovered_prompt362_source)

    effective_prompt362 = (
        recovered_prompt362 if recovered_prompt362_used else current_prompt362
    )
    effective_prompt362_source = (
        recovered_prompt362_source if recovered_prompt362_used else current_prompt362_source
    )
    effective_prompt362_valid = bool(
        recovered_prompt362_used or current_prompt362_valid
    )

    if prompt379_explicit_suppression_active:
        state = _build_prompt363_state(
            boundary_status="suppressed_for_prompt379_explicit_execution",
            prompt362_surface=current_prompt362,
            prompt362_source_path=current_prompt362_source,
            recovered_prompt362_evidence_used=False,
            approve_commit_tag_plan_ready=False,
            actual_tracked_files=[],
            next_action="continue_to_prompt379_explicit_execution",
            blocked_reasons=[],
            summary=(
                "Prompt363 did not recover stale Prompt362 approve-commit-tag "
                "evidence because Prompt379 explicit execution is active."
            ),
        )
        prompt363_boundary_path.parent.mkdir(parents=True, exist_ok=True)
        prompt363_commands_path.write_text("", encoding="utf-8")
        _write_json(prompt363_boundary_path, state)
        _write_json(prompt363_plan_path, state)
        return state

    normalized_repo_path = _normalize_text(
        execution_repo_path,
        default=str(Path.cwd()),
    )
    git_commands = {
        "status_short": ["git", "status", "--short", "--untracked-files=no"],
        "diff_name_only": ["git", "diff", "--name-only"],
        "diff_stat": ["git", "diff", "--stat"],
    }
    git_outputs: dict[str, str] = {}
    git_failed_reasons: list[str] = []
    actual_tracked_files: list[str] = []
    if not normalized_repo_path:
        _append_reason(git_failed_reasons, "prompt363_execution_repo_path_missing")
    else:
        for command_key, command in git_commands.items():
            completed = subprocess.run(
                command,
                text=True,
                capture_output=True,
                check=False,
                cwd=normalized_repo_path,
                shell=False,
            )
            git_outputs[command_key] = completed.stdout or ""
            if completed.returncode != 0:
                _append_reason(
                    git_failed_reasons,
                    f"prompt363_{command_key}_command_failed",
                )
        if not git_failed_reasons:
            changed_from_status = [
                path_text
                for path_text in (
                    _parse_git_status_path(raw_line.rstrip("\n"))
                    for raw_line in (git_outputs.get("status_short") or "").splitlines()
                )
                if path_text
            ]
            changed_from_diff = [
                line.strip()
                for line in (git_outputs.get("diff_name_only") or "").splitlines()
                if line.strip()
            ]
            actual_tracked_files = _normalize_string_list(
                sorted(set(changed_from_status + changed_from_diff)),
                sort_items=True,
            )

    if not effective_prompt362_valid:
        blocked_reasons = _derive_prompt362_invalid_reasons(current_prompt362)
        if not recovered_prompt362_used:
            _append_reason(
                blocked_reasons,
                "prompt363_valid_prompt362_recovery_artifact_not_found",
            )
        state = _build_prompt363_state(
            boundary_status="blocked",
            prompt362_surface=current_prompt362,
            prompt362_source_path=current_prompt362_source,
            recovered_prompt362_evidence_used=False,
            approve_commit_tag_plan_ready=False,
            actual_tracked_files=actual_tracked_files,
            next_action="hold_for_followup",
            blocked_reasons=blocked_reasons,
            summary=(
                "Prompt363 is blocked because no valid Prompt362 approve-commit-tag evidence is available from the current run_state or recovery artifacts."
            ),
        )
        _write_prompt363_artifacts(state)
        return state

    if git_failed_reasons:
        state = _build_prompt363_state(
            boundary_status="blocked",
            prompt362_surface=effective_prompt362,
            prompt362_source_path=effective_prompt362_source,
            recovered_prompt362_evidence_used=recovered_prompt362_used,
            approve_commit_tag_plan_ready=False,
            actual_tracked_files=actual_tracked_files,
            next_action="hold_for_followup",
            blocked_reasons=git_failed_reasons,
            summary=(
                "Prompt363 is blocked because bounded local git diff validation could not be completed."
            ),
        )
        _write_prompt363_artifacts(state)
        return state

    if not actual_tracked_files:
        state = _build_prompt363_state(
            boundary_status="blocked",
            prompt362_surface=effective_prompt362,
            prompt362_source_path=effective_prompt362_source,
            recovered_prompt362_evidence_used=recovered_prompt362_used,
            approve_commit_tag_plan_ready=False,
            actual_tracked_files=actual_tracked_files,
            next_action="hold_for_followup",
            blocked_reasons=["tracked_diff_missing"],
            summary=(
                "Prompt363 is blocked because the current tracked git diff is empty."
            ),
        )
        _write_prompt363_artifacts(state)
        return state

    if actual_tracked_files != expected_tracked_files:
        state = _build_prompt363_state(
            boundary_status="blocked",
            prompt362_surface=effective_prompt362,
            prompt362_source_path=effective_prompt362_source,
            recovered_prompt362_evidence_used=recovered_prompt362_used,
            approve_commit_tag_plan_ready=False,
            actual_tracked_files=actual_tracked_files,
            next_action="hold_for_followup",
            blocked_reasons=["unexpected_tracked_files_present"],
            summary=(
                "Prompt363 is blocked because the current tracked git diff does not match the expected two-file approve commit/tag boundary."
            ),
        )
        _write_prompt363_artifacts(state)
        return state

    state = _build_prompt363_state(
        boundary_status="ready",
        prompt362_surface=effective_prompt362,
        prompt362_source_path=effective_prompt362_source,
        recovered_prompt362_evidence_used=recovered_prompt362_used,
        approve_commit_tag_plan_ready=True,
        actual_tracked_files=actual_tracked_files,
        next_action="run_manual_commit_tag_commands",
        blocked_reasons=[],
        summary=(
            "Prompt363 validated Prompt362 approve-commit-tag evidence, confirmed the exact tracked two-file diff, and wrote deterministic manual commit/tag plan artifacts without executing git mutation."
        ),
    )
    _write_prompt363_artifacts(state)
    return state

def _build_prompt364_post_commit_tag_verification(
    *,
    run_root: Path | None = None,
    execution_repo_path: str = "",
) -> dict[str, Any]:
    artifact_root = run_root if run_root is not None else Path(".")
    prompt364_verification_path = artifact_root / "prompt364_post_commit_tag_verification.json"
    prompt364_handoff_path = artifact_root / "prompt364_next_cycle_handoff.json"
    previous_expected_tag_name = _PROMPT364_PREVIOUS_EXPECTED_TAG_NAME
    expected_head_tag_name = _PROMPT364_EXPECTED_HEAD_TAG_NAME
    expected_tag_name = _PROMPT364_EXPECTED_TAG_NAME
    allowed_implementation_files = list(_PROMPT364_ALLOWED_IMPLEMENTATION_FILES)

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    def _build_state(
        *,
        verification_status: str,
        commit_tag_verified: bool,
        worktree_clean: bool,
        head_short_sha: str,
        head_tags: list[str],
        head_tag_verified: bool,
        previous_tag_verified: bool,
        current_head_tag_verified: bool,
        changed_tracked_files: list[str],
        staged_tracked_files: list[str],
        next_cycle_handoff_ready: bool,
        next_action: str,
        manual_required: bool,
        replan_required: bool,
        blocked_reasons: list[str],
        summary: str,
    ) -> dict[str, Any]:
        normalized_blocked_reasons = _normalize_string_list(
            blocked_reasons,
            sort_items=False,
        )
        return {
            "prompt364_verification_status": _normalize_text(
                verification_status,
                default="blocked",
            ),
            "prompt364_commit_tag_verified": bool(commit_tag_verified),
            "prompt364_worktree_clean": bool(worktree_clean),
            "prompt364_head_short_sha": _normalize_text(head_short_sha, default=""),
            "prompt364_head_tags": _normalize_string_list(head_tags, sort_items=True),
            "prompt364_head_tag_verified": bool(head_tag_verified),
            "prompt364_previous_tag_verified": bool(previous_tag_verified),
            "prompt364_current_head_tag_verified": bool(
                current_head_tag_verified
            ),
            "prompt364_previous_expected_tag_name": previous_expected_tag_name,
            "prompt364_expected_head_tag_name": expected_head_tag_name,
            "prompt364_expected_tag_name": expected_tag_name,
            "prompt364_changed_tracked_files": _normalize_string_list(
                changed_tracked_files,
                sort_items=True,
            ),
            "prompt364_staged_tracked_files": _normalize_string_list(
                staged_tracked_files,
                sort_items=True,
            ),
            "prompt364_allowed_implementation_files": list(
                allowed_implementation_files
            ),
            "prompt364_untracked_files_ignored": True,
            "prompt364_next_cycle_handoff_ready": bool(next_cycle_handoff_ready),
            "prompt364_authoritative_next_action": _normalize_text(
                next_action,
                default="hold_for_followup",
            ),
            "prompt364_next_action": _normalize_text(
                next_action,
                default="hold_for_followup",
            ),
            "prompt364_manual_required": bool(manual_required),
            "prompt364_replan_required": bool(replan_required),
            "prompt364_active_blocked_reason": (
                normalized_blocked_reasons[0] if normalized_blocked_reasons else ""
            ),
            "prompt364_active_blocked_reasons": normalized_blocked_reasons,
            "prompt364_summary": _normalize_text(summary, default=""),
        }

    def _write_prompt364_artifacts(state: Mapping[str, Any]) -> None:
        prompt364_verification_path.parent.mkdir(parents=True, exist_ok=True)
        _write_json(prompt364_verification_path, state)
        _write_json(prompt364_handoff_path, state)

    normalized_repo_path = _normalize_text(
        execution_repo_path,
        default=str(Path.cwd()),
    )
    git_commands = {
        "status_short": ["git", "status", "--short", "--untracked-files=no"],
        "diff_name_only": ["git", "diff", "--name-only"],
        "diff_cached_name_only": ["git", "diff", "--cached", "--name-only"],
        "head_short_sha": ["git", "rev-parse", "--short", "HEAD"],
        "recent_log": ["git", "log", "--oneline", "--decorate", "-n", "5"],
        "head_tags": ["git", "tag", "--points-at", "HEAD"],
        "previous_tag_list": ["git", "tag", "--list", previous_expected_tag_name],
        "expected_head_tag_list": ["git", "tag", "--list", expected_head_tag_name],
    }
    git_outputs: dict[str, str] = {}
    git_failed_reasons: list[str] = []
    if not normalized_repo_path:
        _append_reason(git_failed_reasons, "prompt364_execution_repo_path_missing")
    else:
        for command_key, command in git_commands.items():
            completed = subprocess.run(
                command,
                text=True,
                capture_output=True,
                check=False,
                cwd=normalized_repo_path,
                shell=False,
            )
            git_outputs[command_key] = completed.stdout or ""
            if completed.returncode != 0:
                _append_reason(
                    git_failed_reasons,
                    f"prompt364_{command_key}_command_failed",
                )

    changed_tracked_files: list[str] = []
    staged_tracked_files: list[str] = []
    head_tags: list[str] = []
    previous_tag_list: list[str] = []
    expected_head_tag_list: list[str] = []
    head_short_sha = ""
    if not git_failed_reasons:
        status_paths = [
            path_text
            for path_text in (
                _parse_git_status_path(raw_line.rstrip("\n"))
                for raw_line in (git_outputs.get("status_short") or "").splitlines()
            )
            if path_text
        ]
        unstaged_paths = [
            line.strip()
            for line in (git_outputs.get("diff_name_only") or "").splitlines()
            if line.strip()
        ]
        staged_tracked_files = _normalize_string_list(
            [
                line.strip()
                for line in (git_outputs.get("diff_cached_name_only") or "").splitlines()
                if line.strip()
            ],
            sort_items=True,
        )
        changed_tracked_files = _normalize_string_list(
            sorted(set(status_paths + unstaged_paths + staged_tracked_files)),
            sort_items=True,
        )
        head_short_sha = _normalize_text(git_outputs.get("head_short_sha"), default="")
        head_tags = _normalize_string_list(
            (git_outputs.get("head_tags") or "").splitlines(),
            sort_items=True,
        )
        previous_tag_list = _normalize_string_list(
            (git_outputs.get("previous_tag_list") or "").splitlines(),
            sort_items=True,
        )
        expected_head_tag_list = _normalize_string_list(
            (git_outputs.get("expected_head_tag_list") or "").splitlines(),
            sort_items=True,
        )

    previous_tag_verified = previous_expected_tag_name in previous_tag_list
    expected_head_tag_exists = expected_head_tag_name in expected_head_tag_list
    legacy_head_tag_verified = _PROMPT364_LEGACY_HEAD_TAG_NAME in head_tags
    implementation_in_progress_head_tag_verified = (
        _PROMPT364_IMPLEMENTATION_IN_PROGRESS_HEAD_TAG_NAME in head_tags
    )
    current_head_tag_verified = expected_head_tag_name in head_tags
    head_tag_verified = (
        legacy_head_tag_verified
        or implementation_in_progress_head_tag_verified
        or current_head_tag_verified
    )
    worktree_clean = bool((not changed_tracked_files) and (not staged_tracked_files))
    tracked_changes_present = bool(changed_tracked_files or staged_tracked_files)
    changed_files_within_allowed_set = tracked_changes_present and all(
        path in allowed_implementation_files
        for path in (changed_tracked_files + staged_tracked_files)
    )
    unexpected_tracked_changes_present = tracked_changes_present and any(
        path not in allowed_implementation_files
        for path in (changed_tracked_files + staged_tracked_files)
    )

    if git_failed_reasons:
        state = _build_state(
            verification_status="blocked",
            commit_tag_verified=False,
            worktree_clean=False,
            head_short_sha=head_short_sha,
            head_tags=head_tags,
            head_tag_verified=False,
            previous_tag_verified=False,
            current_head_tag_verified=False,
            changed_tracked_files=changed_tracked_files,
            staged_tracked_files=staged_tracked_files,
            next_cycle_handoff_ready=False,
            next_action="resolve_invalid_repo_state",
            manual_required=True,
            replan_required=False,
            blocked_reasons=git_failed_reasons,
            summary=(
                "Prompt364 is blocked because bounded read-only git verification could not complete successfully."
            ),
        )
        _write_prompt364_artifacts(state)
        return state

    if not previous_tag_verified:
        state = _build_state(
            verification_status="blocked",
            commit_tag_verified=False,
            worktree_clean=worktree_clean,
            head_short_sha=head_short_sha,
            head_tags=head_tags,
            head_tag_verified=head_tag_verified,
            previous_tag_verified=False,
            current_head_tag_verified=current_head_tag_verified,
            changed_tracked_files=changed_tracked_files,
            staged_tracked_files=staged_tracked_files,
            next_cycle_handoff_ready=False,
            next_action="restore_or_tag_prompt363_boundary",
            manual_required=True,
            replan_required=False,
            blocked_reasons=["prompt363_boundary_tag_missing"],
            summary=(
                "Prompt364 is blocked because the Prompt363 approve-commit-tag boundary tag does not exist in the local repository."
            ),
        )
        _write_prompt364_artifacts(state)
        return state

    if unexpected_tracked_changes_present:
        state = _build_state(
            verification_status="blocked",
            commit_tag_verified=True,
            worktree_clean=False,
            head_short_sha=head_short_sha,
            head_tags=head_tags,
            head_tag_verified=head_tag_verified,
            previous_tag_verified=True,
            current_head_tag_verified=current_head_tag_verified,
            changed_tracked_files=changed_tracked_files,
            staged_tracked_files=staged_tracked_files,
            next_cycle_handoff_ready=False,
            next_action="resolve_unexpected_tracked_changes",
            manual_required=True,
            replan_required=False,
            blocked_reasons=["unexpected_tracked_changes_present"],
            summary=(
                "Prompt364 is blocked because tracked changes outside the allowed Prompt364 implementation files are present."
            ),
        )
        _write_prompt364_artifacts(state)
        return state

    if worktree_clean and expected_head_tag_exists and current_head_tag_verified:
        state = _build_state(
            verification_status="verified",
            commit_tag_verified=True,
            worktree_clean=True,
            head_short_sha=head_short_sha,
            head_tags=head_tags,
            head_tag_verified=True,
            previous_tag_verified=True,
            current_head_tag_verified=True,
            changed_tracked_files=changed_tracked_files,
            staged_tracked_files=staged_tracked_files,
            next_cycle_handoff_ready=True,
            next_action="prepare_next_local_cycle",
            manual_required=False,
            replan_required=False,
            blocked_reasons=[],
            summary=(
                "Prompt364 verified that the Prompt363 boundary tag exists in repository history, the Prompt365 dry-run source mutation guard tag is attached to HEAD, and the tracked worktree is clean."
            ),
        )
        _write_prompt364_artifacts(state)
        return state

    if worktree_clean and not current_head_tag_verified:
        state = _build_state(
            verification_status="blocked",
            commit_tag_verified=False,
            worktree_clean=True,
            head_short_sha=head_short_sha,
            head_tags=head_tags,
            head_tag_verified=head_tag_verified,
            previous_tag_verified=True,
            current_head_tag_verified=False,
            changed_tracked_files=changed_tracked_files,
            staged_tracked_files=staged_tracked_files,
            next_cycle_handoff_ready=False,
            next_action="tag_prompt365_commit",
            manual_required=True,
            replan_required=False,
            blocked_reasons=["prompt364_head_tag_missing"],
            summary=(
                "Prompt364 is blocked because the tracked worktree is clean but HEAD does not carry the prompt365-dry-run-source-mutation-guard tag."
            ),
        )
        _write_prompt364_artifacts(state)
        return state

    if changed_files_within_allowed_set and head_tag_verified:
        state = _build_state(
            verification_status="implementation_in_progress",
            commit_tag_verified=True,
            worktree_clean=False,
            head_short_sha=head_short_sha,
            head_tags=head_tags,
            head_tag_verified=True,
            previous_tag_verified=True,
            current_head_tag_verified=current_head_tag_verified,
            changed_tracked_files=changed_tracked_files,
            staged_tracked_files=staged_tracked_files,
            next_cycle_handoff_ready=False,
            next_action="commit_prompt365_then_clean_rerun",
            manual_required=False,
            replan_required=False,
            blocked_reasons=["prompt365_implementation_changes_present"],
            summary=(
                "Prompt364 confirmed the Prompt363 boundary tag exists in repository history, accepted the current implementation-in-progress HEAD tag context, and detected only in-scope Prompt365 implementation changes."
            ),
        )
        _write_prompt364_artifacts(state)
        return state

    state = _build_state(
        verification_status="blocked",
        commit_tag_verified=False,
        worktree_clean=False,
        head_short_sha=head_short_sha,
        head_tags=head_tags,
        head_tag_verified=head_tag_verified,
        previous_tag_verified=True,
        current_head_tag_verified=current_head_tag_verified,
        changed_tracked_files=changed_tracked_files,
        staged_tracked_files=staged_tracked_files,
        next_cycle_handoff_ready=False,
        next_action="resolve_invalid_repo_state",
        manual_required=True,
        replan_required=False,
        blocked_reasons=["prompt364_expected_head_context_missing"],
        summary=(
            "Prompt364 is blocked because the local tracked changes are in-scope but HEAD is not aligned to an allowed Prompt364 implementation tag context or the prompt365-dry-run-source-mutation-guard tag."
        ),
    )
    _write_prompt364_artifacts(state)
    return state

def _build_prompt366_local_autonomous_continuation_contract(
    *,
    run_state_payload: Mapping[str, Any] | None,
    run_root: Path | None = None,
    execution_repo_path: str = "",
    current_prompt364_source_path: str = "",
    current_prompt365_source_path: str = "",
) -> tuple[dict[str, Any], dict[str, Any]]:
    artifact_root = run_root if run_root is not None else Path(".")
    prompt366_contract_path = (
        artifact_root / "prompt366_local_autonomous_continuation_contract.json"
    )
    prompt366_restart_contract_path = (
        artifact_root / "prompt366_next_cycle_restart_contract.json"
    )
    run_state = dict(run_state_payload or {})
    expected_head_tag_name = _PROMPT366_EXPECTED_HEAD_TAG_NAME
    allowed_head_tag_names = _PROMPT366_ALLOWED_HEAD_TAG_NAMES
    previous_source_tag_name = _PROMPT366_PREVIOUS_SOURCE_TAG_NAME
    normalized_repo_path = _normalize_text(
        execution_repo_path,
        default=str(Path.cwd()),
    )

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    def _normalize_prompt364_surface(payload: Mapping[str, Any] | None) -> dict[str, Any]:
        source = dict(payload) if isinstance(payload, Mapping) else {}
        return {
            "prompt364_verification_status": _normalize_text(
                source.get("prompt364_verification_status"),
                default="",
            ),
            "prompt364_next_cycle_handoff_ready": _prompt357_as_boolish(
                source.get("prompt364_next_cycle_handoff_ready")
            ),
            "prompt364_next_action": _normalize_text(
                source.get("prompt364_next_action"),
                default="",
            ),
            "prompt364_authoritative_next_action": _normalize_text(
                source.get("prompt364_authoritative_next_action"),
                default="",
            ),
            "prompt364_head_tag_verified": _prompt357_as_boolish(
                source.get("prompt364_head_tag_verified")
            ),
            "prompt364_head_tags": _normalize_string_list(
                source.get("prompt364_head_tags"),
                sort_items=True,
            ),
            "prompt364_changed_tracked_files": _normalize_string_list(
                source.get("prompt364_changed_tracked_files"),
                sort_items=True,
            ),
            "prompt364_staged_tracked_files": _normalize_string_list(
                source.get("prompt364_staged_tracked_files"),
                sort_items=True,
            ),
            "prompt364_active_blocked_reason": _normalize_text(
                source.get("prompt364_active_blocked_reason"),
                default="",
            ),
            "prompt364_active_blocked_reasons": _normalize_string_list(
                source.get("prompt364_active_blocked_reasons"),
                sort_items=False,
            ),
        }

    def _valid_prompt364_verified_handoff(payload: Mapping[str, Any] | None) -> bool:
        if not isinstance(payload, Mapping):
            return False
        normalized = _normalize_prompt364_surface(payload)
        return all(
            (
                normalized.get("prompt364_verification_status") == "verified",
                bool(normalized.get("prompt364_next_cycle_handoff_ready", False)),
                normalized.get("prompt364_next_action") == "prepare_next_local_cycle",
            )
        )

    def _normalize_prompt365_surface(payload: Mapping[str, Any] | None) -> dict[str, Any]:
        source = dict(payload) if isinstance(payload, Mapping) else {}
        return {
            "prompt365_runtime_source_mutation_guard_status": _normalize_text(
                source.get("prompt365_runtime_source_mutation_guard_status"),
                default="",
            ),
            "prompt365_dry_run_source_mutation_detected": _prompt357_as_boolish(
                source.get("prompt365_dry_run_source_mutation_detected")
            ),
            "prompt365_mutation_capable_path_blocked": _prompt357_as_boolish(
                source.get("prompt365_mutation_capable_path_blocked")
            ),
            "prompt365_new_changed_tracked_files": _normalize_string_list(
                source.get("prompt365_new_changed_tracked_files"),
                sort_items=True,
            ),
            "prompt365_next_action": _normalize_text(
                source.get("prompt365_next_action"),
                default="",
            ),
            "prompt365_blocked_reason": _normalize_text(
                source.get("prompt365_blocked_reason"),
                default="",
            ),
        }

    def _valid_prompt365_clean_guard(payload: Mapping[str, Any] | None) -> bool:
        if not isinstance(payload, Mapping):
            return False
        normalized = _normalize_prompt365_surface(payload)
        return all(
            (
                normalized.get("prompt365_runtime_source_mutation_guard_status") == "clean",
                not bool(normalized.get("prompt365_dry_run_source_mutation_detected", False)),
                not bool(normalized.get("prompt365_mutation_capable_path_blocked", False)),
                normalized.get("prompt365_new_changed_tracked_files") == [],
            )
        )

    def _commands_disable_remote_operations(commands_path_text: Any) -> bool:
        normalized_path = _normalize_text(commands_path_text, default="")
        if not normalized_path:
            return False
        commands_path = Path(normalized_path)
        if not commands_path.exists() or not commands_path.is_file():
            return False
        try:
            commands_text = commands_path.read_text(encoding="utf-8")
        except OSError:
            return False
        commands_lower = commands_text.lower()
        forbidden_fragments = (
            "git push",
            "gh pr",
            "git merge",
            "rollback",
        )
        return not any(fragment in commands_lower for fragment in forbidden_fragments)

    def _valid_prompt367_approve_commit_tag_plan(
        payload: Mapping[str, Any] | None,
    ) -> bool:
        if not isinstance(payload, Mapping):
            return False
        route_decision = _normalize_text(
            payload.get("prompt363_prompt362_route_decision"),
            default="",
        )
        source_action = _normalize_text(
            payload.get("prompt363_source_action"),
            default="",
        )
        expected_tracked_files = _normalize_string_list(
            payload.get("prompt363_expected_tracked_files"),
            sort_items=True,
        )
        commit_message = _normalize_text(
            payload.get("prompt363_commit_message"),
            default="",
        )
        tag_name = _normalize_text(payload.get("prompt363_tag_name"), default="")
        return all(
            (
                _normalize_text(payload.get("prompt363_boundary_status"), default="")
                == "ready",
                bool(payload.get("prompt363_approve_commit_tag_plan_ready", False)),
                route_decision in {"approve_commit_tag", "prepare_approve_commit_tag"}
                or source_action == "prepare_approve_commit_tag",
                bool(expected_tracked_files),
                bool(commit_message),
                bool(tag_name),
                not bool(payload.get("prompt363_commit_tag_execution_allowed", False)),
                _commands_disable_remote_operations(
                    payload.get("prompt363_commands_path")
                ),
            )
        )

    current_prompt364 = _normalize_prompt364_surface(run_state)
    current_prompt365 = _normalize_prompt365_surface(run_state)
    current_prompt364_valid = _valid_prompt364_verified_handoff(run_state)
    current_prompt365_valid = _valid_prompt365_clean_guard(run_state)

    recovered_prompt364_payload, recovered_prompt364_source_path = ({}, "")
    if not current_prompt364_valid:
        (
            recovered_prompt364_payload,
            recovered_prompt364_source_path,
        ) = _prompt358_find_latest_valid_prior_artifact(
            filename="prompt364_next_cycle_handoff.json",
            validator=_valid_prompt364_verified_handoff,
        )
    recovered_prompt365_payload, recovered_prompt365_source_path = ({}, "")
    if not current_prompt365_valid:
        (
            recovered_prompt365_payload,
            recovered_prompt365_source_path,
        ) = _prompt358_find_latest_valid_prior_artifact(
            filename="run_state.json",
            validator=_valid_prompt365_clean_guard,
        )

    effective_prompt364 = (
        _normalize_prompt364_surface(recovered_prompt364_payload)
        if recovered_prompt364_source_path
        else current_prompt364
    )
    effective_prompt365 = (
        _normalize_prompt365_surface(recovered_prompt365_payload)
        if recovered_prompt365_source_path
        else current_prompt365
    )
    prompt366_recovered_prompt364_evidence_used = bool(recovered_prompt364_source_path)
    prompt366_recovered_prompt365_evidence_used = bool(recovered_prompt365_source_path)
    prompt366_prompt364_source_path = _normalize_text(
        recovered_prompt364_source_path
        if prompt366_recovered_prompt364_evidence_used
        else current_prompt364_source_path,
        default="",
    )
    prompt366_prompt365_source_path = _normalize_text(
        recovered_prompt365_source_path
        if prompt366_recovered_prompt365_evidence_used
        else current_prompt365_source_path,
        default="",
    )
    prompt366_prompt364_verified = _valid_prompt364_verified_handoff(
        effective_prompt364
    )
    prompt366_prompt365_guard_clean = _valid_prompt365_clean_guard(
        effective_prompt365
    )

    recovered_prompt367_plan_payload, recovered_prompt367_plan_source_path = (
        _prompt358_find_latest_valid_prior_artifact(
            filename="prompt363_approve_commit_tag_plan.json",
            validator=_valid_prompt367_approve_commit_tag_plan,
        )
    )
    prompt367_plan_payload = (
        dict(recovered_prompt367_plan_payload)
        if isinstance(recovered_prompt367_plan_payload, Mapping)
        else {}
    )
    prompt367_plan_source_path = _normalize_text(
        recovered_prompt367_plan_source_path,
        default="",
    )

    git_state_available = True
    staged_tracked_files: list[str] = []
    unstaged_tracked_files: list[str] = []
    changed_tracked_files: list[str] = []
    head_tags: list[str] = []
    previous_source_tag_list: list[str] = []
    if not normalized_repo_path:
        git_state_available = False
    else:
        try:
            status_short_cmd = _run_git(
                normalized_repo_path,
                ["status", "--short", "--untracked-files=no"],
                timeout_seconds=10,
            )
            diff_name_only_cmd = _run_git(
                normalized_repo_path,
                ["diff", "--name-only"],
                timeout_seconds=10,
            )
            diff_cached_name_only_cmd = _run_git(
                normalized_repo_path,
                ["diff", "--cached", "--name-only"],
                timeout_seconds=10,
            )
            head_tags_cmd = _run_git(
                normalized_repo_path,
                ["tag", "--points-at", "HEAD"],
                timeout_seconds=10,
            )
            previous_source_tag_list_cmd = _run_git(
                normalized_repo_path,
                ["tag", "--list", previous_source_tag_name],
                timeout_seconds=10,
            )
        except (OSError, subprocess.TimeoutExpired):
            git_state_available = False
        else:
            if any(
                command.returncode != 0
                for command in (
                    status_short_cmd,
                    diff_name_only_cmd,
                    diff_cached_name_only_cmd,
                    head_tags_cmd,
                    previous_source_tag_list_cmd,
                )
            ):
                git_state_available = False
            else:
                status_paths = [
                    path_text
                    for path_text in (
                        _parse_git_status_path(raw_line.rstrip("\n"))
                        for raw_line in (status_short_cmd.stdout or "").splitlines()
                    )
                    if path_text
                ]
                unstaged_tracked_files = _normalize_string_list(
                    [
                        line.strip()
                        for line in (diff_name_only_cmd.stdout or "").splitlines()
                        if line.strip()
                    ],
                    sort_items=True,
                )
                staged_tracked_files = _normalize_string_list(
                    [
                        line.strip()
                        for line in (diff_cached_name_only_cmd.stdout or "").splitlines()
                        if line.strip()
                    ],
                    sort_items=True,
                )
                changed_tracked_files = _normalize_string_list(
                    sorted(
                        set(status_paths)
                        | set(unstaged_tracked_files)
                        | set(staged_tracked_files)
                    ),
                    sort_items=True,
                )
                head_tags = _normalize_string_list(
                    (head_tags_cmd.stdout or "").splitlines(),
                    sort_items=True,
                )
                previous_source_tag_list = _normalize_string_list(
                    (previous_source_tag_list_cmd.stdout or "").splitlines(),
                    sort_items=True,
                )

    prompt366_worktree_clean = bool(
        git_state_available
        and not changed_tracked_files
        and not staged_tracked_files
        and not unstaged_tracked_files
    )
    prompt366_previous_source_tag_verified = bool(
        git_state_available and previous_source_tag_name in previous_source_tag_list
    )
    prompt366_head_tag_verified = bool(
        git_state_available
        and any(tag_name in head_tags for tag_name in allowed_head_tag_names)
    )

    prompt367_required_execution_flags = [
        "project_browser_autonomous_approve_commit_tag_execution_enabled",
        "project_browser_autonomous_approve_commit_tag_execution_confirmed",
    ]
    prompt367_input = {
        "prompt_id": "prompt367",
        "objective": "bounded_local_commit_tag_execution_adapter",
        "approve_commit_tag_source_prompt": "prompt363",
        "approve_commit_tag_route_decision": _normalize_text(
            prompt367_plan_payload.get("prompt363_prompt362_route_decision"),
            default="approve_commit_tag",
        ),
        "approve_commit_tag_plan_source_path": prompt367_plan_source_path,
        "approve_commit_tag_commands_source_path": _normalize_text(
            prompt367_plan_payload.get("prompt363_commands_path"),
            default="",
        ),
        "expected_commit_message": _normalize_text(
            prompt367_plan_payload.get("prompt363_commit_message"),
            default="",
        ),
        "expected_tag_name": _normalize_text(
            prompt367_plan_payload.get("prompt363_tag_name"),
            default="",
        ),
        "expected_tracked_files": _normalize_string_list(
            prompt367_plan_payload.get("prompt363_expected_tracked_files"),
            sort_items=True,
        ),
        "execution_flags_required": True,
        "required_execution_flags": prompt367_required_execution_flags,
        "commit_tag_receipt_path": _APPROVE_COMMIT_TAG_EXECUTION_RECEIPT_PATH,
        "commit_tag_execution_allowed_by_default": False,
        "push_pr_merge_enabled": False,
        "pr_merge_enabled": False,
        "rollback_enabled": False,
        "remote_operations_enabled": False,
        "next_action_on_success": "run_prompt367_clean_rerun_verification",
        "next_action_on_blocked": "review_prompt367_commit_tag_blocker",
    }
    prompt367_input_ready = _valid_prompt367_approve_commit_tag_plan(prompt367_plan_payload)

    prompt368_input = {
        "prompt_id": "prompt368",
        "objective": "integrated_next_action_loop_resume_controller",
        "next_action_source_prompt": "prompt364",
        "next_action_source_action": "prepare_next_local_cycle",
        "resume_action": "prepare_next_local_cycle",
        "max_local_cycles": _LOCAL_AUTONOMOUS_CYCLE_V2_MAX_CYCLES,
        "current_local_cycle": _LOCAL_AUTONOMOUS_CYCLE_V2_CURRENT_CYCLE,
        "stop_on_failure": True,
        "stop_conditions": [
            "blocked_route_detected",
            "execution_failure_detected",
            "manual_review_required",
            "max_local_cycles_reached",
        ],
        "allowed_routes": [
            "approve_commit_tag",
            "targeted_fix",
            "no_change_review",
        ],
        "consume_prompt366_restart_contract": True,
        "connect_to_selected_prompt_contract_generation": True,
        "connect_to_prompt359_prompt360_path": True,
        "codex_live_execution_requires_explicit_flags": True,
        "commit_tag_execution_requires_explicit_flags": True,
        "remote_operations_enabled": False,
        "next_action_on_success": "continue_bounded_local_autonomous_loop",
        "next_action_on_blocked": "review_prompt368_loop_resume_blocker",
    }
    prompt368_input_ready = bool(
        prompt366_prompt364_verified and prompt366_prompt365_guard_clean
    )

    prompt369_input = {
        "prompt_id": "prompt369",
        "objective": "targeted_fix_route_integration",
        "targeted_fix_trigger_route": "requires_targeted_fix",
        "targeted_fix_prompt_required": True,
        "bounded_reentry_required": True,
        "live_flags_required": True,
        "codex_reentry_execution_allowed_by_default": False,
        "diff_capture_required": True,
        "return_to_review_route_required": True,
        "max_targeted_fix_attempts": (
            _TARGETED_FIX_POST_REENTRY_BOUNDED_CYCLE_DEFAULT_MAX_CYCLE_COUNT
        ),
        "stop_on_failure": True,
        "remote_operations_enabled": False,
        "push_pr_merge_enabled": False,
        "rollback_enabled": False,
        "next_action_on_success": "return_to_post_execution_review_route",
        "next_action_on_blocked": "review_prompt369_targeted_fix_blocker",
    }
    prompt369_input_ready = bool(
        prompt366_prompt364_verified and prompt366_prompt365_guard_clean
    )

    prompt366_commit_tag_auto_execution_planned = bool(prompt367_input_ready)
    prompt366_targeted_fix_route_integration_planned = bool(prompt369_input_ready)
    prompt366_integrated_loop_resume_planned = bool(prompt368_input_ready)

    blockers: list[str] = []
    if not git_state_available:
        _append_reason(blockers, "prompt366_git_state_unavailable")
    if not prompt366_prompt364_verified:
        _append_reason(blockers, "prompt364_verified_next_cycle_handoff_missing")
    if not prompt366_prompt365_guard_clean:
        _append_reason(blockers, "prompt365_clean_source_mutation_guard_missing")
    if not prompt367_input_ready:
        _append_reason(blockers, "prompt367_approve_commit_tag_plan_missing")
    if git_state_available and not prompt366_previous_source_tag_verified:
        _append_reason(blockers, "prompt366_previous_source_tag_missing")
    if git_state_available and not prompt366_head_tag_verified:
        _append_reason(blockers, "prompt366_head_tag_missing")
    if git_state_available and not prompt366_worktree_clean:
        _append_reason(blockers, "prompt366_tracked_worktree_not_clean")
    if git_state_available and staged_tracked_files:
        _append_reason(blockers, "prompt366_staged_tracked_files_present")
    if git_state_available and unstaged_tracked_files:
        _append_reason(blockers, "prompt366_unstaged_tracked_files_present")

    prompt366_ready = not blockers
    prompt366_continuation_status = "ready" if prompt366_ready else "blocked"
    prompt366_next_cycle_restart_ready = bool(prompt366_ready)
    prompt366_active_blocked_reasons = _normalize_string_list(
        blockers,
        sort_items=False,
    )
    prompt366_active_blocked_reason = (
        prompt366_active_blocked_reasons[0]
        if prompt366_active_blocked_reasons
        else ""
    )
    prompt366_authoritative_next_action = (
        "prepare_prompt367_bounded_commit_tag_execution_adapter"
        if prompt366_ready
        else prompt366_active_blocked_reason
    )
    prompt366_manual_required = bool(
        not prompt366_ready
        and any(
            blocker
            in {
                "prompt366_git_state_unavailable",
                "prompt366_previous_source_tag_missing",
                "prompt366_head_tag_missing",
                "prompt366_tracked_worktree_not_clean",
                "prompt366_staged_tracked_files_present",
                "prompt366_unstaged_tracked_files_present",
            }
            for blocker in blockers
        )
    )
    prompt366_replan_required = bool(
        not prompt366_ready
        and any(
            blocker
            in {
                "prompt364_verified_next_cycle_handoff_missing",
                "prompt365_clean_source_mutation_guard_missing",
                "prompt367_approve_commit_tag_plan_missing",
            }
            for blocker in blockers
        )
    )

    prompt366_restart_contract_payload = {
        "prompt366_schema_version": _PROMPT366_SCHEMA_VERSION,
        "source_prompt": "prompt364",
        "source_action": "prepare_next_local_cycle",
        "source_head_tag": expected_head_tag_name,
        "previous_source_tag": previous_source_tag_name,
        "local_only": True,
        "remote_operations_enabled": False,
        "codex_execution_performed": False,
        "commit_tag_execution_performed": False,
        "targeted_fix_execution_performed": False,
        "next_prompt_sequence": ["prompt367", "prompt368", "prompt369"],
        "authoritative_next_action": prompt366_authoritative_next_action,
        "prompt366_continuation_status": prompt366_continuation_status,
        "prompt366_next_cycle_restart_ready": prompt366_next_cycle_restart_ready,
        "prompt367_input": prompt367_input,
        "prompt368_input": prompt368_input,
        "prompt369_input": prompt369_input,
    }
    prompt366_contract_payload = {
        "prompt366_schema_version": _PROMPT366_SCHEMA_VERSION,
        "prompt366_continuation_status": prompt366_continuation_status,
        "prompt366_next_cycle_restart_ready": prompt366_next_cycle_restart_ready,
        "prompt366_source_prompt": "prompt364",
        "prompt366_source_action": "prepare_next_local_cycle",
        "prompt366_prompt364_verified": prompt366_prompt364_verified,
        "prompt366_prompt365_guard_clean": prompt366_prompt365_guard_clean,
        "prompt366_worktree_clean": prompt366_worktree_clean,
        "prompt366_previous_source_tag_verified": (
            prompt366_previous_source_tag_verified
        ),
        "prompt366_head_tag_verified": prompt366_head_tag_verified,
        "prompt366_recovered_prompt364_evidence_used": (
            prompt366_recovered_prompt364_evidence_used
        ),
        "prompt366_recovered_prompt365_evidence_used": (
            prompt366_recovered_prompt365_evidence_used
        ),
        "prompt366_prompt364_source_path": prompt366_prompt364_source_path,
        "prompt366_prompt365_source_path": prompt366_prompt365_source_path,
        "prompt366_next_cycle_restart_contract_path": str(
            prompt366_restart_contract_path
        ),
        "prompt366_prompt367_input_ready": prompt367_input_ready,
        "prompt366_prompt368_input_ready": prompt368_input_ready,
        "prompt366_prompt369_input_ready": prompt369_input_ready,
        "prompt366_commit_tag_auto_execution_planned": (
            prompt366_commit_tag_auto_execution_planned
        ),
        "prompt366_targeted_fix_route_integration_planned": (
            prompt366_targeted_fix_route_integration_planned
        ),
        "prompt366_integrated_loop_resume_planned": (
            prompt366_integrated_loop_resume_planned
        ),
        "prompt366_authoritative_next_action": prompt366_authoritative_next_action,
        "prompt366_next_action": prompt366_authoritative_next_action,
        "prompt366_manual_required": prompt366_manual_required,
        "prompt366_replan_required": prompt366_replan_required,
        "prompt366_active_blocked_reason": prompt366_active_blocked_reason,
        "prompt366_active_blocked_reasons": prompt366_active_blocked_reasons,
        "prompt367_input": prompt367_input,
        "prompt368_input": prompt368_input,
        "prompt369_input": prompt369_input,
    }

    prompt366_contract_path.parent.mkdir(parents=True, exist_ok=True)
    _write_json(prompt366_contract_path, prompt366_contract_payload)
    _write_json(prompt366_restart_contract_path, prompt366_restart_contract_payload)
    return prompt366_contract_payload, prompt366_restart_contract_payload

def _build_prompt367_bounded_commit_tag_execution_adapter(
    *,
    run_state_payload: Mapping[str, Any] | None,
    run_root: Path | None = None,
    execution_repo_path: str = "",
    current_prompt366_source_path: str = "",
) -> dict[str, Any]:
    artifact_root = run_root if run_root is not None else Path(".")
    plan_path = artifact_root / "prompt367_bounded_commit_tag_execution_plan.json"
    receipt_path = artifact_root / "prompt367_bounded_commit_tag_execution_receipt.json"
    stdout_path = artifact_root / "prompt367_bounded_commit_tag_execution_stdout.txt"
    stderr_path = artifact_root / "prompt367_bounded_commit_tag_execution_stderr.txt"
    run_state = dict(run_state_payload or {})
    normalized_repo_path = _normalize_text(
        execution_repo_path,
        default=str(Path.cwd()),
    )
    current_source_path = _normalize_text(current_prompt366_source_path, default="")
    minimum_required_flags = [
        "project_browser_autonomous_approve_commit_tag_execution_enabled",
        "project_browser_autonomous_approve_commit_tag_execution_confirmed",
    ]

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    def _unique_string_list(values: Sequence[str]) -> list[str]:
        seen: set[str] = set()
        ordered: list[str] = []
        for value in values:
            normalized = _normalize_text(value, default="")
            if not normalized or normalized in seen:
                continue
            seen.add(normalized)
            ordered.append(normalized)
        return ordered

    def _normalize_prompt367_input(payload: Mapping[str, Any] | None) -> dict[str, Any]:
        source = dict(payload) if isinstance(payload, Mapping) else {}
        required_flags = _normalize_string_list(
            source.get("required_execution_flags"),
            sort_items=False,
        )
        required_flags = _unique_string_list([*required_flags, *minimum_required_flags])
        return {
            "prompt_id": _normalize_text(source.get("prompt_id"), default=""),
            "objective": _normalize_text(source.get("objective"), default=""),
            "approve_commit_tag_source_prompt": _normalize_text(
                source.get("approve_commit_tag_source_prompt"),
                default="",
            ),
            "approve_commit_tag_route_decision": _normalize_text(
                source.get("approve_commit_tag_route_decision"),
                default="",
            ),
            "approve_commit_tag_plan_source_path": _normalize_text(
                source.get("approve_commit_tag_plan_source_path"),
                default="",
            ),
            "approve_commit_tag_commands_source_path": _normalize_text(
                source.get("approve_commit_tag_commands_source_path"),
                default="",
            ),
            "expected_commit_message": _normalize_text(
                source.get("expected_commit_message"),
                default="",
            ),
            "expected_tag_name": _normalize_text(
                source.get("expected_tag_name"),
                default="",
            ),
            "expected_tracked_files": _normalize_string_list(
                source.get("expected_tracked_files"),
                sort_items=True,
            ),
            "execution_flags_required": _prompt357_as_boolish(
                source.get("execution_flags_required"),
                default=True,
            ),
            "required_execution_flags": required_flags,
            "commit_tag_execution_allowed_by_default": _prompt357_as_boolish(
                source.get("commit_tag_execution_allowed_by_default"),
                default=False,
            ),
            "remote_operations_enabled": _prompt357_as_boolish(
                source.get("remote_operations_enabled"),
                default=False,
            ),
            "push_pr_merge_enabled": _prompt357_as_boolish(
                source.get("push_pr_merge_enabled"),
                default=False,
            ),
            "pr_merge_enabled": _prompt357_as_boolish(
                source.get("pr_merge_enabled"),
                default=False,
            ),
            "rollback_enabled": _prompt357_as_boolish(
                source.get("rollback_enabled"),
                default=False,
            ),
            "next_action_on_success": _normalize_text(
                source.get("next_action_on_success"),
                default="run_prompt367_clean_rerun_verification",
            ),
            "next_action_on_blocked": _normalize_text(
                source.get("next_action_on_blocked"),
                default="review_prompt367_commit_tag_blocker",
            ),
        }

    def _valid_prompt367_prompt366_evidence(payload: Mapping[str, Any] | None) -> bool:
        source = dict(payload) if isinstance(payload, Mapping) else {}
        prompt367_input = _normalize_prompt367_input(source.get("prompt367_input"))
        return bool(
            _normalize_text(
                source.get("prompt366_continuation_status"),
                default="",
            )
            == "ready"
            and _prompt357_as_boolish(
                source.get("prompt366_next_cycle_restart_ready"),
                default=False,
            )
            and _prompt357_as_boolish(
                source.get("prompt366_prompt367_input_ready"),
                default=False,
            )
            and _normalize_text(
                source.get("prompt366_next_action"),
                default="",
            )
            == "prepare_prompt367_bounded_commit_tag_execution_adapter"
            and bool(prompt367_input)
            and prompt367_input.get("objective")
            == "bounded_local_commit_tag_execution_adapter"
        )

    def _recover_latest_valid_prompt366_evidence() -> tuple[dict[str, Any], str]:
        recovery_root = Path("/tmp/codex-local-runner-checks")
        if not recovery_root.exists() or not recovery_root.is_dir():
            return {}, ""

        candidates: list[tuple[float, Path]] = []
        for pattern in ("run_state.json", "prompt366_local_autonomous_continuation_contract.json"):
            for candidate_path in recovery_root.rglob(pattern):
                try:
                    candidate_mtime = candidate_path.stat().st_mtime
                except OSError:
                    continue
                candidates.append((candidate_mtime, candidate_path))

        for _, candidate_path in sorted(candidates, key=lambda item: item[0], reverse=True):
            try:
                payload = _read_json_object_if_exists(candidate_path)
            except (OSError, ValueError, json.JSONDecodeError):
                payload = None
            if _valid_prompt367_prompt366_evidence(payload):
                return dict(payload or {}), str(candidate_path)
        return {}, ""

    def _collect_git_state(
        repo_path: str,
    ) -> tuple[bool, list[str], list[str], list[str]]:
        if not repo_path:
            return False, [], [], []
        try:
            status_short = _run_git(
                repo_path,
                ["status", "--short", "--untracked-files=no"],
                timeout_seconds=10,
            )
            unstaged_names = _run_git(
                repo_path,
                ["diff", "--name-only"],
                timeout_seconds=10,
            )
            staged_names = _run_git(
                repo_path,
                ["diff", "--cached", "--name-only"],
                timeout_seconds=10,
            )
        except (OSError, subprocess.TimeoutExpired):
            return False, [], [], []

        if (
            status_short.returncode != 0
            or unstaged_names.returncode != 0
            or staged_names.returncode != 0
        ):
            return False, [], [], []

        status_paths = [
            path_text
            for path_text in (
                _parse_git_status_path(raw_line.rstrip("\n"))
                for raw_line in (status_short.stdout or "").splitlines()
            )
            if path_text
        ]
        unstaged = _normalize_string_list(
            [
                line.strip()
                for line in (unstaged_names.stdout or "").splitlines()
                if line.strip()
            ],
            sort_items=True,
        )
        staged = _normalize_string_list(
            [
                line.strip()
                for line in (staged_names.stdout or "").splitlines()
                if line.strip()
            ],
            sort_items=True,
        )
        actual = _normalize_string_list(
            sorted(set(status_paths) | set(unstaged) | set(staged)),
            sort_items=True,
        )
        return True, actual, staged, unstaged

    current_prompt366_evidence = dict(run_state)
    current_prompt366_valid = _valid_prompt367_prompt366_evidence(current_prompt366_evidence)
    recovered_prompt366_evidence: dict[str, Any] = {}
    recovered_prompt366_source_path = ""
    if not current_prompt366_valid:
        (
            recovered_prompt366_evidence,
            recovered_prompt366_source_path,
        ) = _recover_latest_valid_prompt366_evidence()

    recovered_prompt366_evidence_used = bool(
        (not current_prompt366_valid) and recovered_prompt366_source_path
    )
    effective_prompt366 = (
        recovered_prompt366_evidence
        if recovered_prompt366_evidence_used
        else current_prompt366_evidence
    )
    prompt366_source_path = _normalize_text(
        recovered_prompt366_source_path if recovered_prompt366_evidence_used else current_source_path,
        default="",
    )
    prompt366_ready_evidence_available = _valid_prompt367_prompt366_evidence(
        effective_prompt366
    )

    prompt367_input = _normalize_prompt367_input(effective_prompt366.get("prompt367_input"))
    prompt367_source_prompt = _normalize_text(
        effective_prompt366.get("prompt366_source_prompt"),
        default="",
    )
    prompt367_source_action = _normalize_text(
        effective_prompt366.get("prompt366_source_action"),
        default="",
    )
    prompt367_expected_tracked_files = _normalize_string_list(
        prompt367_input.get("expected_tracked_files"),
        sort_items=True,
    )
    prompt367_expected_commit_message = _normalize_text(
        prompt367_input.get("expected_commit_message"),
        default="",
    )
    prompt367_expected_tag_name = _normalize_text(
        prompt367_input.get("expected_tag_name"),
        default="",
    )
    prompt367_implementation_tracked_files = _normalize_string_list(
        _PROMPT367_IMPLEMENTATION_TRACKED_FILES,
        sort_items=True,
    )
    prompt367_implementation_commit_message = _PROMPT367_IMPLEMENTATION_COMMIT_MESSAGE
    prompt367_implementation_tag_name = _PROMPT367_IMPLEMENTATION_TAG_NAME
    prompt367_execution_flags_required = _unique_string_list(
        _normalize_string_list(
            prompt367_input.get("required_execution_flags"),
            sort_items=False,
        )
        or minimum_required_flags
    )
    prompt367_execution_enabled = _prompt357_as_boolish(
        run_state.get("project_browser_autonomous_approve_commit_tag_execution_enabled"),
        default=False,
    )
    prompt367_execution_confirmed = _prompt357_as_boolish(
        run_state.get("project_browser_autonomous_approve_commit_tag_execution_confirmed"),
        default=False,
    )
    prompt367_execution_requested = bool(
        prompt367_execution_enabled and prompt367_execution_confirmed
    )
    prompt367_prompt367_input_ready = bool(
        prompt366_ready_evidence_available
        and prompt367_input.get("objective") == "bounded_local_commit_tag_execution_adapter"
        and _normalize_text(prompt367_input.get("prompt_id"), default="") == "prompt367"
    )
    prompt367_approve_commit_tag_plan_ready = bool(
        prompt367_prompt367_input_ready
        and _normalize_text(
            prompt367_input.get("approve_commit_tag_plan_source_path"),
            default="",
        )
        and _normalize_text(
            prompt367_input.get("approve_commit_tag_commands_source_path"),
            default="",
        )
        and _normalize_text(
            prompt367_input.get("approve_commit_tag_source_prompt"),
            default="",
        )
    )

    git_state_available, prompt367_actual_tracked_files, prompt367_staged_tracked_files, prompt367_unstaged_tracked_files = _collect_git_state(
        normalized_repo_path
    )

    def _prompt367_tag_exists(tag_name: str) -> tuple[bool, bool]:
        if not git_state_available or not tag_name:
            return git_state_available, False
        try:
            tag_exists_result = _run_git(
                normalized_repo_path,
                ["rev-parse", "--verify", f"refs/tags/{tag_name}"],
                timeout_seconds=10,
            )
        except (OSError, subprocess.TimeoutExpired):
            return False, False
        if tag_exists_result.returncode == 0:
            return True, True
        if tag_exists_result.returncode == 128:
            return True, False
        return False, False

    prompt367_tag_lookup_available, prompt367_tag_already_exists = _prompt367_tag_exists(
        prompt367_expected_tag_name
    )
    (
        prompt367_implementation_tag_lookup_available,
        prompt367_implementation_tag_already_exists,
    ) = _prompt367_tag_exists(prompt367_implementation_tag_name)
    if not prompt367_tag_lookup_available or not prompt367_implementation_tag_lookup_available:
        git_state_available = False
        prompt367_actual_tracked_files = []
        prompt367_staged_tracked_files = []
        prompt367_unstaged_tracked_files = []

    prompt367_implementation_changes_present = bool(
        not prompt367_execution_requested
        and git_state_available
        and not prompt367_staged_tracked_files
        and prompt367_actual_tracked_files == prompt367_implementation_tracked_files
        and not prompt367_implementation_tag_already_exists
    )
    if prompt367_implementation_changes_present:
        prompt367_expected_tracked_files = list(prompt367_implementation_tracked_files)
        prompt367_expected_commit_message = prompt367_implementation_commit_message
        prompt367_expected_tag_name = prompt367_implementation_tag_name
        prompt367_tag_already_exists = prompt367_implementation_tag_already_exists

    blockers: list[str] = []
    if not prompt366_ready_evidence_available:
        _append_reason(blockers, "prompt366_ready_evidence_missing")
    if not prompt367_input:
        _append_reason(blockers, "prompt367_input_missing")
    if not prompt367_expected_tracked_files:
        _append_reason(blockers, "prompt367_expected_tracked_files_missing")
    if not prompt367_expected_commit_message:
        _append_reason(blockers, "prompt367_expected_commit_message_missing")
    if not prompt367_expected_tag_name:
        _append_reason(blockers, "prompt367_expected_tag_name_missing")
    if not git_state_available:
        _append_reason(blockers, "prompt367_git_state_unavailable")
    if git_state_available and prompt367_staged_tracked_files:
        _append_reason(blockers, "prompt367_staged_tracked_files_present")
    if git_state_available:
        if prompt367_execution_requested:
            if prompt367_unstaged_tracked_files != prompt367_expected_tracked_files:
                _append_reason(blockers, "prompt367_tracked_files_do_not_match_expected")
        elif (
            not prompt367_implementation_changes_present
            and prompt367_actual_tracked_files
            and prompt367_actual_tracked_files != prompt367_expected_tracked_files
        ):
            _append_reason(blockers, "prompt367_tracked_files_do_not_match_expected")
    if git_state_available and prompt367_execution_requested and prompt367_tag_already_exists:
        _append_reason(blockers, "prompt367_tag_already_exists")

    command_sequence: list[list[str]] = [
        ["git", "add", "--", *prompt367_expected_tracked_files],
        ["git", "commit", "-m", prompt367_expected_commit_message],
        ["git", "tag", prompt367_expected_tag_name],
    ]
    command_results: list[dict[str, Any]] = []
    stdout_sections: list[str] = []
    stderr_sections: list[str] = []
    prompt367_execution_adapter_status = "blocked"
    prompt367_execution_status = "not_run"
    prompt367_execution_allowed = False
    prompt367_execution_attempted = False
    prompt367_execution_performed = False
    prompt367_git_add_performed = False
    prompt367_git_commit_performed = False
    prompt367_git_tag_performed = False
    prompt367_commit_sha = ""
    prompt367_tag_name = ""
    prompt367_returncode: int | None = None
    prompt367_authoritative_next_action = ""
    prompt367_next_action = ""
    prompt367_manual_required = False
    prompt367_replan_required = False
    prompt367_active_blocked_reasons: list[str] = []
    prompt367_active_blocked_reason = ""

    if blockers:
        prompt367_execution_adapter_status = "blocked"
        prompt367_execution_status = "not_run"
        prompt367_execution_allowed = False
        prompt367_execution_attempted = False
        prompt367_execution_performed = False
        prompt367_git_add_performed = False
        prompt367_git_commit_performed = False
        prompt367_git_tag_performed = False
        prompt367_active_blocked_reasons = _normalize_string_list(
            blockers,
            sort_items=False,
        )
        prompt367_active_blocked_reason = (
            prompt367_active_blocked_reasons[0]
            if prompt367_active_blocked_reasons
            else ""
        )
        prompt367_authoritative_next_action = prompt367_active_blocked_reason
        prompt367_next_action = prompt367_active_blocked_reason
    elif prompt367_implementation_changes_present:
        prompt367_execution_adapter_status = "implementation_in_progress"
        prompt367_execution_status = "not_run"
        prompt367_execution_allowed = False
        prompt367_execution_attempted = False
        prompt367_execution_performed = False
        prompt367_git_add_performed = False
        prompt367_git_commit_performed = False
        prompt367_git_tag_performed = False
        prompt367_active_blocked_reasons = ["prompt367_implementation_changes_present"]
        prompt367_active_blocked_reason = "prompt367_implementation_changes_present"
        prompt367_authoritative_next_action = "commit_prompt367_then_clean_rerun"
        prompt367_next_action = "commit_prompt367_then_clean_rerun"
    elif not prompt367_execution_requested:
        prompt367_execution_adapter_status = "ready_for_explicit_execution"
        prompt367_execution_status = "not_run"
        prompt367_execution_allowed = False
        prompt367_execution_attempted = False
        prompt367_execution_performed = False
        prompt367_git_add_performed = False
        prompt367_git_commit_performed = False
        prompt367_git_tag_performed = False
        prompt367_active_blocked_reasons = []
        prompt367_active_blocked_reason = ""
        prompt367_authoritative_next_action = (
            "run_with_explicit_prompt367_commit_tag_execution_flags"
        )
        prompt367_next_action = "run_with_explicit_prompt367_commit_tag_execution_flags"
    else:
        prompt367_execution_adapter_status = "blocked"
        prompt367_execution_status = "failed"
        prompt367_execution_allowed = True
        prompt367_execution_attempted = True

        def _record_command_result(
            label: str,
            command: list[str],
            result: subprocess.CompletedProcess[str] | None,
            error_text: str = "",
        ) -> int:
            stdout_text = _normalize_text(
                "" if result is None else result.stdout,
                default="",
            )
            stderr_text = _normalize_text(
                error_text or ("" if result is None else result.stderr),
                default="",
            )
            returncode = (
                int(result.returncode)
                if result is not None
                else 1
            )
            command_results.append(
                {
                    "label": label,
                    "command": list(command),
                    "returncode": returncode,
                }
            )
            stdout_sections.append(
                f"$ {' '.join(command)}\n{stdout_text}".rstrip() + "\n"
            )
            stderr_sections.append(
                f"$ {' '.join(command)}\n{stderr_text}".rstrip() + "\n"
            )
            return returncode

        try:
            add_result = _run_git(
                normalized_repo_path,
                ["add", "--", *prompt367_expected_tracked_files],
                timeout_seconds=30,
            )
            prompt367_git_add_performed = True
            prompt367_returncode = _record_command_result(
                "git_add",
                command_sequence[0],
                add_result,
            )
        except (OSError, subprocess.TimeoutExpired) as exc:
            prompt367_git_add_performed = True
            prompt367_returncode = _record_command_result(
                "git_add",
                command_sequence[0],
                None,
                error_text=str(exc),
            )
        else:
            if add_result.returncode == 0:
                try:
                    commit_result = _run_git(
                        normalized_repo_path,
                        ["commit", "-m", prompt367_expected_commit_message],
                        timeout_seconds=30,
                    )
                    prompt367_git_commit_performed = True
                    prompt367_returncode = _record_command_result(
                        "git_commit",
                        command_sequence[1],
                        commit_result,
                    )
                except (OSError, subprocess.TimeoutExpired) as exc:
                    prompt367_git_commit_performed = True
                    prompt367_returncode = _record_command_result(
                        "git_commit",
                        command_sequence[1],
                        None,
                        error_text=str(exc),
                    )
                else:
                    if commit_result.returncode == 0:
                        try:
                            head_result = _run_git(
                                normalized_repo_path,
                                ["rev-parse", "HEAD"],
                                timeout_seconds=10,
                            )
                        except (OSError, subprocess.TimeoutExpired):
                            head_result = None
                        if head_result is not None and head_result.returncode == 0:
                            prompt367_commit_sha = _normalize_text(
                                head_result.stdout,
                                default="",
                            )
                        try:
                            tag_result = _run_git(
                                normalized_repo_path,
                                ["tag", prompt367_expected_tag_name],
                                timeout_seconds=30,
                            )
                            prompt367_git_tag_performed = True
                            prompt367_returncode = _record_command_result(
                                "git_tag",
                                command_sequence[2],
                                tag_result,
                            )
                        except (OSError, subprocess.TimeoutExpired) as exc:
                            prompt367_git_tag_performed = True
                            prompt367_returncode = _record_command_result(
                                "git_tag",
                                command_sequence[2],
                                None,
                                error_text=str(exc),
                            )
                        else:
                            if tag_result.returncode == 0:
                                prompt367_tag_name = prompt367_expected_tag_name
                                prompt367_execution_adapter_status = "executed"
                                prompt367_execution_status = "completed"
                                prompt367_execution_performed = True
                                prompt367_authoritative_next_action = (
                                    "run_prompt367_clean_rerun_verification"
                                )
                                prompt367_next_action = (
                                    "run_prompt367_clean_rerun_verification"
                                )
                                prompt367_active_blocked_reasons = []
                                prompt367_active_blocked_reason = ""
        if prompt367_execution_status != "completed":
            prompt367_execution_performed = bool(prompt367_git_add_performed)
            prompt367_authoritative_next_action = "prompt367_execution_failed"
            prompt367_next_action = "prompt367_execution_failed"
            prompt367_active_blocked_reasons = ["prompt367_execution_failed"]
            prompt367_active_blocked_reason = "prompt367_execution_failed"

    final_git_state_available, final_actual_tracked_files, final_staged_tracked_files, final_unstaged_tracked_files = _collect_git_state(
        normalized_repo_path
    )
    final_git_state = {
        "git_state_available": final_git_state_available,
        "actual_tracked_files": final_actual_tracked_files,
        "staged_tracked_files": final_staged_tracked_files,
        "unstaged_tracked_files": final_unstaged_tracked_files,
        "untracked_files_ignored": True,
    }

    if prompt367_returncode is None and prompt367_execution_status == "not_run":
        prompt367_returncode = None

    plan_payload: dict[str, Any] = {
        "prompt367_schema_version": _PROMPT367_SCHEMA_VERSION,
        "prompt367_execution_adapter_status": prompt367_execution_adapter_status,
        "prompt367_execution_status": prompt367_execution_status,
        "prompt367_source_prompt": prompt367_source_prompt,
        "prompt367_source_action": prompt367_source_action,
        "prompt367_recovered_prompt366_evidence_used": recovered_prompt366_evidence_used,
        "prompt367_prompt366_source_path": prompt366_source_path,
        "prompt367_prompt367_input_ready": prompt367_prompt367_input_ready,
        "prompt367_approve_commit_tag_plan_ready": prompt367_approve_commit_tag_plan_ready,
        "prompt367_expected_tracked_files": prompt367_expected_tracked_files,
        "prompt367_actual_tracked_files": prompt367_actual_tracked_files,
        "prompt367_staged_tracked_files": prompt367_staged_tracked_files,
        "prompt367_untracked_files_ignored": True,
        "prompt367_expected_commit_message": prompt367_expected_commit_message,
        "prompt367_expected_tag_name": prompt367_expected_tag_name,
        "prompt367_execution_flags_required": prompt367_execution_flags_required,
        "prompt367_execution_enabled": prompt367_execution_enabled,
        "prompt367_execution_confirmed": prompt367_execution_confirmed,
        "prompt367_execution_allowed": prompt367_execution_allowed,
        "prompt367_execution_attempted": prompt367_execution_attempted,
        "prompt367_execution_performed": prompt367_execution_performed,
        "prompt367_git_add_performed": prompt367_git_add_performed,
        "prompt367_git_commit_performed": prompt367_git_commit_performed,
        "prompt367_git_tag_performed": prompt367_git_tag_performed,
        "prompt367_commit_sha": prompt367_commit_sha,
        "prompt367_tag_name": prompt367_tag_name,
        "prompt367_returncode": prompt367_returncode,
        "prompt367_stdout_path": str(stdout_path),
        "prompt367_stderr_path": str(stderr_path),
        "prompt367_plan_path": str(plan_path),
        "prompt367_receipt_path": str(receipt_path),
        "prompt367_authoritative_next_action": prompt367_authoritative_next_action,
        "prompt367_next_action": prompt367_next_action,
        "prompt367_manual_required": prompt367_manual_required,
        "prompt367_replan_required": prompt367_replan_required,
        "prompt367_active_blocked_reason": prompt367_active_blocked_reason,
        "prompt367_active_blocked_reasons": prompt367_active_blocked_reasons,
        "prompt367_command_sequence": command_sequence,
        "prompt367_pre_execution_unstaged_tracked_files": prompt367_unstaged_tracked_files,
        "prompt367_target_tag_already_exists": prompt367_tag_already_exists,
    }
    receipt_payload: dict[str, Any] = {
        **plan_payload,
        "commands": command_results,
        "final_git_state": final_git_state,
    }

    plan_path.parent.mkdir(parents=True, exist_ok=True)
    stdout_path.write_text("".join(stdout_sections), encoding="utf-8")
    stderr_path.write_text("".join(stderr_sections), encoding="utf-8")
    _write_json(plan_path, plan_payload)
    _write_json(receipt_path, receipt_payload)

    return {
        key: value
        for key, value in plan_payload.items()
        if key.startswith("prompt367_")
    }

def _build_prompt368_integrated_loop_resume_controller(
    *,
    run_state_payload: Mapping[str, Any] | None,
    run_root: Path | None = None,
    execution_repo_path: str = "",
    current_prompt366_source_path: str = "",
    current_prompt367_source_path: str = "",
) -> dict[str, Any]:
    artifact_root = run_root if run_root is not None else Path(".")
    controller_path = artifact_root / "prompt368_integrated_loop_resume_controller.json"
    resume_contract_path = artifact_root / "prompt368_next_cycle_resume_contract.json"
    receipt_path = artifact_root / "prompt368_resume_receipt.json"
    selected_prompt_contract_path_default = (
        artifact_root / _PROMPT368_DEFAULT_SELECTED_PROMPT_CONTRACT_FILENAME
    )
    run_state = dict(run_state_payload or {})
    normalized_repo_path = _normalize_text(
        execution_repo_path,
        default=str(Path.cwd()),
    )

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    def _normalize_prompt368_input(value: Any) -> dict[str, Any]:
        source = dict(value) if isinstance(value, Mapping) else {}
        return {
            "prompt_id": _normalize_text(source.get("prompt_id"), default=""),
            "objective": _normalize_text(source.get("objective"), default=""),
            "next_action_source_prompt": _normalize_text(
                source.get("next_action_source_prompt"),
                default="",
            ),
            "next_action_source_action": _normalize_text(
                source.get("next_action_source_action"),
                default="",
            ),
            "resume_action": _normalize_text(
                source.get("resume_action"),
                default="",
            ),
            "current_local_cycle": _as_non_negative_int(
                source.get("current_local_cycle"),
                default=_LOCAL_AUTONOMOUS_CYCLE_V2_CURRENT_CYCLE,
            ),
            "max_local_cycles": _as_non_negative_int(
                source.get("max_local_cycles"),
                default=_LOCAL_AUTONOMOUS_CYCLE_V2_MAX_CYCLES,
            ),
            "selected_next_step": _normalize_text(
                source.get("selected_next_step"),
                default="",
            ),
            "selected_next_step_operation": _normalize_text(
                source.get("selected_next_step_operation"),
                default="",
            ),
            "selected_prompt_id": _normalize_text(
                source.get("selected_prompt_id"),
                default="",
            ),
            "selected_prompt_title": _normalize_text(
                source.get("selected_prompt_title"),
                default="",
            ),
            "selected_prompt_contract_path": _normalize_text(
                source.get("selected_prompt_contract_path"),
                default="",
            ),
            "selected_prompt_contract_ready": _prompt357_as_boolish(
                source.get("selected_prompt_contract_ready"),
                default=False,
            ),
            "selected_prompt_contract": (
                dict(source.get("selected_prompt_contract"))
                if isinstance(source.get("selected_prompt_contract"), Mapping)
                else {}
            ),
            "next_action_on_success": _normalize_text(
                source.get("next_action_on_success"),
                default="continue_bounded_local_autonomous_loop",
            ),
            "next_action_on_blocked": _normalize_text(
                source.get("next_action_on_blocked"),
                default="review_prompt368_loop_resume_blocker",
            ),
        }

    def _normalize_prompt369_input(value: Any) -> dict[str, Any]:
        source = dict(value) if isinstance(value, Mapping) else {}
        normalized = dict(source)
        normalized["prompt_id"] = _normalize_text(
            source.get("prompt_id"),
            default="",
        )
        normalized["objective"] = _normalize_text(
            source.get("objective"),
            default="",
        )
        normalized["next_action_on_success"] = _normalize_text(
            source.get("next_action_on_success"),
            default="",
        )
        normalized["next_action_on_blocked"] = _normalize_text(
            source.get("next_action_on_blocked"),
            default="",
        )
        normalized["remote_operations_enabled"] = _prompt357_as_boolish(
            source.get("remote_operations_enabled"),
            default=False,
        )
        normalized["push_pr_merge_enabled"] = _prompt357_as_boolish(
            source.get("push_pr_merge_enabled"),
            default=False,
        )
        normalized["rollback_enabled"] = _prompt357_as_boolish(
            source.get("rollback_enabled"),
            default=False,
        )
        return normalized

    def _prompt368_objective_matches(value: Any) -> bool:
        objective = _normalize_text(value, default="")
        if objective in {
            "integrated_next_action_loop_resume_controller",
            "integrated_next_cycle_loop_resume_controller",
            "integrated_loop_resume_controller",
        }:
            return True
        return bool(
            objective
            and "integrated" in objective
            and "resume" in objective
            and "controller" in objective
            and ("loop" in objective or "cycle" in objective)
        )

    def _valid_prompt368_prompt366_evidence(payload: Mapping[str, Any] | None) -> bool:
        source = dict(payload) if isinstance(payload, Mapping) else {}
        prompt368_input = _normalize_prompt368_input(source.get("prompt368_input"))
        return bool(
            _normalize_text(
                source.get("prompt366_continuation_status"),
                default="",
            )
            == "ready"
            and _prompt357_as_boolish(
                source.get("prompt366_next_cycle_restart_ready"),
                default=False,
            )
            and _prompt357_as_boolish(
                source.get("prompt366_prompt368_input_ready"),
                default=False,
            )
            and _normalize_text(
                source.get("prompt366_next_action"),
                default="",
            )
            == "prepare_prompt367_bounded_commit_tag_execution_adapter"
            and bool(prompt368_input)
            and _prompt368_objective_matches(prompt368_input.get("objective"))
        )

    def _valid_prompt368_prompt367_evidence(payload: Mapping[str, Any] | None) -> bool:
        source = dict(payload) if isinstance(payload, Mapping) else {}
        return bool(
            _normalize_text(
                source.get("prompt367_execution_adapter_status"),
                default="",
            )
            == "ready_for_explicit_execution"
            and _normalize_text(
                source.get("prompt367_execution_status"),
                default="",
            )
            == "not_run"
            and not _prompt357_as_boolish(
                source.get("prompt367_execution_performed"),
                default=False,
            )
            and not _prompt357_as_boolish(
                source.get("prompt367_git_add_performed"),
                default=False,
            )
            and not _prompt357_as_boolish(
                source.get("prompt367_git_commit_performed"),
                default=False,
            )
            and not _prompt357_as_boolish(
                source.get("prompt367_git_tag_performed"),
                default=False,
            )
            and _normalize_text(
                source.get("prompt367_next_action"),
                default="",
            )
            == "run_with_explicit_prompt367_commit_tag_execution_flags"
            and _normalize_text(
                source.get("prompt367_active_blocked_reason"),
                default="",
            )
            == ""
        )

    def _recover_latest_valid_run_state(
        validator: Callable[[Mapping[str, Any] | None], bool],
    ) -> tuple[dict[str, Any], str]:
        recovery_root = Path("/tmp/codex-local-runner-checks")
        if not recovery_root.exists() or not recovery_root.is_dir():
            return {}, ""

        candidates: list[tuple[float, Path]] = []
        for candidate_path in recovery_root.rglob("run_state.json"):
            try:
                candidate_mtime = candidate_path.stat().st_mtime
            except OSError:
                continue
            candidates.append((candidate_mtime, candidate_path))

        for _, candidate_path in sorted(candidates, key=lambda item: item[0], reverse=True):
            try:
                payload = _read_json_object_if_exists(candidate_path)
            except (OSError, ValueError, json.JSONDecodeError):
                payload = None
            if validator(payload):
                return dict(payload or {}), str(candidate_path)
        return {}, ""

    def _collect_git_state(
        repo_path: str,
    ) -> tuple[bool, list[str], list[str], list[str]]:
        if not repo_path:
            return False, [], [], []
        try:
            status_short = _run_git(
                repo_path,
                ["status", "--short", "--untracked-files=no"],
                timeout_seconds=10,
            )
            unstaged_names = _run_git(
                repo_path,
                ["diff", "--name-only"],
                timeout_seconds=10,
            )
            staged_names = _run_git(
                repo_path,
                ["diff", "--cached", "--name-only"],
                timeout_seconds=10,
            )
        except (OSError, subprocess.TimeoutExpired):
            return False, [], [], []

        if (
            status_short.returncode != 0
            or unstaged_names.returncode != 0
            or staged_names.returncode != 0
        ):
            return False, [], [], []

        status_paths = [
            path_text
            for path_text in (
                _parse_git_status_path(raw_line.rstrip("\n"))
                for raw_line in (status_short.stdout or "").splitlines()
            )
            if path_text
        ]
        unstaged = _normalize_string_list(
            [
                line.strip()
                for line in (unstaged_names.stdout or "").splitlines()
                if line.strip()
            ],
            sort_items=True,
        )
        staged = _normalize_string_list(
            [
                line.strip()
                for line in (staged_names.stdout or "").splitlines()
                if line.strip()
            ],
            sort_items=True,
        )
        actual = _normalize_string_list(
            sorted(set(status_paths) | set(unstaged) | set(staged)),
            sort_items=True,
        )
        return True, actual, staged, unstaged

    def _prompt368_tag_exists(tag_name: str) -> tuple[bool, bool]:
        if not normalized_repo_path or not tag_name:
            return False, False
        try:
            tag_exists_result = _run_git(
                normalized_repo_path,
                ["rev-parse", "--verify", f"refs/tags/{tag_name}"],
                timeout_seconds=10,
            )
        except (OSError, subprocess.TimeoutExpired):
            return False, False
        if tag_exists_result.returncode == 0:
            return True, True
        if tag_exists_result.returncode == 128:
            return True, False
        return False, False

    def _build_ready_next_action(prompt_id: str, prompt_title: str) -> str:
        normalized_prompt_id = _normalize_text(prompt_id, default="")
        normalized_prompt_title = _normalize_text(
            prompt_title,
            default="",
        ).replace("-", "_")
        if (
            normalized_prompt_id == "prompt369"
            and normalized_prompt_title == "targeted_fix_route_integration"
        ):
            return "prepare_prompt369_targeted_fix_route_integration"
        if normalized_prompt_id and normalized_prompt_title:
            return f"prepare_{normalized_prompt_id}_{normalized_prompt_title}"
        if normalized_prompt_id:
            return f"prepare_{normalized_prompt_id}"
        return "prepare_next_local_cycle_selected_prompt_contract"

    current_prompt366_evidence = dict(run_state)
    current_prompt366_valid = _valid_prompt368_prompt366_evidence(
        current_prompt366_evidence
    )
    recovered_prompt366_evidence: dict[str, Any] = {}
    recovered_prompt366_source_path = ""
    if not current_prompt366_valid:
        (
            recovered_prompt366_evidence,
            recovered_prompt366_source_path,
        ) = _recover_latest_valid_run_state(_valid_prompt368_prompt366_evidence)

    current_prompt367_evidence = dict(run_state)
    current_prompt367_valid = _valid_prompt368_prompt367_evidence(
        current_prompt367_evidence
    )
    recovered_prompt367_evidence: dict[str, Any] = {}
    recovered_prompt367_source_path = ""
    if not current_prompt367_valid:
        (
            recovered_prompt367_evidence,
            recovered_prompt367_source_path,
        ) = _recover_latest_valid_run_state(_valid_prompt368_prompt367_evidence)

    prompt368_recovered_prompt366_evidence_used = bool(
        (not current_prompt366_valid) and recovered_prompt366_source_path
    )
    prompt368_recovered_prompt367_evidence_used = bool(
        (not current_prompt367_valid) and recovered_prompt367_source_path
    )
    effective_prompt366 = (
        recovered_prompt366_evidence
        if prompt368_recovered_prompt366_evidence_used
        else current_prompt366_evidence
    )
    effective_prompt367 = (
        recovered_prompt367_evidence
        if prompt368_recovered_prompt367_evidence_used
        else current_prompt367_evidence
    )
    prompt368_prompt366_source_path = _normalize_text(
        recovered_prompt366_source_path
        if prompt368_recovered_prompt366_evidence_used
        else current_prompt366_source_path,
        default="",
    )
    prompt368_prompt367_source_path = _normalize_text(
        recovered_prompt367_source_path
        if prompt368_recovered_prompt367_evidence_used
        else current_prompt367_source_path,
        default="",
    )

    prompt366_ready_evidence_available = _valid_prompt368_prompt366_evidence(
        effective_prompt366
    )
    prompt367_clean_ready_evidence_available = _valid_prompt368_prompt367_evidence(
        effective_prompt367
    )
    prompt368_source_prompt366_status = _normalize_text(
        effective_prompt366.get("prompt366_continuation_status"),
        default="",
    )
    prompt368_source_prompt367_status = _normalize_text(
        effective_prompt367.get("prompt367_execution_adapter_status"),
        default="",
    )

    prompt368_input = _normalize_prompt368_input(effective_prompt366.get("prompt368_input"))
    prompt369_input = _normalize_prompt369_input(effective_prompt366.get("prompt369_input"))
    prompt368_prompt368_input_ready = bool(
        prompt366_ready_evidence_available
        and _prompt357_as_boolish(
            effective_prompt366.get("prompt366_prompt368_input_ready"),
            default=False,
        )
        and _normalize_text(prompt368_input.get("prompt_id"), default="") == "prompt368"
        and _prompt368_objective_matches(prompt368_input.get("objective"))
    )
    prompt369_input_ready = bool(
        prompt366_ready_evidence_available
        and _prompt357_as_boolish(
            effective_prompt366.get("prompt366_prompt369_input_ready"),
            default=False,
        )
        and _normalize_text(prompt369_input.get("prompt_id"), default="") == "prompt369"
        and _normalize_text(prompt369_input.get("objective"), default="")
        == "targeted_fix_route_integration"
    )

    prompt368_resume_iteration_current = _as_non_negative_int(
        prompt368_input.get("current_local_cycle"),
        default=_LOCAL_AUTONOMOUS_CYCLE_V2_CURRENT_CYCLE,
    )
    if prompt368_resume_iteration_current <= 0:
        prompt368_resume_iteration_current = _LOCAL_AUTONOMOUS_CYCLE_V2_CURRENT_CYCLE
    prompt368_resume_iteration_max = _as_non_negative_int(
        prompt368_input.get("max_local_cycles"),
        default=_LOCAL_AUTONOMOUS_CYCLE_V2_MAX_CYCLES,
    )
    if prompt368_resume_iteration_max <= 0:
        prompt368_resume_iteration_max = _LOCAL_AUTONOMOUS_CYCLE_V2_MAX_CYCLES
    prompt368_resume_source_action = _normalize_text(
        prompt368_input.get("resume_action")
        or prompt368_input.get("next_action_source_action")
        or effective_prompt366.get("prompt366_source_action"),
        default="",
    )

    git_state_available, prompt368_actual_tracked_files, prompt368_staged_tracked_files, prompt368_unstaged_tracked_files = _collect_git_state(
        normalized_repo_path
    )
    (
        prompt368_implementation_tag_lookup_available,
        prompt368_implementation_tag_already_exists,
    ) = _prompt368_tag_exists(_PROMPT368_IMPLEMENTATION_TAG_NAME)
    if not prompt368_implementation_tag_lookup_available:
        prompt368_implementation_tag_already_exists = False
    prompt368_worktree_clean = bool(
        git_state_available
        and not prompt368_actual_tracked_files
        and not prompt368_staged_tracked_files
        and not prompt368_unstaged_tracked_files
    )
    prompt368_implementation_changes_present = bool(
        git_state_available
        and not prompt368_staged_tracked_files
        and bool(prompt368_unstaged_tracked_files)
        and prompt368_actual_tracked_files == prompt368_unstaged_tracked_files
        and set(prompt368_actual_tracked_files).issubset(
            set(_PROMPT368_IMPLEMENTATION_TRACKED_FILES)
        )
        and "automation/orchestration/planned_execution_runner.py"
        in prompt368_actual_tracked_files
        and not prompt368_implementation_tag_already_exists
    )

    prompt368_selected_next_step = _normalize_text(
        prompt368_input.get("selected_next_step"),
        default="",
    )
    prompt368_selected_next_step_operation = _normalize_text(
        prompt368_input.get("selected_next_step_operation"),
        default="",
    )
    prompt368_selected_prompt_id = _normalize_text(
        prompt368_input.get("selected_prompt_id"),
        default="",
    )
    prompt368_selected_prompt_title = _normalize_text(
        prompt368_input.get("selected_prompt_title"),
        default="",
    )
    prompt368_selected_prompt_contract_path = _normalize_text(
        prompt368_input.get("selected_prompt_contract_path"),
        default="",
    )
    prompt368_selected_prompt_contract_payload = (
        dict(prompt368_input.get("selected_prompt_contract"))
        if isinstance(prompt368_input.get("selected_prompt_contract"), Mapping)
        else {}
    )

    if not prompt368_selected_next_step:
        prompt368_selected_next_step = (
            "prepare_next_local_cycle_selected_prompt_contract"
        )
    if not prompt368_selected_next_step_operation:
        prompt368_selected_next_step_operation = "emit_selected_prompt_contract"
    if not prompt368_selected_prompt_id and prompt369_input_ready:
        prompt368_selected_prompt_id = "prompt369"
    if not prompt368_selected_prompt_title and prompt368_selected_prompt_id == "prompt369":
        prompt368_selected_prompt_title = "targeted_fix_route_integration"
    if (
        not prompt368_selected_prompt_contract_path
        and prompt368_selected_prompt_id == "prompt369"
    ):
        prompt368_selected_prompt_contract_path = str(
            selected_prompt_contract_path_default
        )
    if (
        not prompt368_selected_prompt_contract_payload
        and prompt368_selected_prompt_id == "prompt369"
        and prompt369_input_ready
    ):
        prompt368_selected_prompt_contract_payload = {
            "selected_prompt_id": "prompt369",
            "selected_prompt_title": "targeted_fix_route_integration",
            "selected_next_step": prompt368_selected_next_step,
            "selected_next_step_operation": (
                prompt368_selected_next_step_operation
            ),
            "selected_prompt_contract_path": (
                prompt368_selected_prompt_contract_path
            ),
            "source_prompt": "prompt368",
            "source_action": "prepare_prompt369_targeted_fix_route_integration",
            "prompt369_input": dict(prompt369_input),
        }

    prompt368_selected_prompt_contract_ready = bool(
        prompt368_selected_next_step
        and prompt368_selected_next_step_operation
        and prompt368_selected_prompt_id
        and prompt368_selected_prompt_title
        and prompt368_selected_prompt_contract_path
        and (
            bool(prompt368_selected_prompt_contract_payload)
            or _prompt357_as_boolish(
                prompt368_input.get("selected_prompt_contract_ready"),
                default=False,
            )
        )
    )

    prompt368_execution_allowed = False
    prompt368_execution_attempted = False
    prompt368_execution_performed = False
    prompt368_codex_execution_performed = False
    prompt368_git_mutation_performed = False
    prompt368_remote_mutation_performed = False
    prompt368_manual_required = False
    prompt368_replan_required = False
    prompt368_resume_controller_status = "blocked"
    prompt368_resume_status = "not_prepared"
    prompt368_next_cycle_resume_contract_ready = False
    prompt368_integrated_loop_resume_ready = False
    prompt368_active_blocked_reasons: list[str] = []
    prompt368_active_blocked_reason = ""
    prompt368_authoritative_next_action = ""
    prompt368_next_action = ""

    blockers: list[str] = []
    if not prompt366_ready_evidence_available:
        _append_reason(blockers, "prompt366_ready_evidence_missing")
    if not prompt367_clean_ready_evidence_available:
        _append_reason(blockers, "prompt367_clean_ready_evidence_missing")
    if not prompt368_prompt368_input_ready:
        _append_reason(blockers, "prompt368_input_missing")
    if not prompt368_worktree_clean:
        _append_reason(blockers, "prompt368_worktree_not_clean")
    if (
        not prompt368_selected_next_step
        or not prompt368_selected_next_step_operation
        or not prompt368_selected_prompt_id
        or not prompt368_selected_prompt_title
    ):
        _append_reason(blockers, "prompt368_selected_next_step_missing")
    if not prompt368_selected_prompt_contract_ready:
        _append_reason(blockers, "prompt368_selected_prompt_contract_missing")

    if prompt368_implementation_changes_present:
        prompt368_resume_controller_status = "implementation_in_progress"
        prompt368_resume_status = "not_prepared"
        prompt368_authoritative_next_action = "commit_prompt368_then_clean_rerun"
        prompt368_next_action = "commit_prompt368_then_clean_rerun"
        prompt368_active_blocked_reasons = ["prompt368_implementation_changes_present"]
        prompt368_active_blocked_reason = (
            "prompt368_implementation_changes_present"
        )
    else:
        prompt368_next_cycle_resume_contract_ready = not blockers
        prompt368_integrated_loop_resume_ready = (
            prompt368_next_cycle_resume_contract_ready
        )
        if prompt368_next_cycle_resume_contract_ready:
            prompt368_resume_controller_status = "ready"
            prompt368_resume_status = "prepared"
            prompt368_authoritative_next_action = _build_ready_next_action(
                prompt368_selected_prompt_id,
                prompt368_selected_prompt_title,
            )
            prompt368_next_action = prompt368_authoritative_next_action
            prompt368_active_blocked_reasons = []
            prompt368_active_blocked_reason = ""
        else:
            _append_reason(blockers, "prompt368_resume_contract_not_ready")
            prompt368_manual_required = "prompt368_worktree_not_clean" in blockers
            prompt368_replan_required = any(
                blocker
                in {
                    "prompt366_ready_evidence_missing",
                    "prompt367_clean_ready_evidence_missing",
                    "prompt368_input_missing",
                    "prompt368_selected_next_step_missing",
                    "prompt368_selected_prompt_contract_missing",
                    "prompt368_resume_contract_not_ready",
                }
                for blocker in blockers
            )
            prompt368_active_blocked_reasons = _normalize_string_list(
                blockers,
                sort_items=False,
            )
            prompt368_active_blocked_reason = (
                prompt368_active_blocked_reasons[0]
                if prompt368_active_blocked_reasons
                else ""
            )
            prompt368_authoritative_next_action = prompt368_active_blocked_reason
            prompt368_next_action = prompt368_active_blocked_reason

    controller_payload: dict[str, Any] = {
        "prompt368_schema_version": _PROMPT368_SCHEMA_VERSION,
        "prompt368_resume_controller_status": prompt368_resume_controller_status,
        "prompt368_resume_status": prompt368_resume_status,
        "prompt368_source_prompt366_status": prompt368_source_prompt366_status,
        "prompt368_source_prompt367_status": prompt368_source_prompt367_status,
        "prompt368_recovered_prompt366_evidence_used": (
            prompt368_recovered_prompt366_evidence_used
        ),
        "prompt368_recovered_prompt367_evidence_used": (
            prompt368_recovered_prompt367_evidence_used
        ),
        "prompt368_prompt366_source_path": prompt368_prompt366_source_path,
        "prompt368_prompt367_source_path": prompt368_prompt367_source_path,
        "prompt368_prompt368_input_ready": prompt368_prompt368_input_ready,
        "prompt368_next_cycle_resume_contract_ready": (
            prompt368_next_cycle_resume_contract_ready
        ),
        "prompt368_integrated_loop_resume_ready": (
            prompt368_integrated_loop_resume_ready
        ),
        "prompt368_resume_iteration_current": (
            prompt368_resume_iteration_current
        ),
        "prompt368_resume_iteration_max": prompt368_resume_iteration_max,
        "prompt368_resume_source_action": prompt368_resume_source_action,
        "prompt368_selected_next_step": prompt368_selected_next_step,
        "prompt368_selected_next_step_operation": (
            prompt368_selected_next_step_operation
        ),
        "prompt368_selected_prompt_id": prompt368_selected_prompt_id,
        "prompt368_selected_prompt_title": prompt368_selected_prompt_title,
        "prompt368_selected_prompt_contract_ready": (
            prompt368_selected_prompt_contract_ready
        ),
        "prompt368_selected_prompt_contract_path": (
            prompt368_selected_prompt_contract_path
        ),
        "prompt368_resume_contract_path": str(resume_contract_path),
        "prompt368_controller_path": str(controller_path),
        "prompt368_receipt_path": str(receipt_path),
        "prompt368_execution_allowed": prompt368_execution_allowed,
        "prompt368_execution_attempted": prompt368_execution_attempted,
        "prompt368_execution_performed": prompt368_execution_performed,
        "prompt368_codex_execution_performed": (
            prompt368_codex_execution_performed
        ),
        "prompt368_git_mutation_performed": prompt368_git_mutation_performed,
        "prompt368_remote_mutation_performed": (
            prompt368_remote_mutation_performed
        ),
        "prompt368_authoritative_next_action": (
            prompt368_authoritative_next_action
        ),
        "prompt368_next_action": prompt368_next_action,
        "prompt368_manual_required": prompt368_manual_required,
        "prompt368_replan_required": prompt368_replan_required,
        "prompt368_active_blocked_reason": prompt368_active_blocked_reason,
        "prompt368_active_blocked_reasons": prompt368_active_blocked_reasons,
    }

    resume_contract_payload: dict[str, Any] = {
        **controller_payload,
        "local_only": True,
        "remote_operations_enabled": False,
        "selected_prompt_contract": prompt368_selected_prompt_contract_payload,
        "prompt368_input": dict(prompt368_input),
        "prompt369_input": dict(prompt369_input),
    }
    receipt_payload: dict[str, Any] = {
        **controller_payload,
        "prompt368_input": dict(prompt368_input),
        "prompt369_input": dict(prompt369_input),
        "prompt366_source_excerpt": {
            "prompt366_continuation_status": _normalize_text(
                effective_prompt366.get("prompt366_continuation_status"),
                default="",
            ),
            "prompt366_next_cycle_restart_ready": _prompt357_as_boolish(
                effective_prompt366.get("prompt366_next_cycle_restart_ready"),
                default=False,
            ),
            "prompt366_prompt368_input_ready": _prompt357_as_boolish(
                effective_prompt366.get("prompt366_prompt368_input_ready"),
                default=False,
            ),
            "prompt366_prompt369_input_ready": _prompt357_as_boolish(
                effective_prompt366.get("prompt366_prompt369_input_ready"),
                default=False,
            ),
            "prompt366_next_action": _normalize_text(
                effective_prompt366.get("prompt366_next_action"),
                default="",
            ),
        },
        "prompt367_source_excerpt": {
            "prompt367_execution_adapter_status": _normalize_text(
                effective_prompt367.get("prompt367_execution_adapter_status"),
                default="",
            ),
            "prompt367_execution_status": _normalize_text(
                effective_prompt367.get("prompt367_execution_status"),
                default="",
            ),
            "prompt367_execution_performed": _prompt357_as_boolish(
                effective_prompt367.get("prompt367_execution_performed"),
                default=False,
            ),
            "prompt367_git_add_performed": _prompt357_as_boolish(
                effective_prompt367.get("prompt367_git_add_performed"),
                default=False,
            ),
            "prompt367_git_commit_performed": _prompt357_as_boolish(
                effective_prompt367.get("prompt367_git_commit_performed"),
                default=False,
            ),
            "prompt367_git_tag_performed": _prompt357_as_boolish(
                effective_prompt367.get("prompt367_git_tag_performed"),
                default=False,
            ),
            "prompt367_next_action": _normalize_text(
                effective_prompt367.get("prompt367_next_action"),
                default="",
            ),
            "prompt367_active_blocked_reason": _normalize_text(
                effective_prompt367.get("prompt367_active_blocked_reason"),
                default="",
            ),
        },
        "git_state": {
            "git_state_available": git_state_available,
            "actual_tracked_files": prompt368_actual_tracked_files,
            "staged_tracked_files": prompt368_staged_tracked_files,
            "unstaged_tracked_files": prompt368_unstaged_tracked_files,
            "worktree_clean": prompt368_worktree_clean,
            "implementation_changes_present": (
                prompt368_implementation_changes_present
            ),
            "implementation_tag_already_exists": (
                prompt368_implementation_tag_already_exists
            ),
            "untracked_files_ignored": True,
        },
    }

    controller_path.parent.mkdir(parents=True, exist_ok=True)
    _write_json(controller_path, controller_payload)
    _write_json(resume_contract_path, resume_contract_payload)
    _write_json(receipt_path, receipt_payload)

    return {
        key: value
        for key, value in controller_payload.items()
        if key.startswith("prompt368_")
    }

def _build_prompt369_targeted_fix_route_integration_state(
    *,
    run_state_payload: Mapping[str, Any] | None,
    run_root: Path | None = None,
    current_prompt368_source_path: str = "",
    current_prompt362_source_path: str = "",
) -> dict[str, Any]:
    artifact_root = run_root if run_root is not None else Path(".")
    integration_path = artifact_root / "prompt369_targeted_fix_route_integration.json"
    reentry_contract_path = artifact_root / "prompt369_targeted_fix_reentry_contract.json"
    receipt_path = artifact_root / "prompt369_targeted_fix_route_receipt.json"
    run_state = dict(run_state_payload or {})

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    def _normalize_prompt369_input(value: Any) -> dict[str, Any]:
        source = dict(value) if isinstance(value, Mapping) else {}
        return {
            "prompt_id": _normalize_text(source.get("prompt_id"), default=""),
            "objective": _normalize_text(source.get("objective"), default=""),
            "targeted_fix_trigger_route": _normalize_text(
                source.get("targeted_fix_trigger_route"),
                default="",
            ),
            "targeted_fix_prompt_required": _prompt357_as_boolish(
                source.get("targeted_fix_prompt_required"),
                default=False,
            ),
            "bounded_reentry_required": _prompt357_as_boolish(
                source.get("bounded_reentry_required"),
                default=False,
            ),
            "live_flags_required": _prompt357_as_boolish(
                source.get("live_flags_required"),
                default=False,
            ),
            "codex_reentry_execution_allowed_by_default": _prompt357_as_boolish(
                source.get("codex_reentry_execution_allowed_by_default"),
                default=False,
            ),
            "diff_capture_required": _prompt357_as_boolish(
                source.get("diff_capture_required"),
                default=False,
            ),
            "return_to_review_route_required": _prompt357_as_boolish(
                source.get("return_to_review_route_required"),
                default=False,
            ),
            "max_targeted_fix_attempts": _as_non_negative_int(
                source.get("max_targeted_fix_attempts"),
                default=0,
            ),
            "stop_on_failure": _prompt357_as_boolish(
                source.get("stop_on_failure"),
                default=False,
            ),
            "remote_operations_enabled": _prompt357_as_boolish(
                source.get("remote_operations_enabled"),
                default=False,
            ),
            "push_pr_merge_enabled": _prompt357_as_boolish(
                source.get("push_pr_merge_enabled"),
                default=False,
            ),
            "rollback_enabled": _prompt357_as_boolish(
                source.get("rollback_enabled"),
                default=False,
            ),
            "next_action_on_success": _normalize_text(
                source.get("next_action_on_success"),
                default="",
            ),
            "next_action_on_blocked": _normalize_text(
                source.get("next_action_on_blocked"),
                default="",
            ),
        }

    def _normalize_prompt368_surface(value: Any) -> dict[str, Any]:
        source = dict(value) if isinstance(value, Mapping) else {}
        return {
            "prompt368_resume_controller_status": _normalize_text(
                source.get("prompt368_resume_controller_status"),
                default="",
            ),
            "prompt368_resume_status": _normalize_text(
                source.get("prompt368_resume_status"),
                default="",
            ),
            "prompt368_next_cycle_resume_contract_ready": _prompt357_as_boolish(
                source.get("prompt368_next_cycle_resume_contract_ready"),
                default=False,
            ),
            "prompt368_integrated_loop_resume_ready": _prompt357_as_boolish(
                source.get("prompt368_integrated_loop_resume_ready"),
                default=False,
            ),
            "prompt368_next_action": _normalize_text(
                source.get("prompt368_next_action"),
                default="",
            ),
            "prompt368_selected_prompt_id": _normalize_text(
                source.get("prompt368_selected_prompt_id"),
                default="",
            ),
            "prompt368_selected_prompt_title": _normalize_text(
                source.get("prompt368_selected_prompt_title"),
                default="",
            ),
            "prompt368_selected_prompt_contract_ready": _prompt357_as_boolish(
                source.get("prompt368_selected_prompt_contract_ready"),
                default=False,
            ),
            "prompt368_selected_prompt_contract_path": _normalize_text(
                source.get("prompt368_selected_prompt_contract_path"),
                default="",
            ),
            "prompt368_active_blocked_reason": _normalize_text(
                source.get("prompt368_active_blocked_reason"),
                default="",
            ),
            "prompt368_active_blocked_reasons": _normalize_string_list(
                source.get("prompt368_active_blocked_reasons"),
                sort_items=False,
            ),
        }

    def _normalize_prompt362_surface(value: Any) -> dict[str, Any]:
        source = dict(value) if isinstance(value, Mapping) else {}
        return {
            "prompt362_review_status": _normalize_text(
                source.get("prompt362_review_status"),
                default="",
            ),
            "prompt362_route_decision": _normalize_text(
                source.get("prompt362_route_decision"),
                default="",
            ),
            "prompt362_review_handoff_ready": _prompt357_as_boolish(
                source.get("prompt362_review_handoff_ready"),
                default=False,
            ),
            "prompt362_requires_targeted_fix": _prompt357_as_boolish(
                source.get("prompt362_requires_targeted_fix"),
                default=False,
            ),
            "prompt362_next_action": _normalize_text(
                source.get("prompt362_next_action"),
                default="",
            ),
            "prompt362_active_blocked_reason": _normalize_text(
                source.get("prompt362_active_blocked_reason"),
                default="",
            ),
            "prompt362_active_blocked_reasons": _normalize_string_list(
                source.get("prompt362_active_blocked_reasons"),
                sort_items=False,
            ),
        }

    def _normalize_legacy_review_route_surface(value: Any) -> dict[str, Any]:
        source = dict(value) if isinstance(value, Mapping) else {}
        return {
            "review_route_status": _normalize_text(
                source.get("project_browser_autonomous_review_route_status"),
                default="",
            ),
            "review_route_decision": _normalize_text(
                source.get("project_browser_autonomous_review_route_decision"),
                default="",
            ),
            "review_route_next_action": _normalize_text(
                source.get("project_browser_autonomous_review_route_next_action"),
                default="",
            ),
            "review_route_should_prepare_targeted_fix": _prompt357_as_boolish(
                source.get("project_browser_autonomous_review_route_should_prepare_targeted_fix"),
                default=False,
            ),
            "targeted_fix_post_reentry_route_status": _normalize_text(
                source.get("project_browser_autonomous_targeted_fix_post_reentry_route_status"),
                default="",
            ),
            "targeted_fix_post_reentry_route_decision": _normalize_text(
                source.get("project_browser_autonomous_targeted_fix_post_reentry_route_decision"),
                default="",
            ),
            "targeted_fix_post_reentry_next_action": _normalize_text(
                source.get("project_browser_autonomous_targeted_fix_post_reentry_next_action"),
                default="",
            ),
            "targeted_fix_post_reentry_targeted_fix_required": _prompt357_as_boolish(
                source.get("project_browser_autonomous_targeted_fix_post_reentry_targeted_fix_required"),
                default=False,
            ),
        }

    def _is_prepare_targeted_fix_action(value: Any) -> bool:
        action = _normalize_text(value, default="")
        return bool(action and action.startswith("prepare_targeted_fix"))

    def _blocked_next_action_for(reason: str) -> str:
        mapping = {
            "prompt368_resume_controller_not_ready": (
                "repair_prompt368_resume_controller_ready_state"
            ),
            "prompt368_resume_status_not_prepared": (
                "repair_prompt368_resume_prepared_state"
            ),
            "prompt368_next_cycle_resume_contract_not_ready": (
                "repair_prompt368_next_cycle_resume_contract"
            ),
            "prompt368_integrated_loop_resume_not_ready": (
                "repair_prompt368_integrated_loop_resume_readiness"
            ),
            "prompt368_next_action_not_prepare_prompt369_targeted_fix_route_integration": (
                "repair_prompt368_next_action_for_prompt369"
            ),
        }
        return mapping.get(
            reason,
            "review_prompt369_targeted_fix_route_integration_blocker",
        )

    prompt369_input = _normalize_prompt369_input(run_state.get("prompt369_input"))
    prompt368_surface = _normalize_prompt368_surface(run_state)
    prompt362_surface = _normalize_prompt362_surface(run_state)
    legacy_review_route_surface = _normalize_legacy_review_route_surface(run_state)

    prompt369_prompt369_input_ready = bool(
        _normalize_text(prompt369_input.get("prompt_id"), default="") == "prompt369"
        and _normalize_text(prompt369_input.get("objective"), default="")
        == "targeted_fix_route_integration"
    )
    prompt369_prompt368_resume_ready = True
    prompt369_prerequisite_blockers: list[str] = []
    if (
        _normalize_text(
            prompt368_surface.get("prompt368_resume_controller_status"),
            default="",
        )
        != "ready"
    ):
        prompt369_prompt368_resume_ready = False
        _append_reason(
            prompt369_prerequisite_blockers,
            "prompt368_resume_controller_not_ready",
        )
    if (
        _normalize_text(prompt368_surface.get("prompt368_resume_status"), default="")
        != "prepared"
    ):
        prompt369_prompt368_resume_ready = False
        _append_reason(
            prompt369_prerequisite_blockers,
            "prompt368_resume_status_not_prepared",
        )
    if not bool(prompt368_surface.get("prompt368_next_cycle_resume_contract_ready", False)):
        prompt369_prompt368_resume_ready = False
        _append_reason(
            prompt369_prerequisite_blockers,
            "prompt368_next_cycle_resume_contract_not_ready",
        )
    if not bool(prompt368_surface.get("prompt368_integrated_loop_resume_ready", False)):
        prompt369_prompt368_resume_ready = False
        _append_reason(
            prompt369_prerequisite_blockers,
            "prompt368_integrated_loop_resume_not_ready",
        )
    if (
        _normalize_text(prompt368_surface.get("prompt368_next_action"), default="")
        != "prepare_prompt369_targeted_fix_route_integration"
    ):
        prompt369_prompt368_resume_ready = False
        _append_reason(
            prompt369_prerequisite_blockers,
            "prompt368_next_action_not_prepare_prompt369_targeted_fix_route_integration",
        )

    targeted_fix_required = False
    targeted_fix_required_evidence_source = "none"
    prompt369_review_route_evidence_status = "absent"
    prompt369_review_route_evidence_decision = "none"
    prompt369_review_route_evidence_next_action = ""

    prompt362_route_decision = _normalize_text(
        prompt362_surface.get("prompt362_route_decision"),
        default="",
    )
    prompt362_next_action = _normalize_text(
        prompt362_surface.get("prompt362_next_action"),
        default="",
    )
    legacy_review_route_decision = _normalize_text(
        legacy_review_route_surface.get("review_route_decision"),
        default="",
    )
    legacy_review_route_next_action = _normalize_text(
        legacy_review_route_surface.get("review_route_next_action"),
        default="",
    )
    legacy_post_reentry_route_decision = _normalize_text(
        legacy_review_route_surface.get("targeted_fix_post_reentry_route_decision"),
        default="",
    )
    legacy_post_reentry_next_action = _normalize_text(
        legacy_review_route_surface.get("targeted_fix_post_reentry_next_action"),
        default="",
    )

    if (
        bool(prompt362_surface.get("prompt362_requires_targeted_fix", False))
        or prompt362_route_decision in {"targeted_fix_required", "targeted_fix"}
        or _is_prepare_targeted_fix_action(prompt362_next_action)
    ):
        targeted_fix_required = True
        targeted_fix_required_evidence_source = "prompt362_review_route_decision"
        prompt369_review_route_evidence_status = _normalize_text(
            prompt362_surface.get("prompt362_review_status"),
            default="available",
        ) or "available"
        prompt369_review_route_evidence_decision = (
            prompt362_route_decision or "targeted_fix_required"
        )
        prompt369_review_route_evidence_next_action = prompt362_next_action
    elif (
        legacy_review_route_decision == "targeted_fix"
        or bool(
            legacy_review_route_surface.get(
                "review_route_should_prepare_targeted_fix",
                False,
            )
        )
        or _is_prepare_targeted_fix_action(legacy_review_route_next_action)
    ):
        targeted_fix_required = True
        targeted_fix_required_evidence_source = "legacy_review_route"
        prompt369_review_route_evidence_status = (
            _normalize_text(
                legacy_review_route_surface.get("review_route_status"),
                default="available",
            )
            or "available"
        )
        prompt369_review_route_evidence_decision = (
            legacy_review_route_decision or "targeted_fix"
        )
        prompt369_review_route_evidence_next_action = legacy_review_route_next_action
    elif (
        bool(
            legacy_review_route_surface.get(
                "targeted_fix_post_reentry_targeted_fix_required",
                False,
            )
        )
        or legacy_post_reentry_route_decision == "targeted_fix"
        or _is_prepare_targeted_fix_action(legacy_post_reentry_next_action)
    ):
        targeted_fix_required = True
        targeted_fix_required_evidence_source = "legacy_targeted_fix_post_reentry"
        prompt369_review_route_evidence_status = (
            _normalize_text(
                legacy_review_route_surface.get(
                    "targeted_fix_post_reentry_route_status"
                ),
                default="available",
            )
            or "available"
        )
        prompt369_review_route_evidence_decision = (
            legacy_post_reentry_route_decision or "targeted_fix"
        )
        prompt369_review_route_evidence_next_action = legacy_post_reentry_next_action
    elif prompt362_route_decision or prompt362_next_action:
        prompt369_review_route_evidence_status = (
            _normalize_text(
                prompt362_surface.get("prompt362_review_status"),
                default="available",
            )
            or "available"
        )
        prompt369_review_route_evidence_decision = (
            prompt362_route_decision or "not_targeted_fix"
        )
        prompt369_review_route_evidence_next_action = prompt362_next_action
    elif legacy_review_route_decision or legacy_review_route_next_action:
        prompt369_review_route_evidence_status = (
            _normalize_text(
                legacy_review_route_surface.get("review_route_status"),
                default="available",
            )
            or "available"
        )
        prompt369_review_route_evidence_decision = (
            legacy_review_route_decision or "not_targeted_fix"
        )
        prompt369_review_route_evidence_next_action = legacy_review_route_next_action
    elif legacy_post_reentry_route_decision or legacy_post_reentry_next_action:
        prompt369_review_route_evidence_status = (
            _normalize_text(
                legacy_review_route_surface.get("targeted_fix_post_reentry_route_status"),
                default="available",
            )
            or "available"
        )
        prompt369_review_route_evidence_decision = (
            legacy_post_reentry_route_decision or "not_targeted_fix"
        )
        prompt369_review_route_evidence_next_action = legacy_post_reentry_next_action

    blockers: list[str] = []
    if not prompt369_prompt368_resume_ready:
        for blocker in prompt369_prerequisite_blockers:
            _append_reason(blockers, blocker)

    prompt369_targeted_fix_route_integrated = not blockers
    prompt369_targeted_fix_route_integration_status = (
        "ready" if prompt369_targeted_fix_route_integrated else "blocked"
    )
    prompt369_targeted_fix_route_status = (
        "prepared" if prompt369_targeted_fix_route_integrated else "not_prepared"
    )
    prompt369_targeted_fix_reentry_contract_ready = bool(
        prompt369_targeted_fix_route_integrated
    )
    prompt369_targeted_fix_reentry_execution_allowed = False
    prompt369_targeted_fix_reentry_execution_attempted = False
    prompt369_targeted_fix_reentry_execution_performed = False
    prompt369_execution_allowed = False
    prompt369_execution_attempted = False
    prompt369_execution_performed = False
    prompt369_codex_execution_performed = False
    prompt369_git_mutation_performed = False
    prompt369_remote_mutation_performed = False
    prompt369_manual_required = False
    prompt369_replan_required = bool(blockers)
    prompt369_active_blocked_reasons = _normalize_string_list(
        blockers,
        sort_items=False,
    )
    prompt369_active_blocked_reason = (
        prompt369_active_blocked_reasons[0]
        if prompt369_active_blocked_reasons
        else ""
    )
    if prompt369_targeted_fix_route_integrated:
        prompt369_authoritative_next_action = (
            "prepare_prompt370_integrated_autonomous_cycle_runner"
        )
        prompt369_next_action = prompt369_authoritative_next_action
        prompt369_summary = (
            "Prompt369 prepared a metadata-only targeted-fix route integration handoff from Prompt368 resume readiness."
        )
        if targeted_fix_required:
            prompt369_summary = (
                "Prompt369 prepared a metadata-only targeted-fix reentry handoff from Prompt368 resume readiness and explicit targeted-fix review-route evidence."
            )
    else:
        prompt369_authoritative_next_action = _blocked_next_action_for(
            prompt369_active_blocked_reason
        )
        prompt369_next_action = prompt369_authoritative_next_action
        prompt369_summary = (
            "Prompt369 is blocked because required Prompt368 resume readiness evidence is missing."
        )

    integration_payload: dict[str, Any] = {
        "prompt369_schema_version": _PROMPT369_SCHEMA_VERSION,
        "prompt369_targeted_fix_route_integration_status": (
            prompt369_targeted_fix_route_integration_status
        ),
        "prompt369_targeted_fix_route_status": prompt369_targeted_fix_route_status,
        "prompt369_source_prompt368_status": _normalize_text(
            prompt368_surface.get("prompt368_resume_controller_status"),
            default="unavailable",
        ),
        "prompt369_source_prompt362_status": _normalize_text(
            prompt362_surface.get("prompt362_review_status"),
            default="unavailable",
        ),
        "prompt369_prompt368_source_path": _normalize_text(
            current_prompt368_source_path,
            default="",
        ),
        "prompt369_prompt362_source_path": _normalize_text(
            current_prompt362_source_path,
            default="",
        ),
        "prompt369_prompt369_input_ready": prompt369_prompt369_input_ready,
        "prompt369_prompt368_resume_ready": prompt369_prompt368_resume_ready,
        "prompt369_targeted_fix_route_integrated": (
            prompt369_targeted_fix_route_integrated
        ),
        "prompt369_targeted_fix_required": targeted_fix_required,
        "prompt369_targeted_fix_required_evidence_source": (
            targeted_fix_required_evidence_source
        ),
        "prompt369_review_route_evidence_status": (
            prompt369_review_route_evidence_status
        ),
        "prompt369_review_route_evidence_decision": (
            prompt369_review_route_evidence_decision
        ),
        "prompt369_review_route_evidence_next_action": (
            prompt369_review_route_evidence_next_action
        ),
        "prompt369_targeted_fix_reentry_contract_ready": (
            prompt369_targeted_fix_reentry_contract_ready
        ),
        "prompt369_targeted_fix_reentry_execution_allowed": (
            prompt369_targeted_fix_reentry_execution_allowed
        ),
        "prompt369_targeted_fix_reentry_execution_attempted": (
            prompt369_targeted_fix_reentry_execution_attempted
        ),
        "prompt369_targeted_fix_reentry_execution_performed": (
            prompt369_targeted_fix_reentry_execution_performed
        ),
        "prompt369_targeted_fix_route_integration_path": str(integration_path),
        "prompt369_targeted_fix_reentry_contract_path": str(reentry_contract_path),
        "prompt369_targeted_fix_route_receipt_path": str(receipt_path),
        "prompt369_execution_allowed": prompt369_execution_allowed,
        "prompt369_execution_attempted": prompt369_execution_attempted,
        "prompt369_execution_performed": prompt369_execution_performed,
        "prompt369_codex_execution_performed": prompt369_codex_execution_performed,
        "prompt369_git_mutation_performed": prompt369_git_mutation_performed,
        "prompt369_remote_mutation_performed": (
            prompt369_remote_mutation_performed
        ),
        "prompt369_authoritative_next_action": prompt369_authoritative_next_action,
        "prompt369_next_action": prompt369_next_action,
        "prompt369_manual_required": prompt369_manual_required,
        "prompt369_replan_required": prompt369_replan_required,
        "prompt369_active_blocked_reason": prompt369_active_blocked_reason,
        "prompt369_active_blocked_reasons": prompt369_active_blocked_reasons,
        "prompt369_summary": prompt369_summary,
    }

    reentry_contract_payload: dict[str, Any] = {
        **integration_payload,
        "local_only": True,
        "remote_operations_enabled": False,
        "push_pr_merge_enabled": False,
        "rollback_enabled": False,
        "codex_reentry_execution_allowed_by_default": False,
        "prompt369_input": dict(prompt369_input),
    }
    receipt_payload: dict[str, Any] = {
        **integration_payload,
        "prompt369_input": dict(prompt369_input),
        "prompt368_source_excerpt": dict(prompt368_surface),
        "prompt362_source_excerpt": dict(prompt362_surface),
        "legacy_review_route_excerpt": dict(legacy_review_route_surface),
    }

    integration_path.parent.mkdir(parents=True, exist_ok=True)
    _write_json(integration_path, integration_payload)
    _write_json(reentry_contract_path, reentry_contract_payload)
    _write_json(receipt_path, receipt_payload)

    return {
        key: value
        for key, value in integration_payload.items()
        if key.startswith("prompt369_")
    }

def _build_prompt370_integrated_autonomous_cycle_runner_state(
    *,
    run_state_payload: Mapping[str, Any] | None,
    run_root: Path | None = None,
    current_prompt368_source_path: str = "",
    current_prompt369_source_path: str = "",
    current_prompt362_source_path: str = "",
    current_prompt363_source_path: str = "",
) -> dict[str, Any]:
    artifact_root = run_root if run_root is not None else Path(".")
    runner_path = artifact_root / "prompt370_integrated_autonomous_cycle_runner.json"
    dispatch_plan_path = artifact_root / "prompt370_next_action_dispatch_plan.json"
    receipt_path = artifact_root / "prompt370_dispatch_receipt.json"
    run_state = dict(run_state_payload or {})

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    def _normalize_prompt368_surface(value: Any) -> dict[str, Any]:
        source = dict(value) if isinstance(value, Mapping) else {}
        return {
            "prompt368_next_cycle_resume_contract_ready": _prompt357_as_boolish(
                source.get("prompt368_next_cycle_resume_contract_ready"),
                default=False,
            ),
            "prompt368_integrated_loop_resume_ready": _prompt357_as_boolish(
                source.get("prompt368_integrated_loop_resume_ready"),
                default=False,
            ),
            "prompt368_resume_iteration_current": _as_non_negative_int(
                source.get("prompt368_resume_iteration_current"),
                default=0,
            ),
            "prompt368_resume_iteration_max": _as_non_negative_int(
                source.get("prompt368_resume_iteration_max"),
                default=0,
            ),
            "prompt368_next_action": _normalize_text(
                source.get("prompt368_next_action"),
                default="",
            ),
            "prompt368_authoritative_next_action": _normalize_text(
                source.get("prompt368_authoritative_next_action"),
                default="",
            ),
        }

    def _normalize_prompt369_surface(value: Any) -> dict[str, Any]:
        source = dict(value) if isinstance(value, Mapping) else {}
        return {
            "prompt369_targeted_fix_route_integration_status": _normalize_text(
                source.get("prompt369_targeted_fix_route_integration_status"),
                default="",
            ),
            "prompt369_targeted_fix_route_status": _normalize_text(
                source.get("prompt369_targeted_fix_route_status"),
                default="",
            ),
            "prompt369_prompt368_resume_ready": _prompt357_as_boolish(
                source.get("prompt369_prompt368_resume_ready"),
                default=False,
            ),
            "prompt369_targeted_fix_route_integrated": _prompt357_as_boolish(
                source.get("prompt369_targeted_fix_route_integrated"),
                default=False,
            ),
            "prompt369_targeted_fix_required": _prompt357_as_boolish(
                source.get("prompt369_targeted_fix_required"),
                default=False,
            ),
            "prompt369_targeted_fix_reentry_contract_ready": _prompt357_as_boolish(
                source.get("prompt369_targeted_fix_reentry_contract_ready"),
                default=False,
            ),
            "prompt369_review_route_evidence_decision": _normalize_text(
                source.get("prompt369_review_route_evidence_decision"),
                default="",
            ),
            "prompt369_review_route_evidence_next_action": _normalize_text(
                source.get("prompt369_review_route_evidence_next_action"),
                default="",
            ),
            "prompt369_next_action": _normalize_text(
                source.get("prompt369_next_action"),
                default="",
            ),
            "prompt369_authoritative_next_action": _normalize_text(
                source.get("prompt369_authoritative_next_action"),
                default="",
            ),
        }

    def _normalize_prompt362_surface(value: Any) -> dict[str, Any]:
        source = dict(value) if isinstance(value, Mapping) else {}
        return {
            "prompt362_route_decision": _normalize_text(
                source.get("prompt362_route_decision"),
                default="",
            ),
            "prompt362_approve_commit_tag_ready": _prompt357_as_boolish(
                source.get("prompt362_approve_commit_tag_ready"),
                default=False,
            ),
            "prompt362_requires_targeted_fix": _prompt357_as_boolish(
                source.get("prompt362_requires_targeted_fix"),
                default=False,
            ),
            "prompt362_next_action": _normalize_text(
                source.get("prompt362_next_action"),
                default="",
            ),
        }

    def _normalize_prompt363_surface(value: Any) -> dict[str, Any]:
        source = dict(value) if isinstance(value, Mapping) else {}
        return {
            "prompt363_boundary_status": _normalize_text(
                source.get("prompt363_boundary_status"),
                default="",
            ),
            "prompt363_approve_commit_tag_plan_ready": _prompt357_as_boolish(
                source.get("prompt363_approve_commit_tag_plan_ready"),
                default=False,
            ),
            "prompt363_next_action": _normalize_text(
                source.get("prompt363_next_action"),
                default="",
            ),
        }

    def _repair_next_action_for(reason: str) -> str:
        mapping = {
            "prompt368_integrated_loop_resume_ready_not_true": (
                "repair_prompt368_integrated_loop_resume_readiness"
            ),
            "prompt368_next_cycle_resume_contract_ready_not_true": (
                "repair_prompt368_next_cycle_resume_contract"
            ),
            "prompt369_targeted_fix_route_integration_status_not_ready": (
                "repair_prompt369_targeted_fix_route_integration_ready_state"
            ),
            "prompt369_targeted_fix_route_status_not_prepared": (
                "repair_prompt369_targeted_fix_route_prepared_state"
            ),
            "prompt369_prompt368_resume_ready_not_true": (
                "repair_prompt369_prompt368_resume_readiness"
            ),
            "prompt369_targeted_fix_route_integrated_not_true": (
                "repair_prompt369_targeted_fix_route_integration"
            ),
            "prompt369_targeted_fix_reentry_contract_ready_not_true": (
                "repair_prompt369_targeted_fix_reentry_contract"
            ),
            "prompt369_next_action_not_prepare_prompt370_integrated_autonomous_cycle_runner": (
                "repair_prompt369_next_action_for_prompt370"
            ),
            "approve_commit_tag_route_not_ready": (
                "repair_prompt363_approve_commit_tag_plan"
            ),
            "continue_next_cycle_route_not_ready": (
                "repair_prompt370_continue_next_cycle_readiness"
            ),
            "no_safe_dispatch_route_selected": (
                "repair_prompt370_dispatch_route_selection"
            ),
        }
        return mapping.get(reason, "review_prompt370_dispatch_blocker")

    prompt368_surface = _normalize_prompt368_surface(run_state)
    prompt369_surface = _normalize_prompt369_surface(run_state)
    prompt362_surface = _normalize_prompt362_surface(run_state)
    prompt363_surface = _normalize_prompt363_surface(run_state)

    ready_evidence_blockers: list[str] = []
    if not bool(prompt368_surface.get("prompt368_integrated_loop_resume_ready", False)):
        _append_reason(
            ready_evidence_blockers,
            "prompt368_integrated_loop_resume_ready_not_true",
        )
    if not bool(prompt368_surface.get("prompt368_next_cycle_resume_contract_ready", False)):
        _append_reason(
            ready_evidence_blockers,
            "prompt368_next_cycle_resume_contract_ready_not_true",
        )
    if (
        _normalize_text(
            prompt369_surface.get("prompt369_targeted_fix_route_integration_status"),
            default="",
        )
        != "ready"
    ):
        _append_reason(
            ready_evidence_blockers,
            "prompt369_targeted_fix_route_integration_status_not_ready",
        )
    if (
        _normalize_text(
            prompt369_surface.get("prompt369_targeted_fix_route_status"),
            default="",
        )
        != "prepared"
    ):
        _append_reason(
            ready_evidence_blockers,
            "prompt369_targeted_fix_route_status_not_prepared",
        )
    if not bool(prompt369_surface.get("prompt369_prompt368_resume_ready", False)):
        _append_reason(
            ready_evidence_blockers,
            "prompt369_prompt368_resume_ready_not_true",
        )
    if not bool(prompt369_surface.get("prompt369_targeted_fix_route_integrated", False)):
        _append_reason(
            ready_evidence_blockers,
            "prompt369_targeted_fix_route_integrated_not_true",
        )
    if not bool(prompt369_surface.get("prompt369_targeted_fix_reentry_contract_ready", False)):
        _append_reason(
            ready_evidence_blockers,
            "prompt369_targeted_fix_reentry_contract_ready_not_true",
        )
    if (
        _normalize_text(prompt369_surface.get("prompt369_next_action"), default="")
        != "prepare_prompt370_integrated_autonomous_cycle_runner"
    ):
        _append_reason(
            ready_evidence_blockers,
            "prompt369_next_action_not_prepare_prompt370_integrated_autonomous_cycle_runner",
        )

    prompt370_prompt368_resume_ready = not any(
        reason.startswith("prompt368_") for reason in ready_evidence_blockers
    )
    prompt370_prompt369_route_ready = not any(
        reason.startswith("prompt369_") for reason in ready_evidence_blockers
    )

    prompt370_targeted_fix_required = bool(
        prompt369_surface.get("prompt369_targeted_fix_required", False)
    )
    prompt370_targeted_fix_route_ready = bool(
        prompt370_prompt369_route_ready
        and prompt369_surface.get("prompt369_targeted_fix_reentry_contract_ready", False)
    )

    prompt370_review_route_decision = _normalize_text(
        prompt369_surface.get("prompt369_review_route_evidence_decision")
        or prompt362_surface.get("prompt362_route_decision"),
        default="",
    )
    prompt370_review_route_next_action = _normalize_text(
        prompt369_surface.get("prompt369_review_route_evidence_next_action")
        or prompt362_surface.get("prompt362_next_action"),
        default="",
    )
    prompt370_current_next_action = _normalize_text(
        prompt369_surface.get("prompt369_next_action")
        or prompt368_surface.get("prompt368_next_action"),
        default="",
    )

    prompt370_approve_route_required = bool(
        (
            _normalize_text(
                prompt362_surface.get("prompt362_route_decision"),
                default="",
            )
            == "approve_commit_tag"
        )
        or bool(prompt362_surface.get("prompt362_approve_commit_tag_ready", False))
        or _normalize_text(
            prompt362_surface.get("prompt362_next_action"),
            default="",
        )
        == "prepare_approve_commit_tag"
    )
    prompt370_approve_route_ready = bool(
        prompt370_approve_route_required
        and bool(prompt362_surface.get("prompt362_approve_commit_tag_ready", False))
        and _normalize_text(
            prompt363_surface.get("prompt363_boundary_status"),
            default="",
        )
        == "ready"
        and bool(prompt363_surface.get("prompt363_approve_commit_tag_plan_ready", False))
    )

    prompt370_continue_next_cycle_ready = bool(
        prompt370_prompt368_resume_ready
        and prompt370_prompt369_route_ready
        and not prompt370_targeted_fix_required
    )

    prompt370_resume_iteration_current = _as_non_negative_int(
        prompt368_surface.get("prompt368_resume_iteration_current"),
        default=0,
    )
    prompt370_resume_iteration_max = _as_non_negative_int(
        prompt368_surface.get("prompt368_resume_iteration_max"),
        default=0,
    )

    prompt370_stop_condition_reasons: list[str] = []
    if _prompt357_as_boolish(run_state.get("global_stop"), default=False):
        _append_reason(prompt370_stop_condition_reasons, "global_stop_true")
    if _prompt357_as_boolish(run_state.get("terminal"), default=False):
        _append_reason(prompt370_stop_condition_reasons, "terminal_true")
    if (
        prompt370_resume_iteration_max > 0
        and prompt370_resume_iteration_current >= prompt370_resume_iteration_max
    ):
        _append_reason(
            prompt370_stop_condition_reasons,
            "prompt368_resume_iteration_limit_reached",
        )
    if prompt370_current_next_action == "manual_review_cycle_complete":
        _append_reason(
            prompt370_stop_condition_reasons,
            "current_next_action_manual_review_cycle_complete",
        )
    prompt370_stop_condition_present = bool(prompt370_stop_condition_reasons)

    prompt370_integrated_autonomous_cycle_runner_status = "blocked"
    prompt370_dispatch_status = "blocked"
    prompt370_dispatch_decision = "blocked"
    prompt370_selected_route = "blocked"
    prompt370_selected_next_action = ""
    prompt370_dispatch_reason = ""
    prompt370_dispatch_blocked_reason = ""
    prompt370_dispatch_blocked_reasons: list[str] = []
    prompt370_next_action_dispatch_ready = False

    if ready_evidence_blockers:
        prompt370_dispatch_blocked_reasons = _normalize_string_list(
            ready_evidence_blockers,
            sort_items=False,
        )
        prompt370_dispatch_blocked_reason = (
            prompt370_dispatch_blocked_reasons[0]
            if prompt370_dispatch_blocked_reasons
            else "prompt370_required_ready_evidence_missing"
        )
        prompt370_selected_next_action = _repair_next_action_for(
            prompt370_dispatch_blocked_reason
        )
        prompt370_dispatch_reason = (
            "Prompt370 blocked dispatch because required Prompt368/Prompt369 ready evidence is missing."
        )
    elif prompt370_stop_condition_present:
        prompt370_integrated_autonomous_cycle_runner_status = "ready"
        prompt370_dispatch_status = "planned"
        prompt370_dispatch_decision = "stop"
        prompt370_selected_route = "stop"
        prompt370_selected_next_action = "manual_review_cycle_complete"
        prompt370_dispatch_reason = (
            "Prompt370 selected the stop route because an explicit stop condition is present."
        )
        prompt370_next_action_dispatch_ready = True
    elif prompt370_targeted_fix_required and prompt370_targeted_fix_route_ready:
        prompt370_integrated_autonomous_cycle_runner_status = "ready"
        prompt370_dispatch_status = "planned"
        prompt370_dispatch_decision = "targeted_fix"
        prompt370_selected_route = "targeted_fix"
        prompt370_selected_next_action = (
            "prepare_prompt371_bounded_one_cycle_execution_wiring"
        )
        prompt370_dispatch_reason = (
            "Prompt370 selected the targeted-fix route from Prompt369 targeted-fix evidence."
        )
        prompt370_next_action_dispatch_ready = True
    elif prompt370_approve_route_required and prompt370_approve_route_ready:
        prompt370_integrated_autonomous_cycle_runner_status = "ready"
        prompt370_dispatch_status = "planned"
        prompt370_dispatch_decision = "approve_commit_tag"
        prompt370_selected_route = "approve_commit_tag"
        prompt370_selected_next_action = (
            "prepare_prompt372_explicit_commit_tag_execution_verification"
        )
        prompt370_dispatch_reason = (
            "Prompt370 selected the approve-commit-tag route from explicit Prompt362/Prompt363 approve evidence."
        )
        prompt370_next_action_dispatch_ready = True
    elif prompt370_approve_route_required and not prompt370_approve_route_ready:
        prompt370_dispatch_blocked_reasons = ["approve_commit_tag_route_not_ready"]
        prompt370_dispatch_blocked_reason = "approve_commit_tag_route_not_ready"
        prompt370_selected_next_action = _repair_next_action_for(
            prompt370_dispatch_blocked_reason
        )
        prompt370_dispatch_reason = (
            "Prompt370 blocked dispatch because approve-commit-tag was required but its ready evidence is incomplete."
        )
    elif prompt370_continue_next_cycle_ready:
        prompt370_integrated_autonomous_cycle_runner_status = "ready"
        prompt370_dispatch_status = "planned"
        prompt370_dispatch_decision = "continue_next_cycle"
        prompt370_selected_route = "continue_next_cycle"
        prompt370_selected_next_action = (
            "prepare_prompt371_bounded_one_cycle_execution_wiring"
        )
        prompt370_dispatch_reason = (
            "Prompt370 selected the next-cycle continuation route from Prompt368 resume readiness and Prompt369 integrated route readiness."
        )
        prompt370_next_action_dispatch_ready = True
    else:
        prompt370_dispatch_blocked_reasons = ["no_safe_dispatch_route_selected"]
        prompt370_dispatch_blocked_reason = "no_safe_dispatch_route_selected"
        prompt370_selected_next_action = _repair_next_action_for(
            prompt370_dispatch_blocked_reason
        )
        prompt370_dispatch_reason = (
            "Prompt370 blocked dispatch because no safe route could be selected from the available metadata."
        )

    if not prompt370_next_action_dispatch_ready:
        prompt370_integrated_autonomous_cycle_runner_status = "blocked"
        prompt370_dispatch_status = "blocked"
        prompt370_dispatch_decision = "blocked"
        prompt370_selected_route = "blocked"

    prompt370_execution_allowed = False
    prompt370_execution_attempted = False
    prompt370_execution_performed = False
    prompt370_codex_execution_allowed = False
    prompt370_codex_execution_attempted = False
    prompt370_codex_execution_performed = False
    prompt370_git_mutation_allowed = False
    prompt370_git_mutation_attempted = False
    prompt370_git_mutation_performed = False
    prompt370_remote_mutation_allowed = False
    prompt370_remote_mutation_attempted = False
    prompt370_remote_mutation_performed = False

    prompt370_authoritative_next_action = _normalize_text(
        prompt370_selected_next_action,
        default="",
    )
    prompt370_next_action = prompt370_authoritative_next_action
    prompt370_active_blocked_reasons = (
        _normalize_string_list(prompt370_dispatch_blocked_reasons, sort_items=False)
        if not prompt370_next_action_dispatch_ready
        else []
    )
    prompt370_active_blocked_reason = (
        prompt370_active_blocked_reasons[0]
        if prompt370_active_blocked_reasons
        else ""
    )
    prompt370_summary = (
        "Prompt370 prepared a metadata-only autonomous cycle dispatch plan without executing Codex, targeted-fix reentry, or git mutation."
    )
    if prompt370_selected_route == "targeted_fix":
        prompt370_summary = (
            "Prompt370 prepared a metadata-only targeted-fix dispatch plan for the next bounded cycle."
        )
    elif prompt370_selected_route == "approve_commit_tag":
        prompt370_summary = (
            "Prompt370 prepared a metadata-only approve-commit-tag dispatch plan for explicit verification follow-up."
        )
    elif prompt370_selected_route == "continue_next_cycle":
        prompt370_summary = (
            "Prompt370 prepared a metadata-only continue-next-cycle dispatch plan for bounded one-cycle execution wiring."
        )
    elif prompt370_selected_route == "stop":
        prompt370_summary = (
            "Prompt370 prepared a metadata-only stop dispatch because an explicit stop condition is present."
        )
    elif prompt370_selected_route == "blocked":
        prompt370_summary = (
            "Prompt370 is blocked because it could not safely dispatch the next route from current metadata."
        )

    route_candidates = {
        "blocked": {
            "eligible": bool(not prompt370_next_action_dispatch_ready),
            "selected_next_action": _normalize_text(
                prompt370_selected_next_action if not prompt370_next_action_dispatch_ready else "",
                default="",
            ),
            "reason": _normalize_text(
                prompt370_dispatch_blocked_reason if not prompt370_next_action_dispatch_ready else "",
                default="",
            ),
        },
        "stop": {
            "eligible": prompt370_stop_condition_present,
            "selected_next_action": "manual_review_cycle_complete",
            "reason": (
                "explicit_stop_condition_present"
                if prompt370_stop_condition_present
                else ""
            ),
        },
        "targeted_fix": {
            "eligible": bool(
                prompt370_targeted_fix_required and prompt370_targeted_fix_route_ready
            ),
            "selected_next_action": "prepare_prompt371_bounded_one_cycle_execution_wiring",
            "reason": (
                "targeted_fix_required_and_route_ready"
                if prompt370_targeted_fix_required and prompt370_targeted_fix_route_ready
                else ""
            ),
        },
        "approve_commit_tag": {
            "eligible": prompt370_approve_route_ready,
            "selected_next_action": (
                "prepare_prompt372_explicit_commit_tag_execution_verification"
            ),
            "reason": (
                "approve_commit_tag_required_and_ready"
                if prompt370_approve_route_ready
                else ""
            ),
        },
        "continue_next_cycle": {
            "eligible": prompt370_continue_next_cycle_ready,
            "selected_next_action": "prepare_prompt371_bounded_one_cycle_execution_wiring",
            "reason": (
                "targeted_fix_not_required_and_resume_ready"
                if prompt370_continue_next_cycle_ready
                else ""
            ),
        },
    }

    state_payload: dict[str, Any] = {
        "prompt370_schema_version": _PROMPT370_SCHEMA_VERSION,
        "prompt370_integrated_autonomous_cycle_runner_status": (
            prompt370_integrated_autonomous_cycle_runner_status
        ),
        "prompt370_prompt368_source_path": _normalize_text(
            current_prompt368_source_path,
            default="",
        ),
        "prompt370_prompt369_source_path": _normalize_text(
            current_prompt369_source_path,
            default="",
        ),
        "prompt370_prompt362_source_path": _normalize_text(
            current_prompt362_source_path,
            default="",
        ),
        "prompt370_prompt363_source_path": _normalize_text(
            current_prompt363_source_path,
            default="",
        ),
        "prompt370_prompt368_resume_ready": prompt370_prompt368_resume_ready,
        "prompt370_prompt369_route_ready": prompt370_prompt369_route_ready,
        "prompt370_targeted_fix_required": prompt370_targeted_fix_required,
        "prompt370_targeted_fix_route_ready": prompt370_targeted_fix_route_ready,
        "prompt370_approve_route_required": prompt370_approve_route_required,
        "prompt370_approve_route_ready": prompt370_approve_route_ready,
        "prompt370_continue_next_cycle_ready": prompt370_continue_next_cycle_ready,
        "prompt370_stop_condition_present": prompt370_stop_condition_present,
        "prompt370_stop_condition_reasons": _normalize_string_list(
            prompt370_stop_condition_reasons,
            sort_items=False,
        ),
        "prompt370_current_next_action": prompt370_current_next_action,
        "prompt370_review_route_decision": prompt370_review_route_decision,
        "prompt370_review_route_next_action": prompt370_review_route_next_action,
        "prompt370_dispatch_status": prompt370_dispatch_status,
        "prompt370_dispatch_decision": prompt370_dispatch_decision,
        "prompt370_selected_route": prompt370_selected_route,
        "prompt370_selected_next_action": prompt370_selected_next_action,
        "prompt370_dispatch_reason": prompt370_dispatch_reason,
        "prompt370_dispatch_blocked_reason": prompt370_dispatch_blocked_reason,
        "prompt370_dispatch_blocked_reasons": _normalize_string_list(
            prompt370_dispatch_blocked_reasons,
            sort_items=False,
        ),
        "prompt370_next_action_dispatch_ready": prompt370_next_action_dispatch_ready,
        "prompt370_integrated_autonomous_cycle_runner_path": str(runner_path),
        "prompt370_next_action_dispatch_plan_path": str(dispatch_plan_path),
        "prompt370_dispatch_receipt_path": str(receipt_path),
        "prompt370_execution_allowed": prompt370_execution_allowed,
        "prompt370_execution_attempted": prompt370_execution_attempted,
        "prompt370_execution_performed": prompt370_execution_performed,
        "prompt370_codex_execution_allowed": prompt370_codex_execution_allowed,
        "prompt370_codex_execution_attempted": (
            prompt370_codex_execution_attempted
        ),
        "prompt370_codex_execution_performed": (
            prompt370_codex_execution_performed
        ),
        "prompt370_git_mutation_allowed": prompt370_git_mutation_allowed,
        "prompt370_git_mutation_attempted": prompt370_git_mutation_attempted,
        "prompt370_git_mutation_performed": prompt370_git_mutation_performed,
        "prompt370_remote_mutation_allowed": prompt370_remote_mutation_allowed,
        "prompt370_remote_mutation_attempted": (
            prompt370_remote_mutation_attempted
        ),
        "prompt370_remote_mutation_performed": (
            prompt370_remote_mutation_performed
        ),
        "prompt370_authoritative_next_action": prompt370_authoritative_next_action,
        "prompt370_next_action": prompt370_next_action,
        "prompt370_active_blocked_reason": prompt370_active_blocked_reason,
        "prompt370_active_blocked_reasons": prompt370_active_blocked_reasons,
        "prompt370_summary": prompt370_summary,
    }
    dispatch_plan_payload: dict[str, Any] = {
        **state_payload,
        "local_only": True,
        "execution_allowed": False,
        "route_candidates": route_candidates,
    }
    receipt_payload: dict[str, Any] = {
        **state_payload,
        "prompt368_source_excerpt": dict(prompt368_surface),
        "prompt369_source_excerpt": dict(prompt369_surface),
        "prompt362_source_excerpt": dict(prompt362_surface),
        "prompt363_source_excerpt": dict(prompt363_surface),
        "route_candidates": route_candidates,
    }

    runner_path.parent.mkdir(parents=True, exist_ok=True)
    _write_json(runner_path, state_payload)
    _write_json(dispatch_plan_path, dispatch_plan_payload)
    _write_json(receipt_path, receipt_payload)

    return {
        key: value
        for key, value in state_payload.items()
        if key.startswith("prompt370_")
    }

def _build_prompt371_bounded_one_cycle_execution_wiring_state(
    *,
    run_state_payload: Mapping[str, Any] | None,
    run_root: Path | None = None,
    current_prompt370_source_path: str = "",
) -> dict[str, Any]:
    artifact_root = run_root if run_root is not None else Path(".")
    wiring_path = artifact_root / "prompt371_bounded_one_cycle_execution_wiring.json"
    plan_path = artifact_root / "prompt371_one_cycle_execution_plan.json"
    selected_step_contract_path = artifact_root / "prompt371_selected_step_contract.json"
    execution_gate_readiness_path = artifact_root / "prompt371_execution_gate_readiness.json"
    receipt_path = artifact_root / "prompt371_wiring_receipt.json"
    run_state = dict(run_state_payload or {})

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    def _normalize_prompt370_surface(value: Any) -> dict[str, Any]:
        source = dict(value) if isinstance(value, Mapping) else {}
        return {
            "prompt370_integrated_autonomous_cycle_runner_status": _normalize_text(
                source.get("prompt370_integrated_autonomous_cycle_runner_status"),
                default="",
            ),
            "prompt370_dispatch_status": _normalize_text(
                source.get("prompt370_dispatch_status"),
                default="",
            ),
            "prompt370_next_action_dispatch_ready": _prompt357_as_boolish(
                source.get("prompt370_next_action_dispatch_ready"),
                default=False,
            ),
            "prompt370_selected_route": _normalize_text(
                source.get("prompt370_selected_route"),
                default="",
            ),
            "prompt370_selected_next_action": _normalize_text(
                source.get("prompt370_selected_next_action"),
                default="",
            ),
            "prompt370_next_action": _normalize_text(
                source.get("prompt370_next_action"),
                default="",
            ),
            "prompt370_authoritative_next_action": _normalize_text(
                source.get("prompt370_authoritative_next_action"),
                default="",
            ),
            "prompt370_active_blocked_reason": _normalize_text(
                source.get("prompt370_active_blocked_reason"),
                default="",
            ),
            "prompt370_active_blocked_reasons": _normalize_string_list(
                source.get("prompt370_active_blocked_reasons"),
                sort_items=False,
            ),
        }

    def _blocked_next_action_for(reason: str) -> str:
        mapping = {
            "prompt370_integrated_autonomous_cycle_runner_status_not_ready": (
                "repair_prompt370_integrated_autonomous_cycle_runner_ready_state"
            ),
            "prompt370_dispatch_status_not_planned": (
                "repair_prompt370_dispatch_plan_state"
            ),
            "prompt370_next_action_dispatch_ready_not_true": (
                "repair_prompt370_next_action_dispatch_readiness"
            ),
            "prompt370_selected_route_blocked": (
                "repair_prompt370_selected_route_before_prompt371"
            ),
            "prompt370_selected_route_stop_not_supported_for_prompt371": (
                "review_stop_route_before_prompt371"
            ),
            "prompt370_selected_route_not_supported_for_prompt371": (
                "repair_prompt370_selected_route_before_prompt371"
            ),
            "prompt370_selected_next_action_not_prompt371_or_safe_prompt372_boundary": (
                "repair_prompt370_selected_next_action_for_prompt371"
            ),
            "prompt370_next_action_not_prompt371_or_safe_prompt372_boundary": (
                "repair_prompt370_next_action_for_prompt371"
            ),
            "prompt370_authoritative_next_action_not_prompt371_or_safe_prompt372_boundary": (
                "repair_prompt370_authoritative_next_action_for_prompt371"
            ),
        }
        return mapping.get(
            reason,
            "review_prompt371_bounded_one_cycle_execution_wiring_blocker",
        )

    def _expected_prompt370_actions_for(route: str) -> set[str]:
        if route == "approve_commit_tag":
            return {
                "prepare_prompt371_bounded_one_cycle_execution_wiring",
                "prepare_prompt372_explicit_commit_tag_execution_verification",
            }
        return {"prepare_prompt371_bounded_one_cycle_execution_wiring"}

    prompt370_surface = _normalize_prompt370_surface(run_state)
    normalized_selected_route = _normalize_text(
        prompt370_surface.get("prompt370_selected_route"),
        default="",
    )
    prompt370_blockers: list[str] = []
    if (
        _normalize_text(
            prompt370_surface.get(
                "prompt370_integrated_autonomous_cycle_runner_status"
            ),
            default="",
        )
        != "ready"
    ):
        _append_reason(
            prompt370_blockers,
            "prompt370_integrated_autonomous_cycle_runner_status_not_ready",
        )
    if (
        _normalize_text(
            prompt370_surface.get("prompt370_dispatch_status"),
            default="",
        )
        != "planned"
    ):
        _append_reason(prompt370_blockers, "prompt370_dispatch_status_not_planned")
    if not bool(prompt370_surface.get("prompt370_next_action_dispatch_ready", False)):
        _append_reason(
            prompt370_blockers,
            "prompt370_next_action_dispatch_ready_not_true",
        )
    if normalized_selected_route == "blocked":
        _append_reason(prompt370_blockers, "prompt370_selected_route_blocked")
    elif normalized_selected_route == "stop":
        _append_reason(
            prompt370_blockers,
            "prompt370_selected_route_stop_not_supported_for_prompt371",
        )
    elif normalized_selected_route not in {
        "continue_next_cycle",
        "targeted_fix",
        "approve_commit_tag",
    }:
        _append_reason(
            prompt370_blockers,
            "prompt370_selected_route_not_supported_for_prompt371",
        )

    expected_prompt370_actions = _expected_prompt370_actions_for(
        normalized_selected_route
    )
    if (
        expected_prompt370_actions
        and _normalize_text(
            prompt370_surface.get("prompt370_selected_next_action"),
            default="",
        )
        not in expected_prompt370_actions
    ):
        _append_reason(
            prompt370_blockers,
            "prompt370_selected_next_action_not_prompt371_or_safe_prompt372_boundary",
        )
    if (
        expected_prompt370_actions
        and _normalize_text(prompt370_surface.get("prompt370_next_action"), default="")
        not in expected_prompt370_actions
    ):
        _append_reason(
            prompt370_blockers,
            "prompt370_next_action_not_prompt371_or_safe_prompt372_boundary",
        )
    if (
        expected_prompt370_actions
        and _normalize_text(
            prompt370_surface.get("prompt370_authoritative_next_action"),
            default="",
        )
        not in expected_prompt370_actions
    ):
        _append_reason(
            prompt370_blockers,
            "prompt370_authoritative_next_action_not_prompt371_or_safe_prompt372_boundary",
        )

    prompt371_prompt370_dispatch_ready = not prompt370_blockers
    prompt371_cycle_index = _as_non_negative_int(
        run_state.get("prompt368_resume_iteration_current"),
        default=_LOCAL_AUTONOMOUS_CYCLE_V2_CURRENT_CYCLE,
    )
    if prompt371_cycle_index <= 0:
        prompt371_cycle_index = _LOCAL_AUTONOMOUS_CYCLE_V2_CURRENT_CYCLE
    prompt371_max_cycles = 1

    prompt371_bounded_one_cycle_execution_wiring_status = "blocked"
    prompt371_one_cycle_plan_status = "blocked"
    prompt371_selected_route = "blocked"
    prompt371_selected_step_id = 0
    prompt371_selected_step_kind = "blocked"
    prompt371_selected_step_operation = "blocked"
    prompt371_selected_prompt_contract_id = ""
    prompt371_selected_next_action = ""
    prompt371_one_cycle_plan_ready = False
    prompt371_selected_prompt_contract_ready = False
    prompt371_execution_gate_ready = False

    if prompt371_prompt370_dispatch_ready:
        prompt371_bounded_one_cycle_execution_wiring_status = "ready"
        prompt371_one_cycle_plan_status = "planned"
        prompt371_selected_route = normalized_selected_route
        prompt371_one_cycle_plan_ready = True
        prompt371_selected_prompt_contract_ready = True
        prompt371_execution_gate_ready = True
        if normalized_selected_route == "continue_next_cycle":
            prompt371_selected_step_id = 1
            prompt371_selected_step_kind = "bounded_one_cycle"
            prompt371_selected_step_operation = (
                "prepare_selected_step_execution_gate"
            )
            prompt371_selected_prompt_contract_id = (
                "prompt372_selected_step_execution_gate"
            )
            prompt371_selected_next_action = (
                "prepare_prompt372_selected_step_execution_gate"
            )
        elif normalized_selected_route == "targeted_fix":
            prompt371_selected_step_id = 2
            prompt371_selected_step_kind = "targeted_fix_bounded_one_cycle"
            prompt371_selected_step_operation = (
                "prepare_selected_step_execution_gate"
            )
            prompt371_selected_prompt_contract_id = (
                "prompt372_selected_step_execution_gate"
            )
            prompt371_selected_next_action = (
                "prepare_prompt372_selected_step_execution_gate"
            )
        else:
            prompt371_selected_step_id = 3
            prompt371_selected_step_kind = "explicit_commit_tag_verification"
            prompt371_selected_step_operation = (
                "prepare_explicit_commit_tag_execution_verification"
            )
            prompt371_selected_prompt_contract_id = (
                "prompt372_explicit_commit_tag_execution_verification"
            )
            prompt371_selected_next_action = (
                "prepare_prompt372_explicit_commit_tag_execution_verification"
            )
    else:
        prompt371_selected_next_action = _blocked_next_action_for(
            prompt370_blockers[0]
            if prompt370_blockers
            else "prompt370_selected_route_not_supported_for_prompt371"
        )

    prompt371_execution_allowed = False
    prompt371_execution_attempted = False
    prompt371_execution_performed = False
    prompt371_codex_execution_allowed = False
    prompt371_codex_execution_attempted = False
    prompt371_codex_execution_performed = False
    prompt371_git_mutation_allowed = False
    prompt371_git_mutation_attempted = False
    prompt371_git_mutation_performed = False
    prompt371_remote_mutation_allowed = False
    prompt371_remote_mutation_attempted = False
    prompt371_remote_mutation_performed = False
    prompt371_authoritative_next_action = _normalize_text(
        prompt371_selected_next_action,
        default="",
    )
    prompt371_next_action = prompt371_authoritative_next_action
    prompt371_active_blocked_reasons = (
        _normalize_string_list(prompt370_blockers, sort_items=False)
        if not prompt371_prompt370_dispatch_ready
        else []
    )
    prompt371_active_blocked_reason = (
        prompt371_active_blocked_reasons[0]
        if prompt371_active_blocked_reasons
        else ""
    )
    prompt371_summary = (
        "Prompt371 is blocked because Prompt370 dispatch evidence is incomplete or not safe for bounded one-cycle execution wiring."
    )
    if prompt371_selected_route == "continue_next_cycle":
        prompt371_summary = (
            "Prompt371 prepared a metadata-only bounded one-cycle execution wiring handoff for continue-next-cycle up to the Prompt372 selected-step execution gate."
        )
    elif prompt371_selected_route == "targeted_fix":
        prompt371_summary = (
            "Prompt371 prepared a metadata-only bounded one-cycle execution wiring handoff for the targeted-fix route up to the Prompt372 selected-step execution gate."
        )
    elif prompt371_selected_route == "approve_commit_tag":
        prompt371_summary = (
            "Prompt371 prepared a metadata-only bounded one-cycle execution wiring handoff for explicit commit/tag verification without executing git."
        )

    state_payload: dict[str, Any] = {
        "prompt371_schema_version": _PROMPT371_SCHEMA_VERSION,
        "prompt371_bounded_one_cycle_execution_wiring_status": (
            prompt371_bounded_one_cycle_execution_wiring_status
        ),
        "prompt371_one_cycle_plan_status": prompt371_one_cycle_plan_status,
        "prompt371_prompt370_source_path": _normalize_text(
            current_prompt370_source_path,
            default="",
        ),
        "prompt371_prompt370_dispatch_ready": prompt371_prompt370_dispatch_ready,
        "prompt371_selected_route": prompt371_selected_route,
        "prompt371_selected_step_id": prompt371_selected_step_id,
        "prompt371_selected_step_kind": prompt371_selected_step_kind,
        "prompt371_selected_step_operation": prompt371_selected_step_operation,
        "prompt371_selected_prompt_contract_id": (
            prompt371_selected_prompt_contract_id
        ),
        "prompt371_selected_next_action": prompt371_selected_next_action,
        "prompt371_one_cycle_plan_ready": prompt371_one_cycle_plan_ready,
        "prompt371_selected_prompt_contract_ready": (
            prompt371_selected_prompt_contract_ready
        ),
        "prompt371_execution_gate_ready": prompt371_execution_gate_ready,
        "prompt371_cycle_index": prompt371_cycle_index,
        "prompt371_max_cycles": prompt371_max_cycles,
        "prompt371_bounded_one_cycle_execution_wiring_path": str(wiring_path),
        "prompt371_one_cycle_execution_plan_path": str(plan_path),
        "prompt371_selected_step_contract_path": str(selected_step_contract_path),
        "prompt371_execution_gate_readiness_path": str(
            execution_gate_readiness_path
        ),
        "prompt371_wiring_receipt_path": str(receipt_path),
        "prompt371_execution_allowed": prompt371_execution_allowed,
        "prompt371_execution_attempted": prompt371_execution_attempted,
        "prompt371_execution_performed": prompt371_execution_performed,
        "prompt371_codex_execution_allowed": prompt371_codex_execution_allowed,
        "prompt371_codex_execution_attempted": (
            prompt371_codex_execution_attempted
        ),
        "prompt371_codex_execution_performed": (
            prompt371_codex_execution_performed
        ),
        "prompt371_git_mutation_allowed": prompt371_git_mutation_allowed,
        "prompt371_git_mutation_attempted": prompt371_git_mutation_attempted,
        "prompt371_git_mutation_performed": prompt371_git_mutation_performed,
        "prompt371_remote_mutation_allowed": prompt371_remote_mutation_allowed,
        "prompt371_remote_mutation_attempted": (
            prompt371_remote_mutation_attempted
        ),
        "prompt371_remote_mutation_performed": (
            prompt371_remote_mutation_performed
        ),
        "prompt371_authoritative_next_action": (
            prompt371_authoritative_next_action
        ),
        "prompt371_next_action": prompt371_next_action,
        "prompt371_active_blocked_reason": prompt371_active_blocked_reason,
        "prompt371_active_blocked_reasons": prompt371_active_blocked_reasons,
        "prompt371_summary": prompt371_summary,
    }
    plan_payload: dict[str, Any] = {
        **state_payload,
        "local_only": True,
        "plan_kind": "bounded_one_cycle_execution_wiring",
    }
    selected_step_contract_payload: dict[str, Any] = {
        **state_payload,
        "local_only": True,
        "contract_status": prompt371_one_cycle_plan_status,
        "source_prompt": "prompt371",
        "source_action": "prepare_prompt371_bounded_one_cycle_execution_wiring",
        "selected_step_constraints": [
            "metadata-only",
            "execution remains disabled",
            "no Codex invocation",
            "no git mutation",
            "no remote operations",
            "max_cycles must remain 1",
        ],
    }
    execution_gate_readiness_payload: dict[str, Any] = {
        **state_payload,
        "local_only": True,
        "execution_gate_status": (
            "ready" if prompt371_execution_gate_ready else "blocked"
        ),
    }
    receipt_payload: dict[str, Any] = {
        **state_payload,
        "prompt370_source_excerpt": dict(prompt370_surface),
    }

    wiring_path.parent.mkdir(parents=True, exist_ok=True)
    _write_json(wiring_path, state_payload)
    _write_json(plan_path, plan_payload)
    _write_json(selected_step_contract_path, selected_step_contract_payload)
    _write_json(execution_gate_readiness_path, execution_gate_readiness_payload)
    _write_json(receipt_path, receipt_payload)

    return {
        key: value
        for key, value in state_payload.items()
        if key.startswith("prompt371_")
    }

def _build_prompt372_selected_step_execution_gate_state(
    *,
    run_state_payload: Mapping[str, Any] | None,
    run_root: Path | None = None,
    current_prompt371_source_path: str = "",
) -> dict[str, Any]:
    artifact_root = run_root if run_root is not None else Path(".")
    gate_path = artifact_root / "prompt372_selected_step_execution_gate.json"
    request_contract_path = artifact_root / "prompt372_codex_execution_request_contract.json"
    preflight_receipt_path = (
        artifact_root / "prompt372_live_execution_preflight_receipt.json"
    )
    receipt_path = artifact_root / "prompt372_gate_receipt.json"
    run_state = dict(run_state_payload or {})

    def _append_reason(reasons: list[str], reason: str) -> None:
        normalized_reason = _normalize_text(reason, default="")
        if normalized_reason and normalized_reason not in reasons:
            reasons.append(normalized_reason)

    prompt371_surface = {
        "prompt371_bounded_one_cycle_execution_wiring_status": _normalize_text(
            run_state.get("prompt371_bounded_one_cycle_execution_wiring_status"),
            default="",
        ),
        "prompt371_one_cycle_plan_status": _normalize_text(
            run_state.get("prompt371_one_cycle_plan_status"),
            default="",
        ),
        "prompt371_prompt370_dispatch_ready": _prompt357_as_boolish(
            run_state.get("prompt371_prompt370_dispatch_ready"),
            default=False,
        ),
        "prompt371_selected_route": _normalize_text(
            run_state.get("prompt371_selected_route"),
            default="",
        ),
        "prompt371_selected_step_kind": _normalize_text(
            run_state.get("prompt371_selected_step_kind"),
            default="",
        ),
        "prompt371_selected_step_operation": _normalize_text(
            run_state.get("prompt371_selected_step_operation"),
            default="",
        ),
        "prompt371_selected_next_action": _normalize_text(
            run_state.get("prompt371_selected_next_action"),
            default="",
        ),
        "prompt371_one_cycle_plan_ready": _prompt357_as_boolish(
            run_state.get("prompt371_one_cycle_plan_ready"),
            default=False,
        ),
        "prompt371_selected_prompt_contract_ready": _prompt357_as_boolish(
            run_state.get("prompt371_selected_prompt_contract_ready"),
            default=False,
        ),
        "prompt371_execution_gate_ready": _prompt357_as_boolish(
            run_state.get("prompt371_execution_gate_ready"),
            default=False,
        ),
        "prompt371_max_cycles": _as_non_negative_int(
            run_state.get("prompt371_max_cycles"),
            default=0,
        ),
        "prompt371_next_action": _normalize_text(
            run_state.get("prompt371_next_action"),
            default="",
        ),
        "prompt371_selected_step_contract_path": _normalize_text(
            run_state.get("prompt371_selected_step_contract_path"),
            default="",
        ),
        "prompt371_execution_gate_readiness_path": _normalize_text(
            run_state.get("prompt371_execution_gate_readiness_path"),
            default="",
        ),
        "prompt371_wiring_receipt_path": _normalize_text(
            run_state.get("prompt371_wiring_receipt_path"),
            default="",
        ),
        "prompt371_active_blocked_reason": _normalize_text(
            run_state.get("prompt371_active_blocked_reason"),
            default="",
        ),
        "prompt371_active_blocked_reasons": _normalize_string_list(
            run_state.get("prompt371_active_blocked_reasons"),
            sort_items=False,
        ),
    }

    prompt372_gate_blocked_reasons: list[str] = []
    if (
        prompt371_surface["prompt371_bounded_one_cycle_execution_wiring_status"]
        != "ready"
    ):
        _append_reason(
            prompt372_gate_blocked_reasons,
            "prompt371_bounded_one_cycle_execution_wiring_status_not_ready",
        )
    if prompt371_surface["prompt371_one_cycle_plan_status"] != "planned":
        _append_reason(
            prompt372_gate_blocked_reasons,
            "prompt371_one_cycle_plan_status_not_planned",
        )
    if not bool(prompt371_surface["prompt371_prompt370_dispatch_ready"]):
        _append_reason(
            prompt372_gate_blocked_reasons,
            "prompt371_prompt370_dispatch_ready_not_true",
        )
    if prompt371_surface["prompt371_selected_route"] not in {
        "continue_next_cycle",
        "targeted_fix",
        "approve_commit_tag",
    }:
        _append_reason(
            prompt372_gate_blocked_reasons,
            "prompt371_selected_route_not_supported_for_prompt372",
        )
    if not prompt371_surface["prompt371_selected_step_kind"]:
        _append_reason(
            prompt372_gate_blocked_reasons,
            "prompt371_selected_step_kind_missing",
        )
    if (
        prompt371_surface["prompt371_selected_step_operation"]
        != "prepare_selected_step_execution_gate"
    ):
        _append_reason(
            prompt372_gate_blocked_reasons,
            "prompt371_selected_step_operation_not_prepare_selected_step_execution_gate",
        )
    if (
        prompt371_surface["prompt371_selected_next_action"]
        != "prepare_prompt372_selected_step_execution_gate"
    ):
        _append_reason(
            prompt372_gate_blocked_reasons,
            "prompt371_selected_next_action_not_prepare_prompt372_selected_step_execution_gate",
        )
    if not bool(prompt371_surface["prompt371_one_cycle_plan_ready"]):
        _append_reason(
            prompt372_gate_blocked_reasons,
            "prompt371_one_cycle_plan_ready_not_true",
        )
    if not bool(prompt371_surface["prompt371_selected_prompt_contract_ready"]):
        _append_reason(
            prompt372_gate_blocked_reasons,
            "prompt371_selected_prompt_contract_ready_not_true",
        )
    if not bool(prompt371_surface["prompt371_execution_gate_ready"]):
        _append_reason(
            prompt372_gate_blocked_reasons,
            "prompt371_execution_gate_ready_not_true",
        )
    if prompt371_surface["prompt371_max_cycles"] != 1:
        _append_reason(
            prompt372_gate_blocked_reasons,
            "prompt371_max_cycles_not_equal_1",
        )
    if (
        prompt371_surface["prompt371_next_action"]
        != "prepare_prompt372_selected_step_execution_gate"
    ):
        _append_reason(
            prompt372_gate_blocked_reasons,
            "prompt371_next_action_not_prepare_prompt372_selected_step_execution_gate",
        )

    prompt372_selected_step_execution_gate_status = "blocked"
    prompt372_gate_status = "blocked"
    prompt372_prompt371_wiring_ready = False
